# Shared auth-dependency signal for the route-authorization guards (bola,
# privileged-field-assignment, unauthenticated-file-download). A `Depends(...)` counts as an
# authorization signal ONLY when the injected callable's name looks like auth
# (`Depends(get_current_user)`, `Depends(require_admin)`, `Depends(oauth2_scheme)`) — NOT a bare
# `Depends(get_db)` / `Depends(get_pagination)`, which are non-auth dependencies (issue #307).
# FastAPI's `Security(...)` is auth-by-construction (security schemes/scopes), so guards keep it as
# a bare signal separately. Deliberately excludes a bare `session` token: `Depends(get_session)` is
# overwhelmingly a DB session in a FastAPI app, the exact non-auth case this fixes.
# Auth-ish identifier stems, matched at identifier-segment boundaries so a stem cannot bleed into an
# ordinary word (`auth`⊄`author`, `token`⊄`tokenizer`, `scope`⊄`telescope`, `require`⊄`required` —
# issue #307). The stems are matched case-insensitively by the guards, but the boundaries are
# case-SENSITIVE via scoped `(?-i:...)` flags: a plain `(?![a-z])` under the guards' `re.IGNORECASE`
# would fold to "not any letter" and reject the UpperCamel next-segment of an alias like
# `AdminReadDep`. So `_SEG_*` reject only a *lowercase* neighbour — `_`, `)`, a digit, an UpperCamel
# segment, or the string edge all still count as a boundary.
_SEG_BEFORE = r"(?-i:(?<![a-z]))"
_SEG_AFTER = r"(?-i:(?![a-z]))"
# Prefix stems: long, unambiguous auth words whose auth derivations continue in lowercase
# (`oauth2`, `authenticate`, `authorization`, `administrator`, `permissions`) — boundaried left only.
_AUTH_PREFIX_STEMS = r"oauth|authenticat|authoriz|admin|permission|security|credential"
# Segment stems: short enough to be a substring of an ordinary word — boundaried on both sides.
_AUTH_SEGMENT_STEMS = r"auth|token|scope|role|user|require|login|verify|current"


# === helpers: Auth-name matching ============================================================================
def boundaried_stems(segment_stems: str, prefix_stems: str = "") -> str:
    """Boundary-anchor an alternation of identifier stems so a stem can't bleed into an ordinary word.

    ``segment_stems`` (a bare ``|``-joined alternation) are short words that can be a substring of an
    ordinary word, so they are boundaried on BOTH sides and take an OPTIONAL trailing plural `s`:
    `scope`⊄`telescope` and `require`⊄`required` (issue #307), but `scopes`/`roles` still match
    (issue #345). ``prefix_stems`` are long, unambiguous auth words whose derivations continue in
    lowercase (`authorization`, `permissions`), boundaried on the LEFT only so their plurals already
    work and take no `s?`.

    Each call site passes exactly the vocabulary it wants — the shared ``_AUTH_NAME`` uses the full
    auth stem lists (below), while a guard-local matcher (e.g. bola's body-text suppressor) passes
    only its own narrow set. Deliberately NOT an "extend the shared list" escape hatch: a guard that
    scans free body text must not silently inherit the whole ``Depends(...)``-naming vocabulary
    (issue #345 review — that over-suppressed genuine findings on incidental `token`/`role`/`user`).
    """
    body = ""
    if prefix_stems:
        body += prefix_stems + r"|"
    body += r"(?:" + segment_stems + r")s?" + _SEG_AFTER
    return _SEG_BEFORE + r"(?:" + body + r")"


# The shared boundaried matcher — a prefix stem, or a segment stem closed on the right.
_AUTH_NAME = boundaried_stems(_AUTH_SEGMENT_STEMS, _AUTH_PREFIX_STEMS)

# `Depends(<auth-ish callable>)` — the injected callable's name carries an auth stem.
#
# RESIDUAL GAP, accepted (review): the `[\w.]*` prefix cannot cross a `(` or a `[`, so the
# auth stem is only recognized in the FIRST token after `Depends(`. A genuine auth callable hidden
# one level deeper behind a non-auth-named wrapper therefore reads as NON-auth, and the guards that
# consume this via `AUTH_CALL_NAMED` fire on a correctly-authed route:
#     Depends(functools.partial(require_role, "admin"))   -> not recognized (false positive)
#     Depends(Provide[Container.auth_service])            -> not recognized (false positive)
#                                                            (`dependency-injector`'s FastAPI wiring)
# `Depends(Security(get_current_user, scopes=["me"]))` survives only because `Security` is itself an
# auth stem, which is what keeps the class narrower than "any nested call".
#
# This is the COST SIDE of NAMED auth, not a regression: before it, ANY `Depends(...)` counted as auth,
# so these two shapes were silent by accident — via the same hole that let a route carrying only
# `Depends(RateLimiter(...))` read as authenticated. One broad false-NEGATIVE class was traded for
# this much narrower false-POSITIVE one. Pinned by `test_wrapper_hidden_auth_dep_is_known_limitation`
# in the `auth-dependency-not-applied` and `websocket-no-auth` test files, so a future change here is
# intentional and visible.
#
# Do NOT close this by widening the prefix to look past a wrapper: that reopens the "any call counts"
# hole the NAMED-auth tightening closes (`Depends(get_db(user_scoped=True))` would go silent), and the regex
# is shared by four route-auth guards. It wants the real argument resolver — the open tail.
AUTH_DEPENDS_SIGNAL = r"\bDepends\s*\(\s*[\w.]*" + _AUTH_NAME

# Auth-dependency ALIAS: FastAPI's idiomatic module-level DI alias used as a parameter
# default/annotation — `admin = AdminReadDep` where `AdminReadDep = Depends(verify_admin)` is defined
# elsewhere, or `user: CurrentUser` where `CurrentUser = Annotated[..., Depends(get_current_user)]`.
# The guard scans one function block and can't see the alias's definition, so recognize an auth-ish
# identifier ending in `Dep`/`Depends`. Deliberately requires an auth stem so a bare DB alias
# (`DbDep`, `SessionDep`) still fires (issue #307 flagship validation).
AUTH_DEP_ALIAS = r"\b\w*" + _AUTH_NAME + r"\w*Dep(?:ends)?\b"

# The two fragments combined — the three route-authorization guards use this identically.
AUTH_DEP_SIGNAL = AUTH_DEPENDS_SIGNAL + r"|" + AUTH_DEP_ALIAS

# An LLM-invocation call site: Pydantic-AI (`.run`/`.run_sync`), OpenAI (`chat.completions.create` /
# `responses.create`), LangChain (`.invoke`/`.predict`), and generic `.complete`/`.chat`. Shared by
# three guards in three roles: `input-delimiters` uses it as the finding's ANCHOR, `rag-trust-boundary`
# as half of a PRECONDITION, and `prompt-string-interp` as a per-file GATE and same-line prompt
# context.
# It is defined once, here, because the three hand-kept copies drifted apart twice while a comment
# kept them "identical": d04ca120 narrowed the bare `.run(` arm in prompt-string-interp only (found
# in #717), and #717's fix to the other two copies never reached prompt-string-interp (found in
# #726). A pin that compared two of the copies let the third drift unseen, so
# `tests/guards/test_base.py` now fails if any guard module carries a runner exclusion of its own.
# Anthropic's `messages.create(` is deliberately NOT here. As an anchor or a precondition it also
# matches the same method on a Twilio, ORM or queue client, and no FP-bait can separate those from
# Anthropic by this shape (#717). prompt-string-interp ORs it in locally, as a widening of its own.
# (No receiver is written before it in these comments on purpose: `string-format-injection` gates on
# `<receiver>.messages.create(` text, so writing one would make the self-audit scan a guard module's
# own docstring examples.)
# The bare `.run(` form EXCLUDES process / event-loop / web / test runners by receiver. They are not
# LLM calls, and an unconstrained `.run(` made them the dominant false match: `subprocess.run(` inside
# a `.claude/` skill reference and `uvicorn.run(app, ...)` in the flagship's `agent_api.py` were both
# reported as "the LLM call site" (#717), and `uvicorn.run(` alone opened prompt-string-interp's gate
# in a file that never calls a model (#726).
# Receiver-scoped deliberately: `agent.run(...)` / `title_agent.run(...)` are REAL pydantic-ai calls
# and must keep matching. Each guard's planted-violation tests pin that, since this is a narrowing
# (Rule 1).
# The leading `\b` in each lookbehind is load-bearing, not decoration. A bare `(?<!subprocess)` only
# asserts that the 10 characters before the `.` are not `subprocess`; it does NOT require them to
# START an identifier, so every receiver merely ENDING in an excluded word was swallowed too:
# `my_subprocess.run(`, `fake_asyncio.run(`, `detox.run(`, `equinox.run(` (#725 review). That is
# worse than a false match: a suppressed call site makes a guard go silent on a real gap, which is
# Rule 3's "failure that presents as success". `\b` is zero-width, so the lookbehinds stay
# fixed-width and still compile.
# Residuals, accepted (each guard's design doc lists them under Known bypasses):
#   * a dotted attribute receiver (`self.subprocess.run(...)`) is still excluded. That is inherent to
#     matching a receiver by regex, and it is the narrower case.
#   * a newline between receiver and call (`asyncio\n.run(...)`) defeats the lookbehind, so that form
#     still matches.
#   * nox's own idiom `session.run("pytest")` still matches, and a top-level `noxfile.py` counts as
#     product code. The receiver there is `session`, so the `nox` exclusion never sees it.
LLM_CALL = re.compile(
    r"\.run_sync\s*\(|"
    r"(?<!\basyncio)(?<!\bsubprocess)(?<!\btrio)(?<!\banyio)(?<!\buvicorn)(?<!\bgunicorn)"
    r"(?<!\bunittest)(?<!\bpytest)(?<!\bnox)(?<!\btox)\.run\s*\(|"
    r"\.complete\s*\(|\.chat\s*\(|"
    r"chat\.completions\.create\s*\(|responses\.create\s*\(|\.predict\s*\(|"
    r"\.invoke\s*\(",
    re.IGNORECASE,
)

# The OpenAI / Anthropic SDK `create` call SHAPE: `chat.completions`, `completions`, `responses` or
# `messages`, then `.create(`. It only nominates a CANDIDATE. `is_llm_sdk_create_call` below decides
# whether the candidate is an SDK call.
# The shape is not proof on its own, because none of these four method paths belongs only to an LLM
# SDK (#561). A Django reverse relation (`related_name="responses"`) gets `responses.create` for free.
# Twilio sends an SMS with `messages.create` and `body=`, `from_=`, `to=`, on a receiver conventionally
# named `client`. Webex bots have the same method. #717 hit the same wall and kept `messages.create`
# out of `LLM_CALL` above. No receiver allowlist fixes it either: in a ~370-site code-search sample,
# `client` was the receiver of most OpenAI calls AND of most Twilio ones.
# What does separate them is the ARGUMENTS. Every SDK `create` is keyword-only (`def create(self, *,
# ...)`), so a real call names its arguments the SDK's way (`model=`, or a `**` spread of them), and
# a Twilio, ORM or Webex call never does.
# Defined once, here: two guards each kept their own enumeration of these method paths, and the two
# disagreed in both membership and prefix strictness (#561). `tests/guards/test_base.py` pins that both
# import this one.
# (No receiver is written before these shapes in this comment, for the reason given on `LLM_CALL`.)
LLM_SDK_CREATE = re.compile(
    r"\.(?:chat\.completions|completions|responses|messages)\.create\s*\(",
    re.IGNORECASE,
)

# A top-level argument only an SDK `create` spells.
#   * `model=` and a `**` spread come from the keyword-only signature itself.
#   * `messages=` is the conversation every chat-completions and Anthropic messages call sends. It is
#     what an instructor `from_provider(...)` client still passes once the model moved to the provider
#     string and `model=` is gone.
#   * `prompt=` is a stored-prompt template that carries its own model, and `extra_body=` is an Azure
#     AI Foundry agent reference. Those are `responses.create`'s two model-less forms (#561 sample).
# Deliberately NOT accepted: `input=`, a field name an ORM row plausibly has, and a bare `*args`, which
# a keyword-only `create` would reject at runtime.
_LLM_SDK_CREATE_ARG = re.compile(r"\s*(?:\*\*|(?:model|messages|prompt|extra_body)\s*=(?!=))")


@dataclass(frozen=True)
class CanaryPlant:
    """A guard's own declaration of its liveness-canary plant — the canonical plant site.

    `agentsec/canary.py` assembles the generated canary repo by unioning its shrinking base
    monolith with every guard's `canary_plant`, so a guard's plant lives next to the guard
    instead of in a shared 3,700-line file that every concurrent branch appends to.

    `files` maps a canary-repo relative path to its **verbatim** content. `expects` is the set
    of rule ids that plant must make fire. A rule counts as fired from ANY file in the canary
    repo, so `expects` cannot pin a file surface: a surface added to an existing rule needs a unit
    test that names it by a literal path (#632). A guard whose violation is planted in a shared
    scaffolding file (`app.py`, `sql/schema.sql`, …) declares `expects` ONLY and leaves the file
    in the canary base — such a file is owned by no single guard.

    The planted strings are load-bearing: a plant that happens to contain another guard's global
    suppressor marker silences THAT guard repo-wide. `tests/test_canary.py` enforces this and
    names any offender; document a plant's FIRE-strings in a comment directly above it.
    """

    files: Mapping[str, str] = field(default_factory=dict)
    expects: frozenset[str] = frozenset()


class Guard:
    """A static guard. Subclasses set `id`/`title` and implement `applies`/`run`."""

    id: str = ""
    title: str = ""
    # The guard's liveness-canary plant, when declared here rather than in `canary.py`'s base
    # (see `CanaryPlant`). `None` means the plant still lives in the canary base — both
    # mechanisms are supported; `agentsec doctor --canary` discloses the split at runtime.
    canary_plant: CanaryPlant | None = None
    # Reporting metadata the check declares about itself, read through `registry.check_meta()`.
    # Central id-keyed maps in `findings.py`/`registry.py` used to answer these at a distance from
    # the check that knows the answer; #617 proved the declaration belongs here (BB4).
    area: str = UNDECLARED_AREA          # a value from `checkmeta.AREA_ORDER`; required
    tier: Tier = "stack"                 # "baseline" = universal hygiene, independent of stack
    surfacing: bool = False              # flags an architecture for review, does not prove a bug
    surfacing_rule_prefixes: tuple[str, ...] = ()   # per-RULE surfacing, when the whole check is not
    schema_state: bool = False           # reads `.sql` as schema state, so a dump can supersede it

    def applies(self, profile: StackProfile) -> bool:  # noqa: ARG002
        raise NotImplementedError

    def run(self, root: Path, profile: StackProfile) -> list[Finding]:  # noqa: ARG002
        raise NotImplementedError


# === helpers: File walking & reading ========================================================================
def iter_files(root: Path, suffixes: tuple[str, ...]) -> list[Path]:
    """All files under `root` with one of `suffixes`, skipping vendored/build dirs,
    nested git worktrees, and `.gitignore`-matched paths (see `agentsec.walk`)."""
    return walk_files(root, suffixes=suffixes)


def iter_dockerfiles(root: Path) -> list[Path]:
    """All Dockerfiles under `root`: a file named `Dockerfile`/`Dockerfile.<x>`, or any
    `*.dockerfile` (the `service.dockerfile` convention). Honors the shared walk excludes.
    Dockerfiles have no single suffix, so they're matched by name."""
    return [
        f for f in walk_files(root)
        if f.name == "Dockerfile" or f.name.startswith("Dockerfile.") or f.name.lower().endswith(".dockerfile")
    ]


def join_dockerfile_continuations(text: str) -> str:
    r"""Join Dockerfile backslash line-continuations (a ``\`` at end-of-line) into one logical
    line, so an instruction whose argument is split across physical lines is matched as a whole.

    Line numbers are PRESERVED: each merged instruction stays on its original starting physical
    line and every consumed continuation line is replaced by a blank line, so a guard's
    ``text.count("\n", 0, match.start())`` line math still points at the instruction. A
    ``RUN apt-get update && \`` / ``    sudo ...`` pair thus becomes one line the sudo-connector
    regex can see, with no bare ``\`` left sitting between the ``&&`` and the next token.

    A ``\`` at the end of a ``#`` comment line is NOT a continuation (Docker ends comments at the
    newline), so comment lines are never joined into the following instruction.

    The fold accumulates into a LIST and joins once. The obvious `cur = cur.rstrip()[:-1] + " " +
    next` accumulator re-reads and rebuilds the whole logical line on every fold, which is
    O(folds x line length): measured quadratic on an ordinary multi-line `RUN` (0.038s at 8,000
    twenty-char continuations) and worse on longer lines (0.32s at sixty-char), independent of any
    regex (#697). Two behaviours of that loop are load-bearing and are preserved deliberately:

    1. A trailing ``\`` on the FILE'S LAST line stays put, because the `i + 1 < len(lines)` guard
       fails before the strip ever happens. So the strip is deferred until a continuation is
       actually consumed, never done eagerly when the accumulation starts.
    2. The ``#`` guard re-tests the ACCUMULATED string each pass, not the first line, and folding
       can change the answer (a whitespace-only first line followed by a comment line). So the
       first non-whitespace character is tracked as folds happen instead of re-deriving it.

    Both were found by an equivalence sweep against the previous implementation, which the naive
    rewrite failed; `test_join_dockerfile_continuations_matches_reference_implementation` keeps
    them pinned."""
    lines = text.split("\n")
    out: list[str] = []
    i = 0
    n = len(lines)
    while i < n:
        parts: list[str] = [lines[i]]
        blanks = 0
        # The accumulated string's first non-whitespace char, and which part carries it, so the
        # `#` test above stays O(1) per fold instead of re-joining the accumulation.
        first_ns_idx: int | None = None
        first_ns: str | None = None
        lead = lines[i].lstrip()
        if lead:
            first_ns_idx, first_ns = 0, lead[0]
        while i + 1 < n:
            # `cur.rstrip()` reaches back past any trailing whitespace-only parts, so this scan
            # has to find where the accumulated tail really is. Many such parts CAN pile up: each
            # fold rstrips the backslash off `parts[k]`, which leaves a whitespace-only husk when
            # the line was only indentation plus `\`, and the truncation below removes `parts[k+1:]`
            # but never `parts[k]` itself (measured: 1,001 coexisting husks on 1,000 `"  \"` lines).
            # It stays linear anyway, for a subtler reason than "there is only ever one": while a
            # run is folding, the newly appended part still carries its backslash, so it is never
            # blank and this scan stops at once, O(1) per fold. The one walk that is long happens
            # only when the appended line is ITSELF whitespace-only, and that walk necessarily ends
            # the run: it terminates either at k < 0 or at a part whose rstrip() no longer ends in
            # a backslash, and both break. So the long walk happens at most once per run.
            k = len(parts) - 1
            while k >= 0 and not parts[k].strip():
                k -= 1
            if k < 0 or not parts[k].rstrip().endswith("\\"):
                break
            if first_ns == "#":
                break
            parts[k] = parts[k].rstrip()[:-1]  # drop trailing whitespace + the backslash
            del parts[k + 1:]  # ...and the whitespace-only parts rstrip() just consumed
            parts.append(" " + lines[i + 1])
            if first_ns_idx is None or first_ns_idx >= k:
                first_ns_idx, first_ns = None, None
                for j in range(k, len(parts)):
                    lead = parts[j].lstrip()
                    if lead:
                        first_ns_idx, first_ns = j, lead[0]
                        break
            i += 1
            blanks += 1
        out.append("".join(parts))
        out.extend([""] * blanks)  # keep total line count so line numbers still map
        i += 1
    return "\n".join(out)


def drop_dockerfile_continuation_comments(text: str) -> str:
    r"""Remove ``#`` comment lines that sit INSIDE a backslash-continued instruction, the way
    Docker's own parser does, so ``join_dockerfile_continuations`` folds the instruction past
    them instead of folding the comment's text into it.

    ``RUN echo hi \`` / ``# chmod 777 /x`` / ``&& true`` is one ``RUN echo hi && true`` to
    Docker; joined as-is, the commented-out ``chmod`` would read as live. Each dropped line is
    re-emitted as a blank line right after the continuation group ends, so the line count is
    unchanged and every line after the group keeps its number; the instruction itself keeps its
    starting line. Comment lines OUTSIDE a continuation are left alone.

    Run it on the text a guard MATCHES, never on the text its pragma check reads: a pragma
    written as a comment inside a continued ``RUN`` must still count (CLAUDE.md rule 4). One
    pass, linear in the input."""
    out: list[str] = []
    pending = 0
    in_cont = False
    for line in text.split("\n"):
        is_comment = line.lstrip().startswith("#")
        if in_cont and is_comment:
            pending += 1
            continue
        out.append(line)
        in_cont = not is_comment and line.rstrip().endswith("\\")
        if not in_cont and pending:
            out.extend([""] * pending)
            pending = 0
    out.extend([""] * pending)
    return "\n".join(out)


def iter_files_named(
    root: Path, *name_globs: str, respect_gitignore: bool = True
) -> list[Path]:
    """Files under `root` whose **name** matches one of `name_globs` (`*`/`?`), honoring
    the shared walk excludes (vendored/build dirs + nested git worktrees). Use this instead
    of `root.rglob(<pattern>)` for suffix-less / name-matched files (`.env*`, `Dockerfile`,
    `requirements*.txt`): `rglob` descends into worktrees and excluded dirs, producing
    duplicate findings from sibling branch checkouts (e.g. `.claude/worktrees/...`).

    `respect_gitignore=False` still scans `.gitignore`-matched files — needed for env/secret
    guards that must see a real, gitignored `.env` (the vendored-dir + worktree skips still apply)."""
    return walk_files(root, names=name_globs, respect_gitignore=respect_gitignore)


# --- run-scoped read memo (#597) -------------------------------------------------------------------
#
# Every guard reads the files it scans, so one audit of agentsec's own package made 93,450 reads of
# 600 files (2026-10-23). Within one audit the target does not change, so `read_run()` serves each
# path's text once. It is a SEPARATE scope from `derived_state_run()` on purpose: those tables are
# keyed by file CONTENT, so a caller that edits files inside them (the pragma-anchoring gate mutates
# canary files between probes, inside `derived_state_run()`) can never be served stale text. This one
# is keyed by PATH, so it may only be open where nothing writes the target: `audit()` and the
# budgeted guard worker's child, and nowhere else. Bounded by characters, per PROCESS: unlike the
# parse memo's cap (`astutil.share_parse_cache`) it is not divided between budgeted lanes, so N lane
# children can hold up to N times this cap between them.
_MAX_READ_CACHE_CHARS = 32_000_000  # up to 32 MB of ASCII text; a str costs 1-4 bytes per character
_read_cache: dict[Path, str] = {}
_read_cache_chars = 0
_read_depth = 0


@contextmanager
def read_run() -> Iterator[None]:
    """Memoise `read()` by path for the duration of one audit. Re-entrant, cleared on entry to and
    exit from the outermost scope. Only for a run that does not modify the files it reads."""
    global _read_depth, _read_cache_chars
    if _read_depth == 0:
        _read_cache.clear()
        _read_cache_chars = 0
    _read_depth += 1
    try:
        yield
    finally:
        _read_depth -= 1
        if _read_depth == 0:
            _read_cache.clear()
            _read_cache_chars = 0


def read(p: Path) -> str:
    """A file's text as UTF-8 with undecodable bytes ignored, or "" if it cannot be read at all.

    Both halves are load-bearing for a guard: `errors="ignore"` so a stray binary or mis-encoded
    file cannot raise mid-scan, and the `OSError` swallow so a permission-denied or vanished path
    is a skipped file rather than a dead audit. Never reach for `Path.read_text()` directly (and
    never `open()`, which `agentsec/guard_sandbox.py` bans inside guard modules).

    Memoised by path inside a `read_run()` scope (see above); a straight read outside one.
    """
    global _read_cache_chars
    if _read_depth:
        hit = _read_cache.get(p)
        if hit is not None:
            return hit
    try:
        text = p.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return ""
    if _read_depth and _read_cache_chars + len(text) <= _MAX_READ_CACHE_CHARS:
        _read_cache[p] = text
        _read_cache_chars += len(text)
    return text


def file_contains_bytes(p: Path, needle: bytes, *, chunk_bytes: int = 1 << 20) -> bool:
    """True if `needle` occurs anywhere in the file's raw bytes, in O(chunk) memory (issue #443).

    For a guard that must scan files of ANY size (no suffix filter to bound them): it checks the
    WHOLE file for the bytes a finding requires without decoding it, so a committed model
    checkpoint costs one chunk of memory instead of several times its size. Each chunk is
    searched together with the last `len(needle) - 1` bytes of the one before, so a needle
    straddling a chunk boundary is still found. An unreadable file is False, the same as `read()`
    returning "".
    """
    if not needle:
        raise ValueError("needle must be non-empty")
    keep = len(needle) - 1
    tail = b""
    try:
        with p.open("rb") as fh:
            while chunk := fh.read(chunk_bytes):
                buf = tail + chunk
                if needle in buf:
                    return True
                tail = buf[len(buf) - keep :] if keep else b""
    except OSError:
        return False
    return False


def read_bytes_prefix(p: Path, limit: int) -> tuple[bytes, bool]:
    """The first `limit` bytes of `p` and whether the file holds more, in O(limit) memory.

    For a guard that scans a binary artifact up to a cap: `p.read_bytes()[:limit]` loads the
    WHOLE file before slicing, so a committed multi-gigabyte model costs its full size. The
    second value is True when bytes past `limit` exist, so the caller can disclose a capped scan
    instead of reporting it as clean. Raises `OSError` as `Path.open` does.
    """
    with p.open("rb") as fh:
        data = fh.read(limit)
        more = bool(fh.read(1))
    return data, more


# Member compression methods `zip_member_prefix` will inflate. `zipfile` bounds a DEFLATE read
# by the requested size, but inflates a whole compressed chunk of a BZIP2/LZMA member at once,
# so those (and any method `zipfile` cannot read) are reported as not read instead.
_BOUNDED_ZIP_METHODS = frozenset({zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED})


def zip_member_prefix(zf: zipfile.ZipFile, name: str | zipfile.ZipInfo, limit: int) -> tuple[bytes, bool]:
    """The first `limit` decompressed bytes of member `name`, and whether it holds more.

    `zf.read(name)[:limit]` inflates the whole member first, so a kilobyte zip declaring a
    gigabyte member (a zip bomb) costs a gigabyte; this streams at most `limit` bytes. A member
    stored with a method whose read cannot be bounded returns `(b"", True)`: nothing read, and
    the caller must not report it as clean. Raises as `zf.open` does on a corrupt member.

    Pass the `ZipInfo` from `zf.infolist()` when names may repeat: `zf.getinfo(name)` returns
    only the LAST entry of that name, so an earlier same-named entry would never be read.
    """
    info = name if isinstance(name, zipfile.ZipInfo) else zf.getinfo(name)
    if info.compress_type not in _BOUNDED_ZIP_METHODS:
        return b"", True
    with zf.open(info) as member:
        data = member.read(limit)
        more = info.file_size > limit or bool(member.read(1))
    return data, more


_ZIP_EOCD = b"PK\x05\x06"
_ZIP64_EOCD_LOCATOR = b"PK\x06\x07"
_ZIP64_EOCD = b"PK\x06\x06"
_ZIP_EOCD_SEARCH_BYTES = 22 + 0xFFFF  # the fixed record plus the longest archive comment


def zip_central_directory_size(p: Path) -> int | None:
    """The byte size the zip at `p` declares for its central directory, or None if it has no
    end-of-central-directory record, read from the file's tail in O(64 KiB) memory (zip64 aware).

    `zipfile.ZipFile(p)` reads the whole central directory into memory and builds one object per
    entry, so a hostile archive can make merely OPENING it cost many times its directory size.
    Check this against a budget before opening a zip whose size the repo controls. Raises
    `OSError` as `Path.open` does.
    """
    with p.open("rb") as fh:
        size = fh.seek(0, 2)
        tail_len = min(size, _ZIP_EOCD_SEARCH_BYTES)
        fh.seek(size - tail_len)
        tail = fh.read(tail_len)
        at = tail.rfind(_ZIP_EOCD)
        if at == -1 or at + 22 > len(tail):
            return None
        declared = int.from_bytes(tail[at + 12 : at + 16], "little")
        # zipfile (`_EndRecData64`) reads a zip64 locator directly before the classic record and
        # the zip64 record directly before that, and when they are present it takes the
        # directory size from the zip64 record, whatever the classic field says. Mirror it
        # exactly: a classic field that merely looks small must not pass the budget check.
        eocd_at = size - tail_len + at
        if eocd_at < 76:
            return declared
        fh.seek(eocd_at - 76)
        record_and_locator = fh.read(76)
        record, locator = record_and_locator[:56], record_and_locator[56:]
        if locator[:4] != _ZIP64_EOCD_LOCATOR or record[:4] != _ZIP64_EOCD:
            return declared
        return int.from_bytes(record[40:48], "little")


_LFS_VERSION_LINES = (b"version https://git-lfs.github.com/spec/v1", b"version https://hawser.github.com/spec/v1")
_LFS_MAX_POINTER_BYTES = 1024
_LFS_KEY_BYTES = frozenset(b"abcdefghijklmnopqrstuvwxyz0123456789.-")


def _is_lfs_pointer_line(line: bytes) -> bool:
    """`key value`: a lowercase key, one space, then a non-empty run of printable ASCII."""
    key, sep, value = line.partition(b" ")
    return (
        bool(key) and bool(sep) and bool(value) and value[0] != 0x20
        and all(c in _LFS_KEY_BYTES for c in key) and all(0x20 <= c <= 0x7E for c in value)
    )


def is_git_lfs_pointer(p: Path) -> bool:
    """True if `p` is a Git LFS pointer file (the small text stub committed in place of a large
    binary), not the artifact itself. Strict on purpose: under 1024 bytes, the LFS version line
    first, then only `key value` lines of printable ASCII including `oid` and `size`, so a
    loadable binary (a zip, an HDF5 file with a user block, a pickle) cannot pass for one by
    starting with the version line. An unreadable file is False.
    """
    try:
        data, more = read_bytes_prefix(p, _LFS_MAX_POINTER_BYTES)
    except OSError:
        return False
    if more or not data.startswith(_LFS_VERSION_LINES):
        return False
    keys: set[bytes] = set()
    for raw_line in data.split(b"\n"):
        line = raw_line.removesuffix(b"\r")
        if not line:
            continue
        if not _is_lfs_pointer_line(line):
            return False
        keys.add(line.split(b" ", 1)[0])
    return b"oid" in keys and b"size" in keys


# Every line boundary `str.splitlines()` honours.
_SPLITLINES_BREAKS = frozenset("\n\r\x0b\x0c\x1c\x1d\x1e\x85\u2028\u2029")


def _line_pieces(lineno: int, line: str, max_chars: int, step: int) -> Iterator[tuple[int, str]]:
    start = 0
    while True:
        yield lineno, line[start : start + max_chars]
        if start + max_chars >= len(line):
            return
        start += step


def iter_lines_bounded(
    p: Path, *, max_line_chars: int, overlap_chars: int, chunk_bytes: int = 1 << 20
) -> Iterator[tuple[int, str]]:
    """Yield `(lineno, line)` from a streamed read, in O(chunk + max_line_chars) memory (issue #443).

    The bounded counterpart of `enumerate(read(p).splitlines(), start=1)` for a file too large to
    decode whole, and equal to it for every line up to the cap: the same UTF-8 decode with
    undecodable bytes ignored (incrementally, so a character or a CRLF cut by a chunk edge is
    whole), then the same `splitlines()` boundaries and numbering. A line longer than
    `max_line_chars` is yielded as several pieces sharing its line number, each overlapping the
    previous by `overlap_chars`, so a pattern no longer than the overlap is never cut in half by a
    piece boundary; a caller that wants one verdict per line groups on the number. An unreadable
    file yields nothing, like `read()` returning "".
    """
    if not 0 <= overlap_chars < max_line_chars:
        raise ValueError("need 0 <= overlap_chars < max_line_chars")
    step = max_line_chars - overlap_chars
    decoder = codecs.getincrementaldecoder("utf-8")(errors="ignore")
    lineno = 1
    buf = ""
    try:
        with p.open("rb") as fh:
            while True:
                chunk = fh.read(chunk_bytes)
                eof = not chunk
                buf += decoder.decode(chunk, final=eof)
                lines = buf.splitlines()
                carry = ""
                # Unterminated, or a `\r` that may be the first half of a `\r\n` in the next chunk:
                # the last line is still being read.
                if lines and not eof and (buf[-1] == "\r" or buf[-1] not in _SPLITLINES_BREAKS):
                    carry = lines.pop() + ("\r" if buf[-1] == "\r" else "")
                buf = carry
                if lines and max(map(len, lines)) <= max_line_chars:
                    yield from enumerate(lines, start=lineno)  # the common case, no per-line step
                    lineno += len(lines)
                else:
                    for line in lines:
                        yield from _line_pieces(lineno, line, max_line_chars, step)
                        lineno += 1
                if eof:
                    return
                # Emit whole pieces of the line still being read, so it never grows past one piece
                # plus one chunk.
                while len(buf) > max_line_chars:
                    yield lineno, buf[:max_line_chars]
                    buf = buf[step:]
    except OSError:
        return


def rel(root: Path, p: Path) -> str:
    """A path relative to the scanned repo root, absolute if it lies outside it.

    Guards build `Finding.location` from this, which is what keeps a report in repo-relative terms
    rather than in the absolute paths of the machine that ran the scan. Two things it is NOT. It is
    not a guarantee: the fallback returns `p` verbatim, absolute path and all, whenever `p` is not
    under `root`. And it is not a pipeline-wide invariant: the runners map their scanner's own
    location strings and never call it.
    """
    try:
        return str(p.relative_to(root))
    except ValueError:
        return str(p)


# Test / example / fixture / migration paths — a finding here is far less likely to be a
# live, attacker-reachable bug. Guards prone to test-file noise (e.g. ones matching broad
# patterns like `.json()[` or storage-key substrings) skip these via `is_nonproduct_path`.
# NOTE: file conventions like `*.example` / `*.dev.yml` are deliberately NOT here — this is a
# SHARED gate, and a `.env.example` is the *attack surface* for `claude-code-compromise` (a poisoned
# `CODEX_HOME`/reverse-shell template) exactly as `.claude/` is for `ai-instruction-poisoning`. Those
# are guard-RELATIVE non-product surfaces: a guard that FPs on a `*.example` Dockerfile (§D.7) or a
# `*.dev.yml` compose (§H.2) skips it in its OWN `run()`, never via this universal list.
_NONPROD_PATH = re.compile(
    r"(?:^|/)(?:" + NONPRODUCT_DIR_ALT + r")(?:/|$)"
    r"|(?:^|/)(?:test_[^/]*|conftest)\.py$"
    r"|(?:\.test|\.spec)\.[a-z0-9]+$|_test\.py$|_test\.go$",
    re.IGNORECASE,
)


# The DEPLOYMENT trees inside the shared non-product list. They are non-product for pattern-noise
# purposes (a migration's SQL/ORM churn trips broad guards), but unlike `tests/` or `fixtures/`
# their contents are REAL deployment code and any credential in them is a REAL leak — `alembic/env.py`
# routinely holds the database URL. Credential guards therefore keep scanning them; see the
# `credential_scan` flag below (#483 review).
# `re.IGNORECASE` on BOTH patterns below is load-bearing, not decorative. It was reported as inert on
# the grounds that this branch is only reached after a case-SENSITIVE `_NONPROD_PATH` matched — but
# `_NONPROD_PATH` is itself compiled with `re.IGNORECASE` above, so a capitalized `Migrations/` or
# `Alembic/` tree does reach here. Drop the flag and those paths flip from scanned to skipped, which
# silently drops the credential guards on a capitalized deployment tree: the exact
# password-in-`alembic/env.py`-goes-unreported regression `credential_scan` exists to prevent. Pinned
# by `test_credential_scan_is_case_insensitive_end_to_end` (#483 second-pass review).
_DEPLOYMENT_NONPROD = re.compile(r"(?:^|/)(?:migrations?|alembic)(?:/|$)", re.IGNORECASE)
# The same names as a WHOLE path segment, for the segment-wise strip below.
_DEPLOYMENT_SEGMENT = re.compile(r"migrations?|alembic", re.IGNORECASE)


def _in_archive_tree(norm: str, archive_segments: frozenset[str]) -> bool:
    """True if any DIRECTORY segment of a normalized path is an opted-in archive segment.

    Directory segments only (the filename is excluded) — mirrors `detect`'s archive check, so a
    file literally named `old` isn't mistaken for an `old/` tree. Factored out because the check
    now has two call sites: the ordinary tail below, and the `credential_scan` early return."""
    if not archive_segments:
        return False
    return any(seg in archive_segments for seg in norm.lower().split("/")[:-1])


# === helpers: Path classification (what to skip) ============================================================
def is_nonproduct_path(
    rel_path: str,
    archive_segments: frozenset[str] = frozenset(),
    *,
    credential_scan: bool = False,
) -> bool:
    """True for a test/example/fixture/migration path (forward-slash-normalized).

    Archived/dead-code trees are **opt-in**: when `archive_segments` is non-empty (a per-repo
    setting from `.agentsec/config.json`; see `config.load_repo_config` / `StackProfile`),
    a finding under any of those DIRECTORY segments is also non-product. Empty by default —
    so a live directory merely named `old/` is still scanned unless a repo opts in. Guards
    pass `profile.archive_segments` here. (Unconditional archive *demotion* lives in
    `prioritize`, which only re-ranks and never drops a finding.)

    `credential_scan=True` keeps DEPLOYMENT trees (`migrations/`, `alembic/`) in scope while still
    skipping the fake-secret trees (`tests/`, `fixtures/`, `examples/`, `__mocks__/`). A password in
    a test fixture is deliberately fake; one in `alembic/env.py` is a real committed credential.
    Adding `alembic` to the shared list silently dropped five credential guards on that tree — a
    hardcoded DB password in `alembic/env.py` went from reported to unreported (#483 review).

    SCOPE: the carve-out covers THIS gate (the guard DROP) only. `NONPRODUCT_DIR_ALT` has a second
    consumer — `prioritize._NON_PRODUCT`, the report DEMOTE gate — which still ranks a finding under
    `alembic/`/`migrations/` as `reachability="low"`, for every guard including these. So a restored
    credential is reported and still trips `--fail-on` (that gate is severity-based, unaffected), but
    it is ranked low and will not lead "Fix these first". Deliberate: migration churn is genuinely
    noisy, and demoting keeps the finding visible where dropping did not. Changing THAT is a separate
    decision from this one (#483 re-gate)."""
    norm = rel_path.replace("\\", "/")
    if _NONPROD_PATH.search(norm) is not None:
        if credential_scan and _DEPLOYMENT_NONPROD.search(norm) is not None:
            # Non-product ONLY because of deployment segments -> still scanned. Drop those segments
            # SEGMENT-WISE rather than by `re.sub`: a substitution is non-overlapping, so it left
            # the second of two ADJACENT deployment segments in place and the path still read as
            # non-product. `migrations/alembic/env.py`, `alembic/migrations/env.py` and
            # `src/migrations/alembic/env.py` were all wrongly skipped — the very layout this flag
            # exists to keep in scope (#483 review, second pass). The FILENAME is preserved, so a
            # `conftest.py` / `test_*.py` / `*.spec.*` under a deployment tree still counts.
            segments = norm.split("/")
            kept = [s for s in segments[:-1] if not _DEPLOYMENT_SEGMENT.fullmatch(s)]
            if _NONPROD_PATH.search("/".join([*kept, segments[-1]])) is None:
                # ...but a repo's OPT-IN archive tree still wins. Returning False straight from
                # here skipped the `archive_segments` branch below, so `old/alembic/env.py` came
                # back True/False depending only on `credential_scan` — an opted-out tree that the
                # docstring promises is non-product either way (#483 re-gate). `audit()`'s universal
                # `archive_paths` DROP masked it in the report, so this is a contract fix, not a
                # visible-behavior one: keep the two answers consistent at the helper.
                return _in_archive_tree(norm, archive_segments)
        return True
    return _in_archive_tree(norm, archive_segments)


# SQL guards need a NARROWER non-product notion than `is_nonproduct_path`: a reference/example/test
# schema is non-product, but `migrations/` (and `alembic/`) are the DEPLOYED schema for SQL — Supabase's
# canonical layout is `supabase/migrations/*.sql`, so skipping `migrations/` would silence a real RLS /
# extension gap on the guard's primary target population (PR #484 review). This deliberately omits
# `migrations`/`alembic` from the non-product set.
_REFERENCE_SQL_PATH = re.compile(
    r"(?:^|/)(?:examples?|samples?|fixtures?|__mocks__|tests?)(?:/|$)", re.IGNORECASE
)


def is_reference_sql_path(rel_path: str) -> bool:
    """True for a REFERENCE/example/test `.sql` path (`examples/`, `samples/`, `fixtures/`, `tests/`).
    Unlike `is_nonproduct_path`, `migrations/`/`alembic/` are NOT non-product here — for SQL they are the
    deployed schema (PR #484 review)."""
    return _REFERENCE_SQL_PATH.search(rel_path.replace("\\", "/")) is not None


# --- guard-relative non-product FILE conventions ------------------------------------------------
# Deliberately NOT part of the shared `is_nonproduct_path` list (a `.env.example` is a real attack
# surface for `claude-code-compromise`), but shared HERE so the guards that do honor them cannot
# drift apart. `datastore-auth-absent` and its stated mirror `compose-db-port-exposed` disagreed on
# what a dev compose file is: the report published "the Redis port is exposed" while suppressing
# "and it has no password", which is worse than either answer alone (#484 review).

# A local-development compose filename. Structural, NOT a substring match: the qualifier has to be
# the file's own trailing token, either dot-delimited (`docker-compose.dev.yml`, `compose.local.yaml`),
# the whole stem (`dev.yml`), or hyphenated onto a COMPOSE base (`docker-compose-dev.yml`).
# A plain `[.\-](dev|local)\.ya?ml$` substring test matched `production-local.yml` and
# `docker-compose.non-local.yml` — and the latter is reachable through the callers' own
# `docker-compose*.yml` glob, so it was a live false negative, not a latent one (#484 second-pass
# review). Requiring a compose base for the hyphen form is what separates the two.
_DEV_QUALIFIERS = frozenset({"dev", "local", "development"})
_COMPOSE_BASES = frozenset({"compose", "docker-compose"})


def is_dev_compose_file(name: str) -> bool:
    """True for a local-development compose filename (`*.dev.yml`, `docker-compose-dev.yml`, …).
    Guards that treat dev compose as out of scope MUST share this so they agree. Total: never raises."""
    lowered = name.lower()
    stem, dot, ext = lowered.rpartition(".")
    if not dot or ext not in ("yml", "yaml"):
        return False
    head, _, last = stem.rpartition(".")
    if last in _DEV_QUALIFIERS:          # `docker-compose.dev.yml`, `dev.yml`
        return True
    base, hyphen, tail = last.rpartition("-")
    return bool(hyphen) and tail in _DEV_QUALIFIERS and base in _COMPOSE_BASES


# Compose interpolation, full grammar: `$VAR`, `${VAR}`, and the default/error forms
# `${VAR:-d}` / `${VAR-d}` / `${VAR:?m}` / `${VAR?m}` / `${VAR:+a}` / `${VAR+a}`. Shared by
# `compose_credential_env_literal` and `compose_connection_string_credential` (#663 review H1/H2)
# so the two guards' interpolation handling cannot drift apart again — both had a byte-identical
# `_PURE_VAR_REF` that matched only bare `${VAR}` and mis-fired HIGH on every `${VAR:-}` empty
# default, the *recommended* Compose pattern (13 of 16 findings on a 6-repo corpus were this FP).
_COMPOSE_VAR_REF = re.compile(
    r"^\$(?:[A-Za-z_][A-Za-z0-9_]*"
    r"|\{[A-Za-z_][A-Za-z0-9_]*(?P<op>:?[-?+])?(?P<default>[^}]*)\})$"
)


# === helpers: Docker Compose ================================================================================
def is_compose_interpolation_only(value: str) -> bool:
    """True if `value` carries no literal baked into the compose file: a bare `$VAR`/`${VAR}`
    reference, an empty-fallback default (`${VAR:-}`/`${VAR-}`), or an error-message form
    (`${VAR:?msg}`/`${VAR?msg}` — shown only when unset, never a shipped value).

    False for an ordinary literal string AND for a NON-EMPTY-fallback default
    (`${VAR:-hunter2}`/`${VAR-hunter2}`) — that fallback IS a literal credential shipped in the
    compose file, so callers must keep treating it as one (the narrowing this exists to bound:
    a fix here must not stop firing on `${POSTGRES_PASSWORD:-postgres}`). Total: never raises.
    """
    m = _COMPOSE_VAR_REF.match(value)
    if m is None:
        return False
    op, default = m.group("op"), m.group("default")
    if op is None or op in (":?", "?"):
        return True          # pure reference, or an error-message form
    return not default       # a NON-EMPTY fallback is itself a literal, an empty one is not


# A user-customization TEMPLATE: `Dockerfile.example`, `compose.user.example`. Case-insensitive —
# the original `str.endswith(".example")` missed `Dockerfile.EXAMPLE` while the dev-compose pattern
# beside it was already case-insensitive (#484 review).
_EXAMPLE_TEMPLATE_FILE = re.compile(r"\.example$", re.IGNORECASE)


# === helpers: Path classification (what to skip) ============================================================
def is_example_template_file(name: str) -> bool:
    """True for a `*.example` user-customization template filename, case-insensitively.
    Total: never raises."""
    return _EXAMPLE_TEMPLATE_FILE.search(name) is not None


# A line that starts a new top-level SQL statement — its first token is a statement keyword.
# Used ONLY to bound how far a candidate string literal is allowed to reach (see
# `_statement_bounds`); it never classifies anything as a comment on its own, so a keyword this
# list misses can only leave the bound looser, never delete text.
_SQL_STATEMENT_START = re.compile(
    r"[ \t]*(?P<kw>CREATE|ALTER|DROP|COMMENT|GRANT|REVOKE|INSERT|UPDATE|DELETE|SELECT|SET|COPY"
    r"|TRUNCATE|BEGIN|COMMIT|ROLLBACK|WITH|DO|CALL|ANALYZE|VACUUM|REFRESH|EXPLAIN)\b",
    re.IGNORECASE,
)


def _statement_bounds(sql: str) -> list[int]:
    """Sorted indices of the STATEMENT BOUNDARIES a candidate string literal may not cross.

    Two markers, both cheap and text-only: every `;`, and the first character of every line whose
    first token starts a new SQL statement (`_SQL_STATEMENT_START`). Deliberately computed WITHOUT
    knowing string/comment state — that is the chicken/egg problem `strip_sql_comments` exists to
    work around, so a `;` inside a real literal or comment is included here too. The only effect of
    an over-eager boundary is a TIGHTER bound (the quote is read as data and the text is emitted
    verbatim), never a deletion.

    O(n): one C-level `find` loop for the `;`s and one regex match per line, then a `sorted()` over
    two already-sorted runs (Timsort merges those in linear time)."""
    bounds: list[int] = []
    p = sql.find(";")
    while p != -1:
        bounds.append(p)
        p = sql.find(";", p + 1)
    pos = 0
    for line in sql.splitlines(keepends=True):
        m = _SQL_STATEMENT_START.match(line)
        if m is not None:
            bounds.append(pos + m.start("kw"))
        pos += len(line)
    return sorted(bounds)


# === helpers: SQL text ======================================================================================
def opens_sql_escape_string(sql: str, quote_i: int) -> bool:
    r"""True if the `'` at `quote_i` opens a Postgres `E'…'` escape string.

    Postgres honors backslash escapes inside `E'…'` **regardless** of `standard_conforming_strings`,
    so `E'it\'s'` closes at its FINAL quote, not at the escaped one. A scanner that cannot tell `'`
    from `E'` mis-closes the literal, resumes code-mode lexing *inside* it, and then reads a `/*` in
    the literal's own text as a real comment opener — blanking or deleting live SQL after it
    (issue #500, measured: a live `CREATE POLICY` disappeared and both RLS guards went silent).

    The `E` must be a bare prefix, not the tail of an identifier: `value'` in `select value'x'` is
    not an escape string, so the character before the `E` may not be identifier-ish."""
    if quote_i <= 0 or sql[quote_i - 1] not in "eE":
        return False
    j = quote_i - 2
    return j < 0 or not (sql[j].isalnum() or sql[j] in "_$")


def _find_sql_close(sql: str, start: int, delim: str, n: int, *, backslash_escapes: bool = False) -> int:
    r"""Index of the delimiter closing a SQL literal opened just before `start`, or -1.

    SQL escapes an inner delimiter by DOUBLING it (`'it''s'`), so a doubled pair is skipped
    rather than treated as a close. Returning -1 lets the caller decide the opening quote was
    never a literal at all, which is what keeps a stray apostrophe from swallowing the file.

    `backslash_escapes` additionally honors `\x` pairs — set by the caller only for a literal
    opened by the Postgres `E'…'` prefix (`opens_sql_escape_string`), where a backslash escapes
    regardless of `standard_conforming_strings`. It stays OFF for an ordinary `'…'`, so `'C:\'`
    still closes at its own quote rather than eating the next one (issue #441's false positive).

    This is the PAIRING (parity) decision and it is deliberately unbounded — see
    `strip_sql_comments` for why revoking a span's comment-immunity must never move the pairing."""
    j = start
    while j < n:
        c = sql[j]
        if backslash_escapes and c == "\\":
            j += 2  # escape — this char and the next are literal, neither can close the string
            continue
        if c == delim:
            if j + 1 < n and sql[j + 1] == delim:
                j += 2
                continue
            return j
        j += 1
    return -1


def blank_sql_literals(sql: str, *, identifiers: bool = False, dollar_quotes: bool = True) -> str:
    r"""Same-length copy of `sql` with the CONTENT of every string literal space-filled — `'…'`
    (doubled `''` stays inside), `E'…'` (backslash escapes honoured) and `$tag$…$tag$` — delimiters
    kept, so an offset on the result indexes the same character in the original.

    The structural twin of `strip_sql_comments(blank=True)`: run on comment-blanked text it gives a
    view on which a keyword, operator or paren inside a literal (`USING (x = 'a OR b)')`) is
    invisible to a structural regex, while the original at the same offsets still holds the content
    (the `definer_dynamic_sql._mask_quoted` pattern). Newlines inside a literal are kept, so the
    `count("\n", 0, off)` line idiom stays valid on the view too.

    Quote PAIRING is composed from the two helpers above, never re-derived: an ordinary `'…'`
    closes via `_find_sql_close` and an `E'…'` string (`opens_sql_escape_string`) via
    `_find_sql_close(..., backslash_escapes=True)`, so `E'a\'b' OR x` keeps its `OR` outside the
    literal while `'C:\'` still closes at its own quote (#441). A blanker with a private pairing
    rule is exactly what shipped #827 round 3 H1: it mis-closed an `E'…'`, resumed code-mode
    lexing inside the literal, and blanked every later literal out of phase.

    `"…"` identifiers (doubled `""` inside) are always consumed as one unit — a `'` or `$$` inside
    one never opens a literal — and left in place by default; `identifiers=True` space-fills their
    content as well, for a view on which a column named `"or"` cannot split a conjunction. A dollar
    tag opens only where Postgres's lexer opens one: not glued to an identifier character (`x$$`
    is the identifier `x$$`; `$1` is a parameter). An unclosed literal blanks to the end of text.

    `dollar_quotes=False` leaves `$tag$…$tag$` spans untouched (only `'…'`/`"…"` are masked) — for
    a caller that has ALREADY isolated a dollar-quoted function/DO-block body and is scanning
    *inside* it: masking dollar-quotes there would blank the entire body being examined, which is
    the exact regression this flag exists to avoid (`pg_function_immutable_reads_session.py`/
    `pg_function_leakproof.py` M1 — those guards need `current_setting('app.tenant')`-
    shaped session reads to stay visible while a same-shaped call sitting inside a plain string
    literal WITHIN the body does not falsely match).
    """
    out = list(sql)
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c == "'" or c == '"':
            esc = c == "'" and opens_sql_escape_string(sql, i)
            j = _find_sql_close(sql, i + 1, c, n, backslash_escapes=esc)
            end = n if j == -1 else j
            if c == "'" or identifiers:
                out[i + 1 : end] = [ch if ch == "\n" else " " for ch in sql[i + 1 : end]]
            i = end + 1
        elif c == "$":
            if not dollar_quotes:
                i += 1
                continue
            glued = i > 0 and (sql[i - 1].isalnum() or sql[i - 1] == "_")
            m = None if glued else _SQL_DOLLAR_DELIM.match(sql, i)  # defined with the SQL block helpers
            if m is None:
                i += 1
                continue
            tag = m.group(0)
            close = sql.find(tag, m.end())
            end = n if close == -1 else close
            out[m.end() : end] = [ch if ch == "\n" else " " for ch in sql[m.end() : end]]
            i = n if close == -1 else close + len(tag)
        else:
            i += 1
    return "".join(out)


def blank_sql_literals_nested(sql: str) -> str:
    """Same-length copy of `sql` with the content of every `'…'` literal space-filled at every
    nesting level, each `$tag$…$tag$` body kept visible and read as nested SQL.

    The view a guard wants when a statement may sit inside a `DO $$ … $$` block or a plpgsql body
    (so the body must stay visible) but a statement merely quoted in a string must not count.
    `blank_sql_literals(..., dollar_quotes=False)` gets the first half by ignoring dollar quotes
    altogether, so a lone apostrophe in a dollar-quoted STRING (`COMMENT … IS $$Don't$$`) opens a
    literal that never closes and blanks the rest of the file, voiding every later statement
    (#1100 R2-M1). Here quotes pair only within the body that holds them, so an unclosed one blanks
    at most to the end of its own body. A dollar body that never closes is not a body: its opener
    is read as plain text, the way `blank_sql_literals` leaves an unpaired quote's damage capped.

    Iterative (an explicit stack, not recursion) and linear: each body's close is a bisect on the
    `_index_dollar_delims` index, so neither deep nesting nor a flood of unclosed tags can blow
    the stack or go quadratic on attacker-controlled SQL."""
    out = list(sql)
    n = len(sql)
    delims: dict[str, list[int]] | None = None
    stack: list[tuple[int, int]] = []  # (end of body, length of its closing tag), innermost last
    i = 0
    while i < n:
        limit = stack[-1][0] if stack else n
        if i >= limit:
            i = limit + stack.pop()[1]
            continue
        c = sql[i]
        if c == "'" or c == '"':
            esc = c == "'" and opens_sql_escape_string(sql, i)
            j = _find_sql_close(sql, i + 1, c, limit, backslash_escapes=esc)
            end = limit if j == -1 else j
            if c == "'":
                out[i + 1 : end] = [ch if ch == "\n" else " " for ch in sql[i + 1 : end]]
            i = limit if j == -1 else j + 1
        elif c == "$" and not (i > 0 and (sql[i - 1].isalnum() or sql[i - 1] == "_")):
            m = _SQL_DOLLAR_DELIM.match(sql, i, limit)
            if m is None:
                i += 1
                continue
            if delims is None:
                delims = _index_dollar_delims(sql)
            starts = delims.get(m.group(0), [])
            k = bisect_left(starts, m.end())
            close = starts[k] if k < len(starts) else -1
            if close == -1 or close + len(m.group(0)) > limit:
                i = m.end()  # an unclosed (or parent-crossing) tag opens no body
                continue
            stack.append((close, len(m.group(0))))
            i = m.end()
        else:
            i += 1
    return "".join(out)


_STMT_END_OR_QUOTE = re.compile(r"[;'\"]")


def find_statement_end(sql: str, start: int, end: int | None = None) -> int:
    """Index of the `;` ending the statement that continues at `start`, or -1.

    A `;` inside a `'…'` literal or `"…"` identifier that opens and closes on ONE LINE is
    content, not a terminator (issue #559: `CREATE POLICY "grant; select" ON …` carved down to
    `CREATE POLICY "grant;`, so every guard on `iter_statement_spans` / `iter_bounded_matches`
    lost the table, the roles and the expression — five went silent on real defects and three
    fired a false HIGH on correct SQL, all measured). Pairing is the decision `strip_sql_comments`
    makes, via `_find_sql_close`: a doubled delimiter stays inside, an `E'…'` string honours
    backslash escapes.

    A quote that never closes, or whose close lies past a newline, is a stray character: the
    search degrades to the bare `find(";")` from that quote — exactly the pre-#559 carve. The
    single-line bound is deliberate, and measured. Without it two malformed shapes get WORSE than
    today: a stray quote (the #528 shape) pairs with the next statement's literal and the two
    statements merge, losing the second policy; and a head matched inside a
    `DO $$ … EXECUTE format('CREATE POLICY …') $$` body frame-shifts on the literal's CLOSING
    quote and swallows the next real policy. With the bound both degrade to today's carve. The
    cost is a `;` inside a MULTI-line literal, a shape policy names and expressions do not take.
    A stray quote on the same line as the next statement still merges the two — bounded to that
    line, and a syntax error Postgres rejects.

    Linear: each `'` (resp. `"`) pairing scan runs to the next `'` (resp. `"`), so scans of one
    kind tile the input without overlap, and a scan that finds no partner can happen at most
    once per kind. 1 MB of quotes with no `;` measures under 0.2 s; the #419 hostile shapes the
    per-guard `*_hostile_headless_sql_is_linear` tests pin are unchanged.

    `end` bounds the search the way `str.find(sub, start, end)` does: nothing at or past it is
    read, so a quote whose close lies beyond it counts as stray within the bound. A caller asking
    "does a statement boundary lie between these two offsets" (`policy_exists_rls_disabled`'s
    head attribution) passes it, which keeps that check confined to the span it asks about
    instead of scanning on to the file's next terminator."""
    n = len(sql) if end is None else min(end, len(sql))
    i = start
    while True:
        m = _STMT_END_OR_QUOTE.search(sql, i, n)
        if m is None:
            return -1
        i = m.start()
        ch = sql[i]
        if ch == ";":
            return i
        close = _find_sql_close(
            sql, i + 1, ch, n, backslash_escapes=ch == "'" and opens_sql_escape_string(sql, i)
        )
        if close == -1 or sql.find("\n", i + 1, close) != -1:
            return sql.find(";", i + 1, n)
        i = close + 1


_POLICY_NAME_SPANS = re.compile(r'(create\s+policy\s+)("(?:[^"\n]|"")*")', re.IGNORECASE)


def blank_policy_names(sql: str) -> str:
    r"""`sql` with every quoted `CREATE POLICY "…"` name space-filled, length- and newline-preserving.

    A policy name is free text and must never be read as SQL structure. The unanchored
    `\bon\s+(\w+)` tail that `pg_rls_no_policy` / `policy_exists_rls_disabled` search inside the
    statement matches `on bar` INSIDE a name like `"foo on bar"` before it reaches the real
    `ON documents`, so `bar` is marked covered and a real HIGH on `bar` goes silent while
    `documents` draws a false one (#824 review, measured; the #559 carve made the `;`-and-`on`
    variant of the same name reachable). `rls_update_privileged_column.policy_stmt_without_name`
    is the per-statement form of this mask (#445); this one runs over the whole file BEFORE the
    `iter_bounded_matches` carve, so a tail can only ever see the clauses.

    Same length so every offset still maps onto the original, newlines kept so line numbers do.
    A name is masked only when its closing quote sits on the SAME line: a stray `"` would
    otherwise pair with a later statement's `"schema"."table"` quote and blank everything between
    (the #528 shape), so it is left alone — today's behaviour, the same bound
    `find_statement_end` applies."""
    return _POLICY_NAME_SPANS.sub(lambda m: m.group(1) + _blank(m.group(2)), sql)


def _blank(span: str) -> str:
    """Replace each char with a space, except an embedded newline, which passes through verbatim —
    keeps a `blank=True` caller's output the same length and same line count as the input."""
    return "".join(c if c == "\n" else " " for c in span)


# What a comment inside a REVOKED-immunity span is replaced with (issue #528). DELETING it
# outright welded the tokens either side into one contiguous phrase, which a consumer's `\s+`
# then read as real SQL: `'… ALTER TABLE foo /* note */ ENABLE ROW LEVEL SECURITY; …'` inside a
# data literal fabricated an rls-enabled finding for a table that exists nowhere. U+FFFD is not
# `\w`, not `\s`, and part of no SQL token, so it can neither weld a phrase nor extend a match.
# It appears ONLY where revoked-span comment content stood — the ordinary comment paths still
# delete (or blank) exactly as they always have.
_REVOKED_COMMENT_SENTINEL = "\ufffd"

# A `COPY … FROM stdin;` head line — the start of a pg_dump-style inline data section. Only a
# line whose statement ENDS the line matches (`;` then end-of-line): a head this misses can only
# mean LESS blanking, never more, and the payload rows that follow are then lexed as before.
#
# The `FROM stdin` search is ATOMIC (#826 round-2 review Major 1). Two independent lazy segments
# (`[^\n]*?\bFROM\s+stdin\b[^\n]*?;…$`) were quadratic on a head-shaped line carrying many
# `FROM stdin` tokens and no line-final `;`: the tail scanned to end-of-line for a `;` that never
# comes, backtracked, and retried at the next occurrence — O(occurrences x line length), measured
# 0.65s at 44 KB and 2.5s at 88 KB, paid again per such line and NOT bounded by
# `copy_terminator_absent` (that latch only engages once a head fully matches). Committing to the
# leftmost `FROM stdin` is what makes it linear, and the greedy `[^\n]*;` tail then runs once.
#
# Equivalence: `;[ \t\r]*$` can only match at ONE spot on a line (the last `;`, if only spaces
# follow), so on a single-line head the tail's verdict does not depend on WHICH `FROM stdin` was
# picked — the leftmost decides it for all of them. `\s` spans newlines, so a wrapped
# `COPY t FROM\nstdin;` still matches via that leftmost occurrence. The one shape this narrows is
# an earlier `FROM stdin` failing on line 1 while a later newline-spanning one reaches a `;`
# (`COPY t FROM stdin x FROM\nstdin;`) — not a valid COPY head, and the safe direction anyway.
# Differential-fuzzed against the pre-fix pattern over 1.1M inputs at every line-start offset:
# zero cases where this matches and the old one did not.
_COPY_FROM_STDIN = re.compile(
    r"^[ \t]*COPY\b(?>[^\n]*?\bFROM\s+stdin\b)[^\n]*;[ \t\r]*$", re.IGNORECASE | re.MULTILINE
)
# The data section's own terminator: `\.` alone on a line. pg_dump escapes a literal `\.` in row
# data, so the first match after the head is always the genuine end of the section.
_COPY_TERMINATOR = re.compile(r"^\\\.[ \t\r]*$", re.MULTILINE)


def _strip_comments_unguarded(text: str, *, blank: bool = False, sentinel: str = "") -> str:
    """Drop `--` and `/* */` comments from `text` with NO string awareness — every quote is data.

    Applied only to the INTERIOR of a quoted span that crosses a statement boundary, i.e. a span
    whose comment-immunity has been revoked (see `strip_sql_comments`). Deletion semantics are
    identical to the main scan's: a `--` runs to the char before the newline (the newline is kept,
    so line numbers stay aligned), a `/* … */` drops inclusively, an unterminated `/*` is left
    intact, and the first missing `*/` is cached so the tail is never re-scanned (O(n)).
    `blank=True` replaces comment characters with spaces instead of deleting them — see
    `strip_sql_comments`'s docstring. `sentinel` (issue #528) is what a recognized comment is
    REPLACED with instead of vanishing: deletion welded the tokens either side of the comment into
    one `\\s+`-matchable phrase, which fabricated findings out of prose in data literals. In
    `blank` mode the sentinel takes the first character of the blanked fill, so the length and
    line-count contracts are unchanged (a comment opener is never a newline).

    Operating on the interior — never on the delimiters themselves — is what keeps this
    parity-safe: a `--` at the very end of the span can delete at most up to the end of the
    interior, never the closing delimiter."""
    out: list[str] = []
    i, n = 0, len(text)
    block_close_absent = False
    while i < n:
        ch = text[i]
        if ch == "-" and i + 1 < n and text[i + 1] == "-":
            start = i
            i += 2
            while i < n and text[i] != "\n":
                i += 1
            if blank:
                fill = _blank(text[start:i])
                out.append(sentinel + fill[len(sentinel):])
            elif sentinel:
                out.append(sentinel)
            continue
        if ch == "/" and i + 1 < n and text[i + 1] == "*":
            close = -1 if block_close_absent else text.find("*/", i + 2)
            if close != -1:
                if blank:
                    fill = _blank(text[i:close + 2])
                    out.append(sentinel + fill[len(sentinel):])
                elif sentinel:
                    out.append(sentinel)
                i = close + 2
                continue
            block_close_absent = True
        out.append(ch)
        i += 1
    return "".join(out)


def strip_sql_comments(sql: str, *, blank: bool = False) -> str:
    """Strip SQL `--` line comments and `/* */` block comments, quote-aware (issue #427).

    `blank=True` (Critical, `policy_no_role_scope.py`):
    comment characters are replaced with spaces instead of deleted, so the OUTPUT IS THE SAME
    LENGTH as `sql` and a match offset maps back to the same line as the raw file — for callers
    that report per-line findings rather than a single presence/absence check. This changes
    nothing about the quote-tracking, pairing, or statement-boundary logic below: same lexing,
    same decisions about what counts as a comment, only what happens to a character once it is
    classified as one. `blank=True` also makes this function STRING-AWARE in the line-comment
    half where the guards' own ad-hoc `_LINE_COMMENT = re.compile(r"--[^\\n]*")` blankers were
    not (a `--` inside a string literal, e.g. `USING (x = 'a--b')`, no longer over-blanks past the
    literal's own close) — see the guards that switched to this mode for the exact false-negative
    shape that closes.

    A `--` or `/*` INSIDE a quoted literal/identifier is string content, not a comment, so it (and
    the SQL after it) must survive the strip — else a guard matching on that SQL never sees it (a
    silent false negative, the worst class for a scanner). Symmetrically, a quote character INSIDE a
    real comment (an apostrophe in `-- don't grant to anon`) is prose, not a string delimiter, and
    must not pair with a later quote elsewhere in the file.

    Both facts require knowing string vs comment state, which a regex cannot: it is a chicken/egg
    problem (you can't mask strings without knowing where comments are, or vice-versa). So this is a
    single stateful left-to-right scan tracking four contexts — normal / inside `'…'` / inside `"…"`
    / inside a comment — the same technique as `definer_dynamic_sql._mask_quoted`. Each character is
    emitted verbatim EXCEPT the ones inside a recognized comment, which are dropped, and the rows
    of a terminated `COPY … FROM stdin;` data section, which are blanked (issue #528, below). SQL
    escapes an inner delimiter by DOUBLING it (`'it''s'`, `"a""b"`), which stays inside the literal.

    Deletion semantics match the old `_LINE_COMMENT_SQL`/`_BLOCK_COMMENT` regexes for well-formed
    SQL: a `--` line comment drops through the char before the newline (the newline is kept, so
    consumers that map a match offset back to a line by counting `\\n` / `splitlines()` —
    `pg_function_search_path`, `pg_anon_grant` — stay aligned); a `/* … */` block drops inclusively;
    an unterminated `/*` is left intact (the old regex required a closing `*/`).

    **Dollar-quoted bodies are a BOUNDED SCOPE, not a string context** (#442). A terminated
    `$$…$$` / `$tag$…$tag$` body is lexed as code, because to Postgres it is code: a function or
    `DO` body is re-lexed as SQL or PL/pgSQL, so a `--` or `/* … */` inside one is a real comment
    and still strips. Callers depend on that: `rls-auth-uid-unwrapped` detects a `CREATE POLICY`
    inside `DO $$`, and a presence check must not credit a commented-out `ALTER TABLE … ENABLE ROW
    LEVEL SECURITY` written inside one (the definer guards mask the bodies themselves when they
    need them opaque). What the scope adds is that nothing opened inside a body can end outside it:

      * a `--` ends at the earlier of end-of-line and the body's close;
      * a `/*` is a comment only if its `*/` lies before the close, and is data otherwise;
      * a quote pairs only inside the body, and one with no partner there is a stray character;
      * the COPY head probe is off.

    Without the bound, the `/*` of `$$See docs/*.md$$` opened a comment that ran to the next `*/`
    anywhere in the file and blanked the live SQL between them. That was a silent false negative in
    guards on this lexer (measured in six, three of them regressed by #1006), and it was why the
    RLS guards' private `_blank_comments` copies could not be retired onto this function until the
    bound landed; they now call it in blank mode (#442 phase 2b). Copying #602's rule
    from `blank_block_comments` (the body is OPAQUE, no comments inside it) would break the in-body
    contract above, so the scope keeps comments and bounds them instead.

    The opener is recognized only where the scan stands at top level, so a `$$` inside `'…'`, `"…"`,
    `--` or `/* */` is not one, and with the opener rule `blank_sql_literals` uses: not glued to an
    identifier character (`x$$` is an identifier, `$1` a parameter; `x$$$` still reads its last `$$`
    as an opener, the answer `blank_sql_literals` gives too). The close is the first start of
    the same delimiter after the opener, as in Postgres. A tag with no partner before EOF earns no
    scope and is plain text, which is the pre-#442 lexing (the #602 no-partner cap). A `$tag$`
    INSIDE a body is plain text too, with no recursion, so a `/*` inside a nested body can blank at
    most within the outer one; recursing would cost O(n × depth) on hostile nesting. Both delimiters
    are emitted verbatim in both modes.

    Outside the bodies the lexing is unchanged. On input with no `$` the output is byte-identical to
    the pre-#442 lexer (differential fuzz, 200,000 inputs, both modes, zero divergence), and a
    clean-room uncached model of the scope agreed with this scan on 200,000 `$`-bearing inputs.
    Inside a body, quote PARITY can move: the `'` in `$$it's$$` used to pair with a quote after the
    body, and now it cannot. That is the Postgres-correct lex, and so was the new output in every
    divergence from the old lexer minimized out of the fuzz: a quote pairing across the close and
    protecting a real comment, a phantom `/*` or `--` from inside a body hiding a real comment
    after it, or an in-body `--` eating the close.

    Safety property, stated bounded because the unbounded version of it is false: this
    drops only characters it has positively identified as comment content, and it identifies them
    correctly EXCEPT where an unpaired quote steals a later literal's opening delimiter (issue #528),
    which resumes normal-mode lexing inside that literal and can delete real code. The REALISTIC
    source of such a quote — an apostrophe in ordinary `pg_dump` COPY data — is closed: a terminated
    `COPY … FROM stdin;` data section is opaque (the CLOSED #528 bullet below). A stray quote from
    any OTHER source still steals; that tail is pre-existing, not introduced here: the old regex
    approach deletes byte-identically on it. What this closes is the #427 FN-direction, measured at
    1136 improvements against 14 regressions over 20k quote-heavy fuzz inputs. Do not read this
    paragraph as a guarantee that real code is never dropped; the non-COPY tail of #528 is the
    standing counterexample.

    A leftover comment is NOT the harmless direction, and the earlier "mild FP-direction miss"
    wording was wrong (#435 review). Roughly half the consumer set — `public_table_rls`,
    `pg_rls_no_policy`, `policy_exists_rls_disabled`, `pg_function_search_path` — checks for the
    PRESENCE of a hardening statement, so a surviving commented-out `ALTER TABLE … ENABLE ROW LEVEL
    SECURITY` satisfies the check and the guard goes silent on genuinely unprotected SQL.

    **Comment-immunity is therefore STATEMENT-LOCAL** (the #435 re-review Critical). The invariant:
    *the comment-immunity a quote confers may never outlive the statement that granted it — and
    revoking that immunity must never move the pairing.* Those are two separate decisions, and
    keeping them separate is the whole design:

      * PAIRING (parity) — unchanged, and deliberately unbounded (`_find_sql_close`): a quote pairs
        with the next un-doubled delimiter anywhere ahead, or, finding none, is a stray character in
        data emitted as ordinary text.
      * IMMUNITY — granted only if no STATEMENT BOUNDARY lies strictly inside the span: a `;`, or
        the first character of a line whose first token starts a new SQL statement
        (`_statement_bounds`). A span that crosses one keeps its delimiters (so the lexing of
        everything after it is bit-for-bit what it was) but its interior is comment-stripped by
        `_strip_comments_unguarded`.

    Revoking immunity WITHOUT touching parity is load-bearing, not incidental. Refusing to pair
    looks equivalent and is not: it turns the span's closing delimiter into an opening one and
    re-lexes the entire tail — reintroducing exactly this bug one statement further down. That was
    caught on real SQL (a long `INSERT … VALUES ('<prompt>…')` whose prose contains a `;`): refusing
    the literal made its final `'` pair with an apostrophe in a later comment, and the `-- …`
    comments in between started surviving. Parity is never a safe thing to guess at.

    Exactly what this closes and what it does NOT — read both, an overclaim here stops a reader
    looking:

      * CLOSED: a mis-paired quote can no longer preserve comments belonging to ANOTHER statement.
        One apostrophe in a `pg_dump` COPY block (`don't panic`), or a `\\'` backslash escape in an
        `E'…'` string, used to pair with the *opening* delimiter of an unrelated well-formed literal
        later in the file (`COMMENT ON TABLE … IS 'ok';`) and preserve everything between —
        including a commented-out `-- ALTER TABLE … ENABLE ROW LEVEL SECURITY;` — verbatim.
      * CLOSED (issue #528, the realistic vector): a TERMINATED `COPY … FROM stdin;` data section
        is OPAQUE (see "Head recognition is INLINE" below). The head line is real SQL and is
        emitted verbatim; the rows and the `\\.` terminator are blanked to spaces (newlines kept,
        both modes) and never lexed — an apostrophe in dump data can no longer open or close
        anything, and a payload row that happens to look like SQL (`ALTER TABLE … ENABLE ROW LEVEL
        SECURITY` as row data) can no longer satisfy a presence-check consumer. An UNTERMINATED
        section (no `\\.` line before EOF) gets no opaqueness and is lexed as code exactly as
        before — the #602 degrade rule.
        Head recognition is INLINE (#826 review Critical 1 — the first cut pre-scanned heads over
        RAW text, and a head-shaped line inside an earlier literal could pair with a later real
        block's `\\.`, silently stripping that block of its opacity): the head regex is probed only
        at a line start the scan itself reached in normal mode, so a head-shaped line inside a
        literal or comment is structurally invisible — it cannot open a span of its own and cannot
        swallow another block's terminator. The failure direction is one-sided for the two cases
        named here — a head the probe misses, or a recognized head with no terminator ahead, only
        ever means LESS blanking of that head's own would-be payload, never more, the same "only a
        TIGHTER bound" shape `_statement_bounds` documents for itself. It is NOT a claim about the
        whole mechanism: where malformed SQL has already put the scan at top level inside content
        it should not be lexing (an unterminated `/*`, or the region after a stray quote — the NOT
        CLOSED tail below), a head recognized THERE blanks its whole row range, which is strictly
        more than the fallback lexing would have touched. That is pre-existing and unchanged by
        the inline redesign, not a new exposure, but "never more" does not cover it.
      * NOT CLOSED: two stray quotes WITHIN one statement, with no boundary between them, still
        confer immunity, so a comment between them still survives (`SELECT can't go -- it's broken`
        is unchanged). A lone `'` is genuinely ambiguous in SQL — a prose apostrophe and an opening
        delimiter are the same character — so this is BOUNDED, not eliminated: the blast radius is
        one statement instead of the whole file tail.
      * NOT CLOSED (issue #528, the non-COPY tail): revoking immunity protects a phantom span's
        INTERIOR, and nothing protects what follows its close. When a stray quote from a source the
        COPY opaqueness does not cover (a typo in hand-written SQL, an `E'…'` backslash leftover,
        an unterminated COPY section) steals a later literal's OPENING delimiter, the scan resumes
        normal-mode lexing inside that literal, so a `--`/`/*` in its ordinary string data reads as
        a comment opener and deletes real SQL after it (to end-of-line, or to the next `*/`
        anywhere ahead). Pre-existing and not a regression: the old regexes delete byte-identically
        here. It is the same mechanism as the 14-case tail in the fuzz numbers above, and the
        318-file corpus evidence is consistent with that shape not occurring in real SQL outside
        COPY data.
      * RESIDUAL, the price: a GENUINE literal that spans a `;` or a statement-start line is no
        longer opaque, so a `--`/`/*` inside such a literal is stripped — since issue #528, stripped
        TO `_REVOKED_COMMENT_SENTINEL` (U+FFFD) rather than to nothing, because bare deletion WELDED
        the tokens either side of the comment into one phrase a consumer's `\\s+` then read as real
        SQL, reporting a finding against a table that exists nowhere (the weld half of #528; the
        318-file measurement diffed stripped OUTPUT, not guard verdicts, so it could not have
        surfaced that shape). An `INSERT … VALUES ('BEGIN;\\n-- note\\nCOMMIT;')` still loses
        `-- note` (the sentinel stands in its place); a markdown prompt literal still loses an
        `---` rule. Its delimiters, its other characters, and everything after it are unaffected; a
        `--` keeps its newline but a MULTI-LINE `/* … */` inside such a literal drops inclusively
        and takes its newlines with it (the sentinel does not preserve them), exactly as an
        ordinary block comment always has in deleting mode. Single-statement literals, including
        newline-spanning ones, are untouched. Measured on 318 real-world `.sql` files: two changed
        (both a markdown `---` rule inside a long prompt literal), with no guard verdict moving.
      * RESIDUAL, the `E'…'` half specifically: honoring the escape prefix (issue #500) is
        false-negative side ON VALID SQL, and is NOT one-directional on MALFORMED SQL, where
        Postgres itself has no defined answer. Closing an unterminated `E'…` where Postgres would
        can make the literal span a `;`, which revokes its comment-immunity by the rule above, so a
        `--` inside it strips text that survived before. Reproducer, as a Python literal because the
        backslash count is the whole point:

            s = "E'---- \\';aMARK\\n\\nvalue' -- c\\n"   # one backslash before the middle quote

        `aMARK` survives on pre-#500 code and is lost here. Both directions occur and the counts are
        corpus-dependent, so none is quoted; every reduced case needs an invalid literal and no
        realistic reproducer was found (#603 review Low 1, placement corrected by the #603
        fresh-eyes review — this caveat was first written onto `blank_block_comments`, which has no
        statement-boundary logic and so cannot exhibit it).

    O(n): the `*/` search caches its first miss (`block_close_absent`) and the closing-quote
    lookahead caches its own per delimiter (`quote_close_absent`), so neither a pathological
    `"/* "*N` nor a `"'"*N` input can re-scan the tail per occurrence — the same O(n²)-DoS cap
    `strip_js_comments` uses on untrusted repo source (PR #407 r4). Revoking immunity re-scans a
    span's interior exactly once and then jumps past it, so every character is still visited a
    bounded number of times. The COPY head probe runs once per line start and each terminator
    search ends exactly where the scan resumes, so an opaque payload is visited once; a FAILED
    terminator search is latched (`copy_terminator_absent`) because a `\\.` line absent from one
    tail is absent from every later, smaller tail — unterminated heads cannot re-scan. A dollar body
    costs one delimiter match per top-level `$` and a bisect into `_index_dollar_delims`, built once
    and lazily, so a file of distinct unterminated tags stays linear (the #602 shape). Inside a body
    every lookahead stops at its close and the body has its own pair of miss caches, so a failed
    search costs at most that body, and bodies never overlap."""
    out: list[str] = []
    i, n = 0, len(sql)
    block_close_absent = False   # once `*/` is absent from the tail it is absent for every later `/*`
    bounds = _statement_bounds(sql)  # statement boundaries a span's comment-immunity may not cross
    nb, bi = len(bounds), 0          # `bi` walks `bounds` forward with the monotone `i`
    # Terminated `COPY … FROM stdin;` data sections are OPAQUE (issue #528): their rows are DATA,
    # so they are blanked, never lexed — an apostrophe in ordinary dump data can neither open nor
    # close a string, and payload text that happens to look like SQL cannot reach a consumer.
    # Recognition is INLINE (#826 review Critical 1): the head regex is probed only at a line
    # start the scan itself reached in normal mode, so a head-shaped line inside a literal or a
    # comment is structurally invisible — it cannot open a span of its own, and it cannot swallow
    # a later, genuine block's terminator the way the first cut's raw-text pre-scan could.
    copy_terminator_absent = False  # a `\.` line absent from one tail is absent from every later one
    # Miss cache per string delimiter, so the lookahead below stays O(n) overall on a `"'" * N`
    # input instead of re-scanning the tail once per quote.
    #
    # It is a MISS CACHE, not a proof of monotonicity, and the comment here used to claim the
    # latter ("once there is no closing `'` in the tail, there is none for any later one either").
    # That is false, and by doubling parity alone — no backslash escapes needed. Measured on
    # `"'''aaa''"`: `_find_sql_close(..., start=1)` is -1 while `start=2` returns 2, because the
    # first scan pairs the leading quote-run one way and the second pairs it the other. So a miss
    # recorded at one start can be served to a later start that would have closed.
    #
    # Kept anyway, with the claim corrected rather than the code: an over-eager -1 means the quote
    # is emitted as ordinary text instead of opening an opaque literal, so a `--`/`/*` inside it is
    # stripped as code. That is the SAME direction the non-string-aware line pass already takes,
    # and it is the pre-existing behavior on this path. A 1.2M-trial differential fuzz against an
    # uncached `strip_sql_comments` found zero output divergence for either cache (#500 review), so
    # this is a bound that is not tight, not a defect with a known trigger.
    quote_close_absent = {"'": False, '"': False}
    # `E'…'` scans skip backslash pairs, so they can close LATER than a plain scan, or not at all.
    # They deliberately carry NO miss cache, and must not be given the plain one to share: an
    # unclosed E-string would then tell a later ordinary `'` that the tail holds no close, moving a
    # pairing decision it never made.
    #
    # An escape-scan cache lived here until #603 review Medium 1, justified by a comment claiming it
    # "keeps this O(n) on a `E'*N` input". Both halves of that were measured false. On `"E'" * 40_000`
    # the cache is never even READ (every scan closes two characters later), which is why the test
    # pinning the claim also passed with the cache deleted. And on inputs built to maximise reads,
    # deleting it stays linear: 10 patterns, up to 32,000 cache reads at n=32,000, growth 4.0x per 4x
    # of input with and without the cache alike, worst case 30ms (#603).
    #
    # Removal is also a CORRECTNESS fix, not only a simplification. The commit that removed the cache
    # claimed output was unaffected either way, on 240,000 differential-fuzz inputs with zero
    # divergence. That claim was wrong, and a 9-character input falsifies it (#603 fresh-eyes review):
    #
    #     strip_sql_comments("e'e''--\\'")   cached -> "e'e''--\\'"   uncached -> "e'e''"
    #
    # The cached run leaves a REAL `--` comment unstripped, so a consumer sees commented-out text as
    # live SQL. The route: the unterminated `e'\` records a genuine full-tail miss, the next `e''`
    # is then served -1 from the boolean without a scan, its quote is emitted as ordinary text, and
    # its sibling is released to the main loop as a fresh plain quote that pairs with the trailing
    # `'`, swallowing the `--` as phantom string content. Rare under random fuzzing (0 to 1 hit per
    # 240,000 trials, seed-dependent) and trivial to construct deliberately.
    #
    # The reason the earlier reasoning missed it, recorded because this function has now had FOUR
    # comments assert a property it did not have: a cached miss can only ever be served to an E-quote
    # an earlier scan skipped, and an E-quote has `E`/`e` immediately before it, so it can be neither
    # half of a `\x` pair nor the second half of a `''` pair, leaving only "first half of a `''`
    # pair" — which does close at once ON A FRESH SCAN. Every step is true and the conclusion still
    # does not follow, because the cache never RUNS that fresh scan. It is a latched boolean, so
    # "would have closed at once" and "returns -1 unconditionally" are different answers. Bounding
    # the work a cache saves says nothing about the value it returns.
    #
    # Do not reintroduce a cache here on the strength of the O(1)-per-read argument. Equivalence has
    # been falsified, not merely left unproven; `test_strip_sql_escape_cache_would_have_hidden_a_real_comment`
    # pins the counterexample.
    #
    # A terminated dollar-quoted body is a BOUNDED SCOPE (#442; "Dollar-quoted bodies" above). `hi`
    # is the bound every lookahead in the loop respects: `n` at top level, and inside a body the
    # start of its closing delimiter `body_tag`. Both miss caches above describe "the tail", and a
    # miss inside one body says nothing about the file's tail, so a body gets fresh caches and the
    # top-level pair is parked in `outer_caches` until the scan leaves it.
    hi = n
    body_tag = ""
    outer_caches: tuple[bool, dict[str, bool]] = (block_close_absent, quote_close_absent)
    dollar_delims: dict[str, list[int]] | None = None  # built on the first top-level `$tag$`
    while True:
        while i < hi:
            # The COPY head probe: only at a line start this scan reached itself, in normal mode. A
            # head at EOF (no payload) or with no `\.` terminator ahead degrades to ordinary lexing —
            # the #602 rule — and the failed terminator search is latched, since no later search over
            # a smaller tail can succeed where this one failed. Off inside a dollar body (#442).
            if (i == 0 or sql[i - 1] == "\n") and not copy_terminator_absent and hi == n:
                head = _COPY_FROM_STDIN.match(sql, i)
                if head is not None:
                    nl = sql.find("\n", head.end())
                    if nl != -1:
                        term = _COPY_TERMINATOR.search(sql, nl + 1)
                        if term is None:
                            copy_terminator_absent = True
                        else:
                            out.append(sql[i:nl + 1])                   # the head line is real SQL: verbatim
                            out.append(_blank(sql[nl + 1:term.end()]))  # the rows and the `\.` are data: blanked
                            i = term.end()
                            continue
            ch = sql[i]
            if ch == "'" or ch == '"':  # string literal / quoted identifier — content may be opaque
                # Confirm the literal actually CLOSES before treating the tail as string content.
                # Consuming to EOF on an unterminated quote meant one stray apostrophe in ordinary
                # data — a `pg_dump` COPY block containing `don't` — put the whole rest of the file
                # into string context, so real `--` comments after it stopped being stripped
                # (#435 review). No malformed SQL required.
                # A Postgres `E'…'` literal escapes with a backslash whatever
                # `standard_conforming_strings` says, so its close is found with escapes ON (#500).
                escaped = ch == "'" and opens_sql_escape_string(sql, i)
                if escaped:
                    close = _find_sql_close(sql, i + 1, ch, hi, backslash_escapes=True)
                else:
                    close = -1 if quote_close_absent[ch] else _find_sql_close(sql, i + 1, ch, hi)
                if close == -1:
                    if not escaped:
                        quote_close_absent[ch] = True
                    # Not a literal: a quote with no partner is a stray character in data, not SQL
                    # string syntax. Emit it as ordinary text so the scan carries on lexing code.
                    out.append(ch)
                    i += 1
                    continue
                while bi < nb and bounds[bi] <= i:
                    bi += 1
                if bi < nb and bounds[bi] < close:
                    # The span crosses a statement boundary, so this pairing cannot be a single SQL
                    # literal — but WHICH quote is the stray one is unknowable here. Keep the pairing
                    # (parity untouched, the tail lexes identically) and revoke only the immunity: the
                    # interior is comment-stripped, so a commented-out `ALTER TABLE … ENABLE ROW LEVEL
                    # SECURITY` between two mis-paired quotes can no longer silence a guard's
                    # presence-check (#435 re-review Critical).
                    out.append(ch)
                    out.append(_strip_comments_unguarded(sql[i + 1:close], blank=blank, sentinel=_REVOKED_COMMENT_SENTINEL))
                    out.append(sql[close])
                    i = close + 1
                    continue
                out.append(sql[i:close + 1])
                i = close + 1
                continue
            if ch == "-" and i + 1 < hi and sql[i + 1] == "-":  # `--` line comment: drop to end of line
                start = i
                i += 2
                while i < hi and sql[i] != "\n":  # ... or to a dollar body's close, whichever is first
                    i += 1
                if blank:
                    out.append(_blank(sql[start:i]))
                continue
            if ch == "/" and i + 1 < hi and sql[i + 1] == "*":  # `/* … */` block comment: drop inclusively
                close = -1 if block_close_absent else sql.find("*/", i + 2, hi)
                if close != -1:
                    if blank:
                        out.append(_blank(sql[i:close + 2]))
                    i = close + 2
                    continue
                block_close_absent = True  # no `*/` in the tail: this and every later `/*` are not comments
                # No closing `*/`: not a comment (matches the old regex). Fall through and emit `/`.
            if ch == "$" and hi == n:  # a dollar-quoted body opens a bounded scope (#442)
                # Opener rule as `blank_sql_literals`: not glued to an identifier character (`x$$` is
                # an identifier, `$1` a parameter). The close is the first start of the SAME delimiter
                # past the opener, answered from the one-pass index (a per-opener `find` is quadratic
                # on distinct unterminated tags, #602). No partner: the `$` is plain text, as before.
                glued = i > 0 and (sql[i - 1].isalnum() or sql[i - 1] == "_")
                m = None if glued else _SQL_DOLLAR_DELIM.match(sql, i)  # defined with the SQL block helpers
                if m is not None:
                    if dollar_delims is None:
                        dollar_delims = _index_dollar_delims(sql)
                    starts = dollar_delims.get(m.group(0), [])
                    k = bisect_left(starts, m.end())
                    if k < len(starts):
                        out.append(m.group(0))
                        body_tag, hi, i = m.group(0), starts[k], m.end()
                        outer_caches = (block_close_absent, quote_close_absent)
                        block_close_absent, quote_close_absent = False, {"'": False, '"': False}
                        continue
            out.append(ch)
            i += 1
        if hi == n:
            break
        out.append(body_tag)  # the scan reached the body's close: emit it verbatim, back to top level
        i = hi + len(body_tag)
        hi = n
        block_close_absent, quote_close_absent = outer_caches
    return "".join(out)


def sql_code_lines(sql: str) -> list[str]:
    """`sql.splitlines()`, line for line, with every SQL comment blanked to spaces — the per-line
    view a guard scans so that a commented-out statement, a trailing `-- … SCHEMA public` or
    comment prose (`-- Step 2: Create view …`) can never match, while line `i` stays line `i` of
    the raw file (#442). What counts as a comment is `strip_sql_comments(sql, blank=True)`'s
    decision, unchanged: quote-aware, `COPY … FROM stdin;` data opaque, and a dollar-quoted body a
    bounded scope (#442), so a `/*` in `$$See docs/*.md$$` cannot blank the lines after the body.

    Sliced from that one blanked pass at the RAW lines' own offsets, never split from it. Blank
    mode keeps only `\\n` inside a comment, so a form feed, a lone `\\r` or a U+2028 there ends a
    raw line but not a blanked one, and `blanked.splitlines()` would number every later line one
    short. That would put the finding out of step with `pragma_line_set`, which numbers the raw
    file, and a pragma on the finding's own line would silently stop suppressing it."""
    blanked = strip_sql_comments(sql, blank=True)
    out: list[str] = []
    off = 0
    for line, full in zip(sql.splitlines(), sql.splitlines(keepends=True), strict=True):
        out.append(blanked[off : off + len(line)])
        off += len(full)
    return out


def iter_statement_spans(sql: str, head: re.Pattern[str]) -> Iterator[tuple[int, int]]:
    """`(start, end)` spans of each `;`-terminated statement opened by a `head` match —
    the linear replacement for a `head-pattern … [^;]*? ;` finditer.

    Guards scan **attacker-controlled SQL**, and a scan-to-terminator regex re-scans
    from every candidate head, which is O(n²) on hostile `;`-less input (issue #419).
    This does two linear forward searches per statement instead: find the head, find
    its terminator, resume after it. Yields nothing for a head with no following `;`,
    like the regex it replaced.

    The terminator is found by `find_statement_end`, so a `;` inside a single-line
    quoted name or literal is content, not an end — the ONE divergence from the regex,
    which stopped at the first `;` regardless and carved
    `CREATE POLICY "grant; select" ON …` down to `CREATE POLICY "grant;` (issue #559)."""
    pos = 0
    while True:
        m = head.search(sql, pos)
        if m is None:
            return
        semi = find_statement_end(sql, m.end())
        if semi == -1:
            return
        yield m.start(), semi + 1
        pos = semi + 1


_PG_AUTH_WS = r"[ \t\n\r\f\v]"


def pg_auth_call_pattern(*names: str) -> str:
    """Regex FRAGMENT matching a bare-OR-`pg_dump`-quoted-identifier `auth.<name>()` call, for
    any of `names` (e.g. `pg_auth_call_pattern("uid")` matches `auth.uid()` AND `"auth"."uid"()`).

    `pg_dump`/migration-tool output spells every identifier quoted (`"auth"."uid"()`); hand-
    written SQL almost always uses the bare form (`auth.uid()`). A pattern anchored to only one
    spelling is silent on whichever source produced the other — the shared root cause behind 3
    separate High findings in the PR #893 review (H3, H5, H6: quoted-identifier FPs/
    FNs in 3 different guards, each independently anchored to the bare form only). One helper,
    reused everywhere this identity check is needed, so it can't drift apart per guard.

    The negative lookbehind is load-bearing (mirrors `policy_no_role_scope.py`'s own proven
    pattern, the one guard in this codebase that already got this right): without it, a quoted
    identifier that merely CONTAINS "auth" as a suffix — a column literally named `"auth"` — set
    up so `.uid()` looks like it follows, would still (rarely) false-match; the lookbehind refuses
    to start the match right after another quote character or word character."""
    alt = "|".join(f'"{n}"|{n}' for n in names)
    return rf'(?<!["\w])(?:"auth"|auth){_PG_AUTH_WS}*\.{_PG_AUTH_WS}*(?:{alt}){_PG_AUTH_WS}*\({_PG_AUTH_WS}*\)'


# Where a GRANT/REVOKE role list ends: the trailing clauses, or the statement terminator.
_SQL_ROLE_LIST_END = re.compile(r"\bWITH\s+GRANT\b|\bGRANTED\s+BY\b|\bCASCADE\b|\bRESTRICT\b|;", re.IGNORECASE)


def sql_role_names(role_list: str) -> frozenset[str]:
    """Every role a GRANT/REVOKE role list names, lowercased and unquoted, from the text right
    after its `TO`/`FROM` (`sql_role_names('PUBLIC, "anon" CASCADE;')` is `{"public", "anon"}`).

    The list is cut at `WITH GRANT OPTION` / `GRANTED BY` / `CASCADE` / `RESTRICT` / `;`, the
    optional `GROUP` keyword is dropped, and each entry is matched whole, so `FROM public_role` is
    not `public`. A REVOKE removes only the roles it names: Supabase's default privileges grant
    `anon` and `authenticated` DIRECTLY, so `REVOKE … FROM PUBLIC` leaves both of them in place
    (#1096). A guard that asks "was this object revoked" instead of "from which roles" reads that
    statement as a lockdown. Callers compare the returned set against the roles they require."""
    out: set[str] = set()
    for part in _SQL_ROLE_LIST_END.split(role_list, maxsplit=1)[0].split(","):
        toks = part.replace('"', " ").split()
        if len(toks) > 1 and toks[0].lower() == "group":
            toks = toks[1:]
        if toks:
            out.add(toks[0].lower())
    return frozenset(out)


# `EXECUTE '…'` / `EXECUTE format('…'` up to (not including) the opening quote of its literal.
_SQL_EXECUTE_LITERAL = re.compile(r"\bexecute\s+(?:format\s*\(\s*)?(?=[eE]?')", re.IGNORECASE)


def sql_execute_literals(sql: str) -> list[str]:
    """The text of every single-quoted literal that is the argument of `EXECUTE` or
    `EXECUTE format(` in this (comment-stripped) SQL, with `''` folded to `'` (an `E'…'` literal's
    backslash escapes are left as written, so a role spelled through one is not recognised).

    A statement quoted in a string is not a statement, so a guard reading GRANT/REVOKE on a
    `blank_sql_literals_nested` view rightly ignores `RAISE NOTICE 'revoke …'`. But a plpgsql
    `EXECUTE 'REVOKE …'` runs its literal, so blanking it voids a mitigation the author wrote
    (#1100 R1-M1). A guard parses each returned text as SQL alongside its blanked view. An
    unterminated literal is skipped. A `format()` placeholder is returned as written (`%I`), which
    a caller's name or role match then rejects as unresolvable."""
    out: list[str] = []
    for m in _SQL_EXECUTE_LITERAL.finditer(sql):
        quote = sql.index("'", m.end())
        esc = opens_sql_escape_string(sql, quote)
        close = _find_sql_close(sql, quote + 1, "'", len(sql), backslash_escapes=esc)
        if close != -1:
            out.append(sql[quote + 1:close].replace("''", "'"))
    return out


# === helpers: Text & call-site scanning =====================================================================
def iter_bounded_matches(
    sql: str, head: re.Pattern[str], *tails: re.Pattern[str]
) -> Iterator[tuple[re.Match[str], ...]]:
    """Tuples of `tails` matches following a `head` match in order, all within one
    `;`-bounded statement — the linear replacement for a
    `head [^;]*? tail₁ [^;]*? … tailₙ` finditer (issue #419, same DoS class as
    `iter_statement_spans`).

    Each statement does one bounded forward search per tail. "First occurrence after
    x" is monotone in x, so when the chain fails no later head inside the same
    statement can succeed either — the scan skips straight past the `;`, and a lazy
    regex's backtracking through later tail occurrences could never have rescued the
    match (a later window is a subset of the failed one). The trailing `;` is NOT
    required (the patterns this replaces don't require one). The bound is
    `find_statement_end`, so a `;` inside a single-line quoted name or literal does not
    cut a statement short (issue #559)."""
    pos = 0
    n = len(sql)
    while True:
        m = head.search(sql, pos)
        if m is None:
            return
        semi = find_statement_end(sql, m.end())
        bound = semi if semi != -1 else n
        matches: list[re.Match[str]] = []
        cursor = m.end()
        for tail in tails:
            t = tail.search(sql, cursor, bound)
            if t is None:
                break
            matches.append(t)
            cursor = t.end()
        if len(matches) == len(tails):
            yield tuple(matches)
            pos = cursor
        elif semi == -1:
            return
        else:
            pos = semi + 1


def _string_delimiter(text: str, i: int, *, python: bool) -> str:
    """The delimiter of the string literal whose opening quote is `text[i]`.

    The one place the two call walkers below decide what closes a string, so they cannot drift
    apart. By default every quote is a one-character delimiter, which is right for JS, PHP and Java,
    and is what keeps SQL's doubled quotes (`'it''s'`) balanced. With `python`, a quote repeated
    three times opens a triple-quoted literal that only the same three characters close, as
    Python's own tokenizer reads it. Without that, an apostrophe inside a triple-quoted literal
    flipped the walker's quote parity for the rest of the call (#613)."""
    triple = text[i] * 3
    return triple if python and text.startswith(triple, i) else text[i]


def matching_close_paren(text: str, open_idx: int, *, python: bool = False) -> int | None:
    """Index of the `)` matching the `(` at `open_idx`, quote- and escape-aware.

    Mirrors `split_call_args`'s own traversal exactly (same depth/quote tracking), position-only
    — added for callers that need to know where a wrapped call ENDS (to inspect or blank its full
    span) rather than its split argument list (a bounded regex lookahead structurally
    cannot see past a `)` or a newline inside its own lookahead window, so `Depends(HTTPBearer(\\n
    auto_error=False\\n))` — multi-line, or with a nested paren before the flag — bypassed it; this
    walks the real text instead of guessing a window width). Never guesses: returns `None` on
    unbalanced parens, same contract as `split_call_args`. Pass `python=True` for Python source
    (see `split_call_args`); the two walkers take the same flag and agree on every input."""
    depth = 0
    quote = ""
    i, n = open_idx, len(text)
    while i < n:
        ch = text[i]
        if quote:
            if ch == "\\":
                i += 2
                continue
            if text.startswith(quote, i):
                i += len(quote)
                quote = ""
                continue
            i += 1
            continue
        if ch in "'\"":
            quote = _string_delimiter(text, i, python=python)
            i += len(quote)
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


def close_paren_map(text: str) -> dict[int, int]:
    """Every `(` index in `text` mapped to its matching `)`, in ONE quote-aware pass.

    For a caller that asks `matching_close_paren` about MANY calls in one file: each of those walks
    to EOF when its call never closes, so N unclosed `requests.post(` lines cost O(N * file) (PR
    #1093 round 2: 2000 such lines took 8-100 s across three guards). Same quote and escape rules,
    with two deliberate differences, both because the pass starts at the top of the file rather
    than at a `(` assumed to be code: a `(` inside a string literal is not a call and gets no
    entry, and a quote closes at the end of its line (a Python or JS single-line literal cannot
    span one, so a stray quote poisons only its own line). Unbalanced `(` get no entry, the same
    never-guess contract. Strip comments and triple-quoted strings first, as callers already do.
    `strip_python_strings` blanks a triple-quoted string's content but KEEPS its delimiters, so a
    run of three identical quote characters outside a string is skipped as one delimiter rather
    than read as three toggles. Read as toggles, the closing line of a multi-line string stayed
    "inside a string" and swallowed its own `)`, leaving the enclosing call unpaired (PR #1093
    round 3)."""
    out: dict[int, int] = {}
    stack: list[int] = []
    quote = ""
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == "\n":
            quote = ""
        elif quote:
            if ch == "\\":
                i += 2
                continue
            if ch == quote:
                quote = ""
        elif ch in "'\"":
            if text.startswith(ch * 3, i):
                i += 3
                continue
            quote = ch
        elif ch == "(":
            stack.append(i)
        elif ch == ")" and stack:
            out[stack.pop()] = i
        i += 1
    return out


def split_call_args(text: str, open_idx: int, *, python: bool = False) -> list[str] | None:
    """Split a `(...)` call's arguments on top-level commas, from the `(` at open_idx.

    Shared balanced-paren splitter: a NESTED call's own commas/parens don't leak into the
    top-level split (`f(g(a, b), c)` → `["g(a, b)", " c"]`, not four pieces). `regex_html_sanitizer`
    and `dom_xss_sinks` each still carry their own copy (pre-existing, functionally identical);
    `weak_crypto` imports this one directly rather than adding a third copy (review #395 M
    finding: a kwarg-order-sensitive `[^)]*` scan stopped at the first `)`, including one from a
    nested call like `default_backend()`, silently missing a real weak key). Returns None on
    unbalanced parens (never guesses).

    QUOTE- and escape-aware (#548 round-3 review, High 1): a `)` or `,` inside a string literal
    argument (`f.includes('note)' + 'trusted.com')`) no longer truncates the split early — the same
    class of bug `log_injection.py::_first_call_arg` was written to fix once already (#395 RM-2),
    on this exact helper, for the exact same reason. Backslash-escapes inside a quoted span are
    honored (an escaped quote char doesn't close the string); brackets/braces are NOT tracked as a
    second depth axis (pre-existing scope — a list/dict-literal argument's internal comma is not
    handled here, unchanged from before this fix).

    `python=True` reads a tripled quote (three apostrophes, or three double quotes) as one
    delimiter (#613). Pass it for Python source that still carries its string literals. The
    default treats every quote as a one-character delimiter, which a triple-quoted argument holding
    an odd count of its own quote character (an apostrophe, in the apostrophe form) desyncs: the
    call truncates early, splits to `None`, or resyncs on a later quote and resolves past its real
    end. The default stays per-character because SQL callers rely on it: four apostrophes in a row
    are a one-quote SQL literal, and a triple-aware read leaves them unclosed. A quote inside a
    COMMENT still desyncs either mode, since neither knows `#`; a caller that can see comments
    passes a comment-blanked view."""
    depth = 0
    quote = ""
    args: list[str] = []
    current: list[str] = []
    i, n = open_idx, len(text)
    while i < n:
        ch = text[i]
        if quote:
            if ch == "\\":
                current.append(text[i : i + 2])  # an escaped character never closes the string
                i += 2
                continue
            if text.startswith(quote, i):
                current.append(quote)
                i += len(quote)
                quote = ""
                continue
            current.append(ch)
            i += 1
            continue
        if ch in "'\"":
            quote = _string_delimiter(text, i, python=python)
            current.append(quote)
            i += len(quote)
            continue
        if ch == "(":
            depth += 1
            if depth > 1:
                current.append(ch)
        elif ch == ")":
            depth -= 1
            if depth == 0:
                args.append("".join(current))
                return args
            current.append(ch)
        elif ch == "," and depth == 1:
            args.append("".join(current))
            current = []
        else:
            current.append(ch)
        i += 1
    return None  # unbalanced parens — give up rather than guess


def is_llm_sdk_create_call(text: str, open_idx: int) -> bool:
    """True if the `LLM_SDK_CREATE` candidate whose `(` sits at `open_idx` is an OpenAI/Anthropic SDK call.

    A candidate is confirmed when one of its top-level arguments is `model=`, `messages=`, `prompt=`,
    `extra_body=` or a `**` spread. Those are the keyword-only SDK signature's own spellings, and a
    Twilio SMS, a Django reverse-relation create or a Webex message spells none of them (#561).

    It FAILS OPEN. When the argument list cannot be split (unbalanced parens), or `open_idx` is not a
    `(`, the answer is True, which is what every caller did before this gate existed. This is a
    narrowing gate, so the cost of a wrong False is a silent miss on a real gap. That is a failure
    which presents as success, so the gate never guesses towards it.

    Read `text` with comments blanked. `split_call_args` is quote-aware but does not know `#`: a `)` in
    a comment inside a multi-line call (a numbered note, `# 1) ...`) ends the split early and hides a
    later `model=`, and a comment's apostrophe shifts the quote pairing. Pass `router_code_view`, which
    finds comments and literals with the tokenizer. A view that pairs quotes line by line is NOT safe,
    even with its comments gone: on the row that closes a multi-line triple-quoted argument, the
    leftover delimiter pairs with `model=`'s own quote and blanks the keyword, a wrong False that no
    fail-open catches, because the argument list still splits (#1050 review).

    By design, a real call that spells none of those keywords is rejected, which is the gate's one
    under-alerting edge. A wrapper forwarding only a positional `*args` is the shape that reaches it,
    and a keyword-only SDK `create` raises on that at runtime.

    Residuals, accepted, both erring towards firing as before the gate:
      * `split_call_args` does not track `[]`/`{}` depth, so a `**` spread INSIDE a dict literal
        argument (`answers={"q": a, **rest}`) reads as a top-level spread and confirms the call. A
        `model=` cannot leak that way: a dict key is written with `:`, and a nested call's keywords sit
        inside parens the splitter does track.
      * a lambda's own comma is not a call's, so `key=lambda a, model=None: a` surfaces a top-level
        `model=`."""
    if not text.startswith("(", open_idx):
        return True
    args = split_call_args(text, open_idx, python=True)
    if args is None:
        return True
    return any(_LLM_SDK_CREATE_ARG.match(arg) for arg in args)


# A `#` line-comment: a `#` at line-start or after whitespace (a `#` mid-token is part of a value).
_HASH_COMMENT = re.compile(r"(?:^|\s)#.*$")
# A single-line quoted span (dquote: backslash-escapes honored; squote: literal, per YAML/shell).
# Masked to equal-length filler before the `#`-comment search so a `#` INSIDE quotes isn't a comment.
#
# This pattern is the SPEC, not the implementation: `_mask_quoted_spans` below produces exactly what
# `_QUOTED_SPAN.sub(lambda m: "x" * len(m.group()), s)` would, and the differential test in
# `tests/test_guards_base_perf.py` holds it to that. Keep it off the hot path. Its `.sub()` is
# quadratic on a line of `\"` pairs with no terminating bare quote (920 ms at 16 KB, x4.0 per
# doubling), which is why #493 once capped masked lines at 1 KB, and a line past the cap kept its
# comment: a silent false negative in every guard whose mitigation token could sit in that comment
# (#508).
_QUOTED_SPAN = re.compile(r'"(?:\\.|[^"\\\n])*"|\'[^\'\n]*\'')
_DQ_SPAN = re.compile(r'"(?:\\.|[^"\\\n])*"')  # the dquote half of `_QUOTED_SPAN`, tried via `.match`
_QUOTE_CHAR = re.compile(r"[\"']")


def _mask_quoted_spans(line: str) -> str:
    """`_QUOTED_SPAN.sub(lambda m: "x" * len(m.group()), line)`, byte for byte, in linear time.

    The regex is quadratic because it forgets its failures, not because the problem needs n^2.
    `.sub()` tries a span at every quote. On `"\\"\\"\\…` with no bare close, each `"` scans to
    end of line, fails, and the scan restarts one character on: O(n) starts at O(n) each. Four
    spellings of the pattern (unrolled, atomic, both) measured quadratic in #493, because the cost
    is the restart count, not backtracking. The hand-rolled scanner tried there kept the same
    restart-per-quote structure, so it was quadratic for the same reason. Two facts make every
    restart after the first failure redundant:

    * A `"` that fails dooms every later `"` up to the next `\\n`. The dquote branch cannot
      backtrack (`\\\\.` and `[^"\\\\\\n]` never agree on a first character), and its walk cannot
      cross a newline. Any `"` it passed sat in the second slot of a `\\x` pair, because an
      aligned `"` would have closed the span. A walk restarted just past that `"` is therefore in
      the alignment the failed walk already had there, and fails at the same place.
    * A `'` that fails has no `'` after it before the next `\\n`, otherwise it would have closed
      there. The next `'` the loop meets is past that newline already, so this needs no state.

    So one remembered index (where the dead dquote stretch ends) makes the scan O(n): 3.0 ms at
    16 KB, x2.0 per doubling. That index MUST expire at the `\\n`, since the lemma holds per
    newline-free segment only. Production callers pass one physical line, but this stays exact on
    any input. The single-quote newline check is bounded by the span it closes, because an
    unbounded `find` is O(rest of line) per span, which is quadratic again."""
    out: list[str] = []
    i, n = 0, len(line)
    dq_dead = -1  # every `"` at or before this index is known not to open a span
    while (m := _QUOTE_CHAR.search(line, i)) is not None:
        q = m.start()
        if line[q] == '"':
            if q > dq_dead:
                span = _DQ_SPAN.match(line, q)
                if span is not None:
                    out += (line[i:q], "x" * (span.end() - q))
                    i = span.end()
                    continue
                nl = line.find("\n", q + 1)
                dq_dead = n if nl == -1 else nl
        else:
            close = line.find("'", q + 1)
            if close != -1 and line.find("\n", q + 1, close) == -1:
                out += (line[i:q], "x" * (close + 1 - q))
                i = close + 1
                continue
        out.append(line[i : q + 1])
        i = q + 1
    out.append(line[i:])
    return "".join(out)


# THE ONE INVARIANT FOR "WHERE DOES A LINE END?" IN `strip_js_comments`
# ---------------------------------------------------------------------
# Every *grammar* question the scanner asks — where a `//` comment ends, where a `'`/`"` literal must
# have ended, where an unterminated one is capped — has ONE answer: the ECMAScript LineTerminator set
# (`_JS_STRING_TERMINATORS`), modulo LineContinuation for string literals (see `_logical_line_end`).
# Exactly ONE question is not a grammar question: "which characters may a blank() never overwrite?"
# That one is Python's `str.splitlines()` set (`_JS_LINE_BOUNDARIES`), because it governs line-number
# preservation, not parsing. Every defect in this function's five review rounds came from answering a
# grammar question with the `splitlines()` set, or vice versa. Reach for a NEW spelling of
# "line ending" here only after showing which of those two questions it answers.
#
# The invariant is one QUESTION per constant, NOT one use site. `_JS_STRING_TERMINATORS` has three
# use sites — the opener-lookahead window, the unterminated-string cap, and the `//` scan — and all
# three ask the same grammar question, so a grep that finds three is the invariant holding, not
# rotting. (The commit message that landed this block said "exactly one use site", which is false as
# worded; #440 re-gate L3. Corrected here because a commit message cannot be.)
#
# Every character `str.splitlines()` treats as a line boundary (so blanking must never replace one
# — else `raw.splitlines()` and the stripped copy diverge and every downstream line number shifts).
# This is the LINE-NUMBERING answer; it is never the grammar answer.
_JS_LINE_BOUNDARIES = "\n\r\v\f\x1c\x1d\x1e\x85  "
# The ECMAScript LineTerminator set (ES2023 §12.3): LF, CR, LS, PS — and NOTHING else. This is the
# GRAMMAR answer: the only characters a `'...'`/`"..."` literal cannot contain raw, the only ones that
# end a `//` comment, and hence the stop set for the opener lookahead, the `//` scan and the string
# cap below. Deliberately neither of its two neighbours:
#   * `_JS_LINE_BOUNDARIES` (above) also holds VT, FF, FS, GS, RS and NEL, none of which end a JS
#     line. Using it as the lookahead stop refused to open a LEGAL string containing one of them
#     (`"a\x0bb//fake"`), so the body read as CODE, the `//` inside it read as a real comment, and a
#     real sink after it was deleted — the exact class this fix exists to close, reintroduced through
#     a different trigger (#440 re-gate, CRITICAL). Using it as the `//` scan's stop was the mirror
#     image: the comment ended early at a VT/NEL and *commented-out* code reached the guards (#440
#     gate F5, a live false positive).
#   * `_JS_LINE_TERMINATORS` additionally holds NEL (U+0085), which is not an ES LineTerminator
#     either. Inside `strip_js_comments` it survives for ONE use: the unterminated-regex BAIL below,
#     where stopping EARLY is the safe direction (the scan resumes in code mode and nothing is
#     blanked), so a deliberately conservative set is right there and wrong everywhere else in this
#     function. `blank_block_comments` also reads it, for the HCL/SQL string line-bail - a different
#     dialect's question about where a *string* ends, not this one's about where a JS line ends.
#     Three live sites total: one here, two there. (The earlier wording said "ONE use" flat and
#     named the reuse forbidden, which reads as a claim that the two `blank_block_comments` sites
#     should not exist - the same false-as-worded shape corrected for `_JS_STRING_TERMINATORS` two
#     bullets up. #440 review.)
_JS_STRING_TERMINATORS = "\n\r  "
# Deliberately conservative bail-out set for the unterminated-regex scan — see above. NOT a claim
# about where a JS line ends; do not reuse it for a blanking decision *inside `strip_js_comments`*.
# (`blank_block_comments` legitimately uses it for the HCL/SQL string line-bail, a different call.)
_JS_LINE_TERMINATORS = "\n\r  \x85"
# Keywords after which a `/` begins a regex literal, not a division (they end in an identifier char
# yet are not values). Used by the regex-vs-division heuristic below.
_REGEX_PRECEDING_KEYWORDS = frozenset({
    "return", "typeof", "instanceof", "in", "of", "new", "delete", "void",
    "do", "else", "yield", "await", "throw", "case",
})
# Keywords whose `(...)` is a control-flow HEAD, not a call — so a `/` right after the closing `)`
# opens a regex (`if (cond) /re/.test(x)`), unlike `call(...) / 2` division (PR #407 r3 review).
_CONTROL_KEYWORDS = frozenset({"if", "while", "for", "switch", "catch", "with"})
# Every ECMAScript keyword `K` for which `K'...'` — a string literal ABUTTING the keyword, no space —
# is grammatically legal somewhere in the language. See `_quote_is_jsx_apostrophe` for why this is the
# deciding set, and why it is NOT `_REGEX_PRECEDING_KEYWORDS` (a different question: which tokens may
# precede a REGEX rather than a division). The two overlap but neither implies the other; conflating
# them silently dropped CRITICAL findings for `from`/`default`/`extends`/`as`/`static` (#440 re-review).
#
# The enumeration is CLOSED and derived, not sampled: JS has a fixed, spec-defined keyword vocabulary,
# so "keywords that may abut a string" is finite and enumerable, unlike the open set of identifiers.
# Each entry below was verified against the real V8 parser (`node`, ES2024) by finding one legal
# program containing `K'a'`, and every keyword NOT listed was verified to have NO such program:
#   return/throw/typeof/void/delete/new/await/yield  expression operand   (`return'a'`)
#   in/instanceof                                    binary RHS          (`x in'a'`)
#   of                                               for-of head         (`for (const a of'b')`)
#   case/do/else                                     statement position  (`case'a':`)
#   import/from/default/extends/as                   module + class head (`import t from"x"`)
#   static/get/set/async                             class/object member (`class C{static'a'(){}}`)
# Deliberately EXCLUDED — `let`, `var`, `const`, `class`, `function`, `if`, `for`, `while`, `switch`,
# `break`, `continue`, `try`, `catch`, `finally`, `export`, `enum` (each requires an identifier, a
# parenthesis or a block next, so `K'a'` never parses) and the VALUE keywords `this`/`super`/`true`/
# `false`/`null` (a quote after a value is a syntax error). Excluding them is what keeps JSX prose
# like `<p>Let's go</p>` and `<p>the class's name</p>` correctly read as apostrophes.
# TypeScript-only keyword positions (`satisfies`/`keyof`/`is`, and the class-member modifiers
# `public`/`private`/`readonly`/...) are excluded on purpose: no TS emitter or formatter produces the
# abutting form, and those words are common English possessives in JSX prose, so including them would
# cost more than it buys.
_STRING_ABUTTING_KEYWORDS = frozenset({
    "return", "throw", "typeof", "void", "delete", "new", "await", "yield",
    "in", "instanceof", "of", "case", "do", "else",
    "import", "from", "default", "extends", "as",
    "static", "get", "set", "async",
})


def _last_unescaped_quotes(text: str, start: int, end: int) -> dict[str, int]:
    """Position of the LAST unescaped `'` and `"` in `text[start:end)`, or -1 if absent.

    One pass per line, so the caller's per-quote "does this close before the line boundary?"
    question is O(1) and the whole scan stays linear. Backslash parity is counted the way a
    string body sees it: a delimiter preceded by an ODD run of `\\` is escaped.

    Parity is counted back to the TRUE start of the run, not to `start` — escape status is a
    property of the text, not of where this window happened to begin. That is the identical
    correction `_logical_line_end` makes below, and the two must answer the identical question
    identically (#440 re-gate L2). Inert as the caller stands today (a window only ever begins at a
    raw LineTerminator or at index 0, so no backslash run can straddle `start`), so this is a
    consistency fix, not a behaviour change — pinned both ways by
    `test_quote_parity_is_counted_to_the_true_run_start` (the unit-level difference) and
    `test_the_parity_correction_changes_no_strip_js_comments_output` (the inertness). Still O(n):
    runs are disjoint across the line starts this is called at.
    """
    last = {"'": -1, '"': -1}
    k = start - 1
    while k >= 0 and text[k] == "\\":
        k -= 1
    j, backslashes = start, start - 1 - k
    while j < end:
        ch = text[j]
        if ch == "\\":
            backslashes += 1
        else:
            if ch in last and backslashes % 2 == 0:
                last[ch] = j
            backslashes = 0
        j += 1
    return last


def _logical_line_end(text: str, start: int, n: int) -> int:
    r"""End of the LOGICAL JS line containing `start` — the window for the opener lookahead.

    A `'...'`/`"..."` literal cannot contain a RAW LineTerminator, but it CAN contain a
    **LineContinuation** — a `\` immediately followed by one (ES2023 §12.9.4.1) — and that carries the
    literal onto the next physical line. So the window must NOT stop at a terminator whose preceding
    run of `\` is ODD: the literal's closing quote legitimately lies beyond it.

    This is the half of the grammar the previous round got wrong. Its comment asserted "a quote with
    no unescaped partner before the line boundary was never an opener … one that does not close on its
    line is not valid JS" — false for exactly this construct. The cost of believing it: the opener is
    refused, the body is scanned as CODE, a `//` inside it (very commonly a URL — `https://`) reads as
    a real comment, and the rest of that physical line is blanked, deleting a real sink (#440 gate F2,
    CRITICAL). The `\<CR><LF>` form counts as ONE terminator sequence, so it is skipped whole.

    Backslash parity is counted back to the true start of the run (not to `start`): whether a
    terminator is escaped is a property of the text, not of where this window happened to begin. Runs
    are disjoint per terminator, so the whole scan stays O(n).
    """
    j = start
    while j < n:
        if text[j] in _JS_STRING_TERMINATORS:
            k = j - 1
            while k >= 0 and text[k] == "\\":
                k -= 1
            if (j - 1 - k) % 2 == 0:  # even run (incl. none) → a RAW terminator: the line really ends
                break
            if text[j] == "\r" and j + 1 < n and text[j + 1] == "\n":
                j += 1  # `\<CR><LF>` is one LineTerminatorSequence — the continuation covers both
        j += 1
    return j


def _word_before(text: str, pos: int) -> str:
    """The identifier immediately before `pos` (skipping whitespace), or '' if none."""
    j = pos - 1
    while j >= 0 and text[j].isspace():
        j -= 1
    end = j + 1
    while j >= 0 and (text[j].isalnum() or text[j] in "_$"):
        j -= 1
    return text[j + 1:end]


def _member_access_before(text: str, pos: int) -> bool:
    """True if the identifier immediately before `pos` is a property/method access (`.name`).

    `obj.if(...)` uses a reserved word as a member name — legal JS, and NOT a control-flow head, so
    the `(` must not be treated like an `if (...)` head (PR #407 r4)."""
    j = pos - 1
    while j >= 0 and text[j].isspace():
        j -= 1
    while j >= 0 and (text[j].isalnum() or text[j] in "_$"):  # skip the identifier
        j -= 1
    while j >= 0 and text[j].isspace():  # `obj . if(` — allow whitespace around the dot
        j -= 1
    return j >= 0 and text[j] == "."


def _quote_is_jsx_apostrophe(text: str, pos: int, c: str) -> bool:
    """True if the `'`/`"` at `pos` is JSX TEXT punctuation rather than a string OPENER.

    A `'`/`"` directly after an identifier character cannot open a string in ordinary JS (`x'`
    is not valid), so it is an apostrophe in JSX text content — `<p>It's fine</p>` — which must
    not be paired with the next quote on the line (that blanked everything between, deleting a
    CRITICAL DOM-XSS sink on the same line; #440 review).

    THE INVARIANT: **a `'`/`"` abutting a preceding word W opens a string literal if and only if
    `W'...'` is legal JS — i.e. iff W is a keyword after which a string may begin; for every other W
    (a plain identifier, a number, or a VALUE keyword like `this`/`true`) `W'...'` cannot parse at
    all, so the only reading left is JSX text.** That is the whole specification, and
    `_STRING_ABUTTING_KEYWORDS` is exactly its (closed, spec-bounded, V8-verified) keyword side.

    The single preceding CHARACTER cannot tell `It's` from `return'x'` — both are `<letter>'` — which
    is why the test is the WORD, not one char. Getting the word's side wrong is a CRITICAL: missing a
    real opener leaves the scan in "code" mode INSIDE the string, so a `//` in the string body reads as
    a real line comment and blanks the rest of the line, deleting whatever followed. That happens at
    BOTH `strip_strings` settings (quote tracking governs comment detection regardless of the flag),
    and `import t from"https://cdn/x.js";<sink>` — plain esbuild output — is the common case.

    An EARLIER fix answered a different question by mistake: it gated on `_REGEX_PRECEDING_KEYWORDS`,
    the set of tokens after which a `/` starts a REGEX rather than a division. That set happens to
    contain `return`/`throw`/`case`/`typeof`, so those looked fixed, while `from`/`default`/`extends`/
    `as`/`static` — absent from it, because a regex cannot follow them — kept silently deleting sinks
    (#440 re-review). Regex-may-follow and string-may-abut are independent properties; derive this one
    from the grammar, never from that list.

    The member-access branch stays, on the invariant rather than on analogy: `obj.return` is a
    property access, hence a VALUE, and `obj.return'x'` is a syntax error (`node --check` confirms) —
    so a reserved word used as a member name never introduces a string, and `<span>{u}.default's</span>`
    stays an apostrophe. (This is NOT the same reason as the `/`-site's mirror of it there, where
    `obj.return / 2` is legal division; that analogy would be false here.)

    Backticks are excluded entirely: a tagged template literal (``tag`...` ``) legitimately
    follows an identifier."""
    if c == "`" or pos == 0:
        return False
    if not (text[pos - 1].isalnum() or text[pos - 1] in "_$"):
        return False
    return not (_word_before(text, pos) in _STRING_ABUTTING_KEYWORDS
                and not _member_access_before(text, pos))


def _js_regex_can_start(text: str, slash_i: int, prev: str, paren_was_control: bool) -> bool:
    """Heuristic: does the `/` at `slash_i` open a regex literal (vs. a division operator)?

    `prev` is the last significant (non-whitespace) source char before it; `paren_was_control` says
    whether the most recently closed `)` closed a control-flow head. A `/` opens a regex when it
    follows an operator / opener / statement start — NOT a value (identifier, number, `]`, `.`,
    string, or a call's `)`). Exceptions: a regex-preceding keyword (`return /re/`), and a `)` that
    closed an `if (...)`/`while (...)` head. `}` stays "division" (block-vs-object is ambiguous
    without a fuller parse) — a documented residual: the unterminated-`/*` cap below neutralises its
    *cross-file* consequence, but a same-line `}`-regex truncation can still drop a same-line finding."""
    if prev == "" or prev in "([{,;:=!&|?*/%^~<>":
        return True
    if prev in "+-":  # postfix `++`/`--` yields a VALUE (division); unary/binary +/- allows a regex
        j = slash_i - 1
        while j >= 0 and text[j].isspace():
            j -= 1
        return not (j - 1 >= 0 and text[j - 1] == text[j])  # `++`/`--` → division
    if prev == ")":
        return paren_was_control
    if prev in "]}." or prev in "'\"`":
        return False
    if prev.isalnum() or prev in "_$":  # could be a keyword like `return`/`typeof`
        # ...but a reserved word used as a MEMBER name (`obj.return`, `x.in`) is a value, not a keyword,
        # so a following `/` is division — mirror the control-head `(` site's member-access guard.
        return (_word_before(text, slash_i) in _REGEX_PRECEDING_KEYWORDS
                and not _member_access_before(text, slash_i))
    return True


def _js_regex_end(text: str, body_start: int, n: int) -> tuple[int, int]:
    """Scan a regex literal's body from `body_start` (just past its opening `/`).

    Returns `(body_end, stop)`: `body_end` is the index of the closing `/`, or -1 if the literal does
    not close before a line terminator (an unterminated regex never crosses a line), and `stop` is
    the index just past the closing `/`, or where the scan bailed. Flags are not consumed. A `\\`
    escapes the next char and a `[...]` class may hold a bare `/`. The one copy of this rule, shared
    by code mode and the `${ … }` sub-lexer (#543), because this function's history is copies of one
    lexer rule drifting apart."""
    i, in_class = body_start, False
    while i < n:
        ch = text[i]
        if ch == "\\":
            i += 2
            continue
        if ch in _JS_LINE_TERMINATORS:
            return -1, i
        if ch == "[":
            in_class = True
        elif ch == "]":
            in_class = False
        elif ch == "/" and not in_class:
            return i, i + 1
        i += 1
    return -1, i


def _regex_body_may_blank(text: str, slash_i: int) -> bool:
    """May `strip_regex` blank the body of the regex literal `_js_regex_can_start` found at `slash_i`?

    No whenever the source char before the `/` says no real regex can start there, so the "regex"
    is a misread whose body would be real code (#909). The char is read from `text`, not from the
    lexer's `prev`, because `prev` is set to `)` after a string, template or regex closes. That routes
    the `/` through `paren_was_control`, which still describes the last REAL `)`, so after an
    `if (ok)` a JSX `<A b="c" />` reads as a regex start and its "body" runs to the next `/` on the
    line. Seen in a real `.tsx` file in a 10k-file corpus. The other refusals are JSX: a closing
    tag `</label>` puts `<` before the `/`, and JSX text that starts with one (`<nav>/ {…} /</nav>`)
    puts a bare `>` there. `=>` stays allowed: `s => /re/.test(s)` is the common real form. Linear
    overall: the look-back covers only the whitespace run before this `/`."""
    j = slash_i - 1
    while j >= 0 and text[j].isspace():
        j -= 1
    if j < 0:
        return True
    ch = text[j]
    if ch in "<'\"`":
        return False
    return not (ch == ">" and (j == 0 or text[j - 1] != "="))


def _after_non_null_assertion(text: str, slash_i: int) -> bool:
    """Is the `/` at `slash_i` preceded by a TypeScript non-null assertion (`x! / 2`), so division?

    `_js_regex_can_start` reads any `!` as an operator, so a `/` after one opens a regex. After a
    value, a glued `!` is the postfix assertion and the `/` divides. The `${ … }` sub-lexer asks
    this because a misread there runs to the next `/` on the line and can swallow the substitution's
    `}` and closing backtick (#1124 round 1, H2). A regex-preceding keyword glued to the `!`
    (`return!/re/.test(s)`, common in minified code) is still a negation. Linear: the look-back
    covers the whitespace run and the one word before the `!`."""
    j = slash_i - 1
    while j >= 0 and text[j].isspace():
        j -= 1
    if j < 1 or text[j] != "!":
        return False
    before = text[j - 1]
    if before in ")]":
        return True
    if not (before.isalnum() or before in "_$"):
        return False
    return not (_word_before(text, j) in _REGEX_PRECEDING_KEYWORDS and not _member_access_before(text, j))

def _closes_on_this_line(text: str, quote_i: int, n: int) -> bool:
    r"""Is the `'`/`"` at `quote_i` really a string opener, judged by its own LOGICAL line?

    Used only inside a template substitution, whose sub-lexer is lighter than code mode. Comments and
    regex literals there are consumed whole since #543, but an apostrophe it still fails to place
    reaches this test looking like a delimiter: JSX text (`${ <b>it's</b> }`), or a regex it read
    as division. Opening a string on one swallowed the rest of the FILE and silently deleted real
    sinks (#542 review, H1).

    ES2023: a `'`/`"` literal excludes a raw LineTerminator, so a quote with no partner before the
    line ends was never an opener. But it may contain a **LineContinuation** (`\` immediately before
    the terminator, 12.9.4.1), which legally carries the literal onto the next physical line — so the
    window is the logical line, and a terminator preceded by an ODD backslash run does not end it.
    That distinction is not hypothetical: refusing a continued literal is the exact class #440's
    re-gate found and paid for on the sibling predicate, and re-deriving it without the continuation
    case would reintroduce it here.

    Escapes inside the line need no special handling: an escaped `\'` found as the partner still
    opens the string, and the scanner's own escape branch then consumes it correctly.
    """
    j = quote_i + 1
    while j < n:
        ch = text[j]
        if ch == text[quote_i]:
            return True
        if ch in _JS_LINE_TERMINATORS:
            backslashes = 0
            k = j - 1
            while k > quote_i and text[k] == "\\":
                backslashes += 1
                k -= 1
            if backslashes % 2 == 0:  # a real line end — the literal cannot reach past it
                return False
            if ch == "\r" and j + 1 < n and text[j + 1] == "\n":
                j += 1  # CRLF is one terminator
        j += 1
    return False


def _strip_js_comments_uncached(
    text: str, *, strip_strings: bool = False, strip_regex: bool = False, keep_substitutions: bool = False
) -> str:
    r"""Blank JS/TS `//` and `/* */` comments (and optionally string literals), preserving layout.

    A small **string- and regex-literal-aware** scanner: a `//` line comment or a `/* */` block
    comment (including a JSDoc `/** */`) is replaced by spaces so a guard's regex never matches a
    commented-out or documented example of the very pattern it detects — the recurring false-positive
    class in the njsscan JS guards (a `// nodeIntegration: true was here` note, a JSDoc mentioning a
    vulnerable call). A `//`/`/*` appearing INSIDE a string, template literal, or **regex literal** is
    correctly not treated as a comment — the latter matters because a real regex like `/\//g` or an
    Express path matcher `/^\/api\//` embeds a `//` sequence that a naive scanner would misread as a
    comment and blank the rest of the line, silently dropping real findings (PR #407 review). Unlike a
    naive `^\s*//` check, a trailing `code(); // ...` comment after real code is stripped too. Every
    blanked character becomes a single space and every `str.splitlines()` boundary character is left
    intact, so line numbers AND column offsets computed from the result map back to the source.

    `strip_strings=True` additionally blanks the CONTENTS of string/template literals (keeping the
    delimiters), for a guard whose match must not fire on a pattern appearing only inside a string
    literal — e.g. `req.` inside `'req.count: total'` (a hardcoded label, not request input). Off by
    default: several guards legitimately match a string VALUE (a header name, `'*'`). Template-literal
    interpolation (`${expr}`) is treated as string content, so a `${req.x}` is blanked under
    `strip_strings` — a conservative, documented limitation (a false negative, never a false positive).
    `strip_strings` does NOT touch regex literal bodies: they stay as code under either setting.
    `strip_regex=True` (independent, opt-in) blanks a regex literal's BODY, keeping both `/` delimiters
    and the flags, for a consumer that walks bracket/quote structure and must not count the `}` of
    `/}/g` or the `'` of `/'/g` as code (dom-xss-sinks' timer scan, #909). It is deliberately not folded
    into `strip_strings`, which many guards consume and none was reviewed against. Because it turns a
    regex-vs-division misread from "a `//` inside is not a comment" into "the text between two slashes
    is gone", it blanks only a regex that CLOSED on its own line and whose preceding source char admits
    a real regex (`_regex_body_may_blank`: never after a string, template, `<` or bare `>`).
    Template literals **nest**, and the nesting is tracked as a STACK of frames, one per open backtick,
    each counting the unmatched `{` of the substitution it is inside (#541). A single active-delimiter
    char cannot model that: the inner backtick of ``` `a ${ `b` }` ``` matched the outer delimiter and
    closed it, leaving the scanner in CODE mode inside a string — so a `//` in the body (usually a URL)
    became a comment and blanked the rest of the physical line, deleting real sinks for every consumer.
    A `}` that belongs to an object literal or sits inside a string within the substitution therefore
    does not end it, and substitution content remains string content exactly as described above.
    A comment or regex literal inside a substitution is consumed whole before any delimiter test, so
    a `{`/`}`/quote/backtick inside it (`${ v.replace(/{/g,"") }`, `${ x /* } */ }`) cannot shift the
    frame (#543). Before that fix one unbalanced brace kept the template open to EOF, and a pair of
    them (a `/{/` in one substitution, a `/}/` in a later one) rebalanced and read the code between
    them as template text. Regex-vs-division there uses the code-mode heuristic below, with no
    control head possible (a substitution is an expression), and only a regex that closes on its line
    is consumed. What BOUNDS any desync still unknown: a template still open at EOF is
    restored VERBATIM from its opener, because a frame that never unwinds means nothing after that
    point was reliably classified, so a misparse that ends that way degrades to "this region was not
    stripped" and never to "this sink was deleted" (#542 re-gate).
    This is a DIFFERENT mechanism from the unterminated-`/*` cap below, and the difference is the whole
    cost: `/*` merely declines to blank forward, so later comments are still stripped, whereas this
    **un-blanks a region already scanned** — a commented-out example inside it comes back and can fire.
    Recovery and that false positive are one mechanism, measured 1:1, and cannot be separated without a
    real parser. The trade is deliberate (a visible FP over an invisible deletion) and is pinned by
    `test_..._the_cap_revives_comments_after_a_desync_accepted_trade`. It is rare in practice: on
    112,514 real js/ts files the cap fires on 16, all vendor, and none the repo walk actually scans.
    Note it only changes `strip_strings=True` output — in default mode a still-open template's contents
    were never blanked in the first place, so restoring them is a no-op.
    A second cap covers the PAIRING itself (#910). A stray backtick — a missing closer on a CSS-in-JS
    template, a lone one in JSX prose — pairs with the next unrelated backtick and the real code between
    them is blanked as template text; that pairing CLOSES, so the EOF cap above never reaches it. The
    whole-file signal is parity: one stray delimiter always leaves the delimiter count odd, and an even
    count with blanked code is either two or more lexical errors or valid JS whose string content looks
    like code (correctly blanked). On an odd count every CLOSED outermost template span is restored
    verbatim; comments and plain strings blanked in code mode stay blanked, which is what keeps an
    earlier valid template's trailing `// example` silenced. The cost is that earlier template's own
    content coming back, pinned by `test_..._parity_revive_restores_earlier_templates_accepted_trade`;
    on 65,480 real js/ts files (21,427 with a backtick) it changes 2, both vendor, with no consumer
    finding changing on either. Like the EOF cap, a revived template can carry a brace into a
    consumer's structural walk, so a consumer that walks structure must skip literals itself rather
    than trust this blanking (`dom-xss-sinks`' `_match_bracket` does, #909).
    Regex-vs-division uses a lightweight char/keyword heuristic (not a full JS parse). A `/` right
    after a control-flow head's `)` (`if (x) /re/`) is correctly a regex via a small paren-kind stack;
    a `/` after `}` is read as division (block-vs-object literal is ambiguous without a fuller parse) —
    a documented residual. Its **cross-file** consequence — a mis-read regex embedding a `/*` that
    would run the block-comment scan to end-of-file — is capped: an **unterminated** `/*` (no `*/`
    before EOF) is NOT blanked, so a mis-classification can never blank across the file (and that cap
    is O(n): the first missing `*/` is cached, never re-scanned). A same-line `}`-regex truncation
    (`if (x) { } /^\d+\//.test(p); flag`) can still drop a *same-line* finding — a known, line-scoped
    residual (the `}` block-vs-object ambiguity), not fixed by the cap.

    `keep_substitutions=True` is the ANCHOR mask (#749), meaningful only with `strip_strings=True`. It
    blanks plain-string content and template TEXT exactly as `strip_strings` does, but keeps the code
    inside a `${ … }` substitution, so a guard can ask whether a match it found on the default view
    sits in live code or in quoted text: a call spelled out in a string (a docs example, an error
    message) is blanked, and a real call nested in a substitution (`` `${execSync(cmd)}` ``) survives.
    Matching on plain `strip_strings=True` output instead deletes that nested sink, a CRITICAL false
    negative that no guard test noticed (measured, #749). Only the substitution's own code is kept: a
    plain string inside it is still blanked (both delimiters kept, as in code mode), so is a nested
    template's text, and so are the `${`/`}` delimiters, any comment, and any `\`-escape pair
    (outside a string, one can only sit in a regex literal there; the rest of that regex, delimiters
    and flags included, stays code). Both restore caps apply here too: a desync still open at EOF, or
    one that leaves the delimiter count odd, comes back as source, so every anchor in it reads as
    code. Neither cap covers a desync that REBALANCES, the parity paragraph's "two or more lexical
    errors", where the code between the two errors reads as template text and an anchor there is
    dropped. The one known rebalancing shape, a `{` in a regex or comment inside one substitution and
    a `}` in a later one, is lexed correctly since #543: its code stays code, pinned by
    `test_strip_js_comments_anchor_mask_rebalancing_regex_pair_reads_as_code`. Test an anchor with
    `js_anchor_is_code`.

    A quote's own mis-classification is capped the same way. Deciding whether a `'`/`"` abutting a word
    OPENS a string or is JSX text (`<p>It's</p>`) is a heuristic — see `_quote_is_jsx_apostrophe` — so
    it can err in both directions. To bound the cost, a `'`/`"` only opens when an unescaped partner
    exists before the end of its **logical** JS line, and an unterminated one is closed at that
    boundary: a raw line terminator cannot appear inside one (ES grammar), so a quote still "open"
    there was never an opener. **Logical** is load-bearing and is NOT `str.splitlines()`: the line ends
    at an ES LineTerminator (LF/CR/LS/PS — a VT/FF/NEL is not one), and a LineContinuation (`\` + a
    LineTerminator) carries a literal past one (`_logical_line_end`). So a quote error is confined to
    one *logical* line, which may span several `splitlines()` lines — it can never desync the rest of
    the file. Template literals are exempt (they legitimately span lines).

    That partner test is FLAT, which bounds what it can promise (#558). `_last_unescaped_quotes`
    counts every unescaped quote on the logical line, so a quote that is not really an opener (invalid
    JS, or a `_quote_is_jsx_apostrophe` miss) can pair with a quote inside a LATER template, string,
    comment or regex: ``return 'oops; el.innerHTML = u; const t = `it's`;`` blanks the sink under
    `strip_strings`, and a real `//` in such a span is hidden from comment detection. Making the
    lookahead skip template spans does not fix it, because which spans are templates depends on
    whether this quote opens a string: ``'it`s'`` (valid, must open) is identical to the line above up
    to the partner. Measured, that change altered 42 of 9,517 real js/ts files under `strip_strings`,
    all of them free of TypeScript syntax errors, while a TypeScript-parser oracle found the defect in
    none of their 522,733 openers. A deleted sink stays on the logical line. With the partner in a
    string, comment or regex nothing is swallowed, and the false string just closes on it. With the
    partner in a template, one backtick is swallowed and the stray one after the partner opens a
    template; the EOF and parity caps above restore source from there on, so later code survives. The
    price is theirs: a commented-out line after the stray, to EOF, reads as live code. Pinned as
    an accepted residual by
    `test_a_false_opener_pairs_with_a_quote_in_another_construct_accepted_residual` and its
    neighbours (the bound and the comment cost each have their own), with
    `test_a_real_string_holding_a_backtick_still_opens` as the FP-bait any future fix must keep green."""
    out = list(text)
    i, n = 0, len(text)
    quote = ""  # the active ' or " delimiter while inside a plain string, else "" (backticks: `tpl`)
    prev = ""   # last significant (non-whitespace) source char, for the regex-vs-division heuristic
    paren_kinds: list[bool] = []   # per open `(`: True if it is a control-flow head (`if (`/`while (`)
    paren_was_control = False      # whether the most recently closed `)` closed a control head
    block_close_absent = False     # once `*/` is absent from the tail it is absent for every later `/*`
    regex_fail_end = -1  # where the sub-lexer's last unclosed regex scan bailed, so it is not rescanned
    line_end = -1                  # end of the LOGICAL line containing `i` — see `_logical_line_end`
    last_quote = {"'": -1, '"': -1}  # last unescaped `'`/`"` on that line — see `_last_unescaped_quotes`
    # Template-literal frames — one per OPEN backtick, innermost last (#541). A template's
    # substitutions are not flat text: `${ … }` may hold a nested template, which may hold its own
    # `${ … }`, so the nesting is a pushdown, not a flag. Tracking it in a single `quote` char is
    # what caused the desync: the nested opening backtick matched `c == quote` and closed the OUTER
    # literal, leaving the scanner in CODE mode while physically inside a string — after which a
    # `//` in the body (very commonly a URL) read as a real comment and blanked the rest of the
    # physical line, deleting genuine sinks from the scan for every consumer.
    #   frame value  -1  → in that template's TEXT
    #   frame value >=0  → inside one of its `${ … }` substitutions, holding the count of
    #                      unmatched `{` so an object literal (`${ {a:1}.a }`) does not end it early.
    # Substitution CONTENT is still BLANKED as string content under `strip_strings` — but, unlike
    # before, it is now SCANNED for `'`/`"` and `{`/`}` so the frame survives an object literal or a
    # `}` inside a string. Do not read that as "the substitution path is unchanged": this sub-lexer
    # is new, and it is where #542's H1 lived. Comments and regex literals inside a substitution are
    # consumed whole before those tests, so their braces, quotes and backticks are inert (#543).
    # One deliberate bound remains: a quote is only an opener if it CLOSES on its own logical line
    # (`_closes_on_this_line`). The sub-lexer is lighter than code mode (no control-head tracking,
    # the `}`-then-`/` regex residual), so an apostrophe it fails to place inside a regex would
    # otherwise open a string that runs to EOF.
    tpl: list[int] = []
    tpl_quote = ""  # the ' or " delimiter of a string inside the innermost substitution, else ""
    tpl_root = -1   # offset of the OUTERMOST open backtick, for the unterminated blast-radius cap
    tpl_delims = 0  # template-DELIMITER backticks seen — never one inside a string/comment/regex (#910)
    tpl_closed_spans: list[tuple[int, int]] = []  # every CLOSED outermost template, for the parity cap

    def blank(j: int) -> None:  # replace with a space, but never a line-boundary char (keeps alignment)
        if text[j] not in _JS_LINE_BOUNDARIES:
            out[j] = " "

    while i < n:
        if i >= line_end:  # crossed into a new LOGICAL line — refresh the quote lookahead (O(n) total)
            line_end = _logical_line_end(text, i, n)
            last_quote = _last_unescaped_quotes(text, i, line_end)
        c = text[i]
        if tpl:  # inside a template literal, at some nesting depth
            if tpl_quote:  # a plain string inside a substitution — braces in it are not braces
                if c == "\\":
                    if strip_strings:
                        blank(i)
                        if i + 1 < n:
                            blank(i + 1)
                    i += 2
                    continue
                if c == tpl_quote:
                    tpl_quote = ""
                    if keep_substitutions:  # a string in substitution CODE keeps its closer, like its opener
                        i += 1
                        continue
                if strip_strings:
                    blank(i)
                i += 1
                continue
            if c == "\\":  # escape — `\`` does not close the template
                if strip_strings:
                    blank(i)
                    if i + 1 < n:
                        blank(i + 1)
                i += 2
                continue
            if tpl[-1] < 0:  # template TEXT
                if c == "`":  # this template closes (delimiter kept)
                    tpl.pop()
                    tpl_delims += 1
                    if not tpl:  # the OUTERMOST frame closed — its span is what the parity cap may revive
                        tpl_closed_spans.append((tpl_root, i + 1))
                    prev = ")"  # a template literal is a value → a following `/` is division
                    i += 1
                    continue
                if c == "$" and i + 1 < n and text[i + 1] == "{":  # a substitution opens
                    tpl[-1] = 0
                    prev = "{"  # an expression starts here, so a `/` may open a regex (`${ /re/ }`)
                    if strip_strings:
                        blank(i)
                        blank(i + 1)
                    i += 2
                    continue
            else:  # inside a `${ … }` substitution
                # A comment or a regex literal is consumed WHOLE before any delimiter test, so a `{`,
                # `}`, quote or backtick inside it cannot touch the frame (#543). Blanking follows the
                # substitution-content rule below (`strip_strings`, not under the anchor mask), except
                # that a comment is always blanked under `strip_strings`. Default mode leaves both
                # alone, as it always has for substitution content.
                if c == "/" and i + 1 < n and text[i + 1] == "/":  # a line comment, as in code mode
                    while i < n and text[i] not in _JS_STRING_TERMINATORS:
                        if strip_strings:
                            blank(i)
                        i += 1
                    continue
                if c == "/" and i + 1 < n and text[i + 1] == "*":
                    close = -1 if block_close_absent else text.find("*/", i + 2)
                    if close != -1:
                        if strip_strings:
                            for j in range(i, close + 2):
                                blank(j)
                        i = close + 2
                        continue
                    # Unterminated: the code-mode cap again (declines to consume, shares the O(n)
                    # miss cache), and the `/` must not be retried as a regex opener either.
                    block_close_absent = True
                elif (c == "/" and i >= regex_fail_end and _js_regex_can_start(text, i, prev, False)
                      and _regex_body_may_blank(text, i) and not _after_non_null_assertion(text, i)):
                    # `paren_was_control` is False: a substitution is an expression, so no control
                    # head can precede the `/`, and `(a) / b` is division. `_regex_body_may_blank`
                    # refuses a JSX closing tag (`${ <b>x</b> }`): consuming `/b> }` as a regex would
                    # hide the substitution's own `}`, a desync this branch would have created. So
                    # does a non-null `x! / 2` (#1124 H2). Only a regex that CLOSES on its line is
                    # consumed: a misread division with no second `/` falls through as one char
                    # instead of hiding the line's braces and backticks. A scan that fails records
                    # where it bailed, and no `/` before that is retried, which keeps a run of
                    # unclosable starts (`/[/[/[...`) linear rather than one rescan each (#1124 H1).
                    body_end, j = _js_regex_end(text, i + 1, n)
                    if body_end == -1:
                        regex_fail_end = j
                    else:
                        while j < n and text[j].isalpha():  # flags
                            j += 1
                        if strip_strings and not keep_substitutions:  # substitution content, whole
                            for k in range(i, j):
                                blank(k)
                        else:
                            if strip_regex and not any(ch in _JS_LINE_TERMINATORS for ch in text[i + 1:body_end]):
                                for k in range(i + 1, body_end):  # the body only, as in code mode
                                    blank(k)
                            if strip_strings:  # the anchor mask blanks every `\`-escape pair (#749)
                                k = i + 1
                                while k < body_end:
                                    if text[k] == "\\":
                                        blank(k)
                                        blank(k + 1)
                                        k += 2
                                    else:
                                        k += 1
                        prev = ")"  # a regex is a value → a following `/` is division
                        i = j
                        continue
                if not c.isspace():
                    prev = c
                if c == "`":  # a NESTED template opens (delimiter kept) — this is the #541 fix
                    tpl.append(-1)
                    tpl_delims += 1
                    i += 1
                    continue
                if c in "'\"" and _closes_on_this_line(text, i, n):
                    tpl_quote = c
                elif c == "{":
                    tpl[-1] += 1
                elif c == "}":
                    tpl[-1] = -1 if tpl[-1] == 0 else tpl[-1] - 1  # -1 → back to template text
            # Template TEXT is always string content. Substitution content is too, unless the caller
            # asked for the anchor mask (#749), which keeps it as code. A substitution's closing `}`
            # has already reset the frame to -1 above, so it is blanked like the `${` that opened it.
            if strip_strings and (tpl[-1] < 0 or not keep_substitutions):
                blank(i)
            i += 1
            continue
        if quote:  # inside a plain ' or " string literal
            if c in _JS_STRING_TERMINATORS:
                # A RAW LineTerminator cannot appear inside a `'...'`/`"..."` literal (ES:
                # SingleStringCharacter excludes it; an escaped `\<LF>` LineContinuation never reaches
                # here — the escape branch below consumes it). So an "open" quote still open at one was
                # never an opener, and the honest recovery is to close it at the boundary. This is the
                # BLAST-RADIUS CAP for `_quote_is_jsx_apostrophe` mis-classification, mirroring the
                # unterminated-`/*` cap above: JSX prose whose word happens to be a keyword
                # (`<p>the default's value</p>`) otherwise leaves the scanner "inside a string" to EOF,
                # desyncing comment detection for the whole file and, under `strip_strings`, blanking
                # it. Capped here, any such error is confined to the one LOGICAL line that caused it.
                # The set is `_JS_STRING_TERMINATORS`, not a fourth literal spelling of "line ending":
                # a `'`/`"` cannot hold a raw LS/PS either, and the cap must agree with the opener
                # lookahead that admitted the quote (#440 gate F6). Template literals are exempt —
                # they legitimately span lines.
                quote = ""
                prev = ""  # a new line starts a statement → a following `/` may open a regex
                i += 1
                continue
            if c == "\\":  # escape — this char + the next are literal, can't close the string
                if strip_strings:
                    blank(i)
                    if i + 1 < n:
                        blank(i + 1)
                # `\<CR><LF>` is ONE LineTerminatorSequence, so the continuation covers all three
                # chars. Consuming only two would leave the scan on the LF, where the cap above would
                # close a literal the grammar says is still open — reopening F2 on CRLF sources.
                i += 3 if text[i + 1:i + 3] == "\r\n" else 2
                continue
            if c == quote:
                quote = ""  # closing delimiter (kept)
                prev = ")"  # a string is a value → a following `/` is division
            elif strip_strings:
                blank(i)
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "/":  # // line comment (always a comment)
            # A `//` comment ends at an ES LineTerminator and NOTHING else (ES2023 §12.4:
            # SingleLineComment runs to the next LineTerminator) — so it runs straight through a
            # VT/FF/FS/GS/RS/NEL. Stopping at `_JS_LINE_BOUNDARIES` was the mirror image of the
            # opener-lookahead defect: the comment ended early and the *commented-out* remainder was
            # handed to the guards as live code — a false positive measured at every commit in #440
            # (gate F5). A LineContinuation does NOT extend a comment, so this is the raw terminator
            # set, not `_logical_line_end`. Blanking still goes through `blank()`, which refuses to
            # overwrite a `splitlines()` boundary — the one line-NUMBERING question in this function.
            #
            # Blast radius of the widening, measured: bounded by the next ES LineTerminator, so in
            # any file that uses LF at all it is the remainder of the CURRENT physical line — which
            # genuinely IS commented out. Only a file with no LF anywhere (minified) lets a `//`
            # reach EOF, and that is NEW here — before this change the old stop set ended the comment
            # at the first VT/FF/FS/GS/RS/NEL, so in a control-char-separated file the remainder
            # survived (measured: `"// c\x0b" + "el.innerHTML = a;\x0b" * 40` → 40 dom-xss-sinks
            # findings at the parent, 0 here). The new behaviour is the grammatically correct one
            # (ES2023 §12.4: with no LineTerminator in the file the rest really is commented out) and
            # exposure is 0 of 40 000 real files, but it is a widening, not a no-op — an earlier draft
            # of this comment claimed it was equally true before, and that was wrong (#440 re-gate L1).
            #
            # Unlike the quote and `/*` caps above, no cap is warranted here: a `//` outside a
            # string/regex is not a heuristic guess, it is unambiguously a comment.
            while i < n and text[i] not in _JS_STRING_TERMINATORS:
                blank(i)
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":  # /* block comment */ (incl. JSDoc)
            # A failed `find("*/")` at position k guarantees failure for every k' > k, so cache the
            # first miss and short-circuit — else a pathological `"/*"*N` input re-scans the whole tail
            # at each `/*`, an O(n^2) DoS on the untrusted target-repo source we scan (PR #407 r4).
            close = -1 if block_close_absent else text.find("*/", i + 2)
            if close == -1:  # unterminated — do NOT blank to EOF (blast-radius cap, PR #407 r3):
                block_close_absent = True
                prev = "/"   # a mis-classified regex `/*...` must never blank the rest of the file
                i += 1
                continue
            for j in range(i, close + 2):
                blank(j)
            i = close + 2
            continue
        if c == "/" and _js_regex_can_start(text, i, prev, paren_was_control):  # regex — keep as code
            body_start = i + 1
            body_end, i = _js_regex_end(text, body_start, n)  # unterminated: bail, never cross a line
            if (
                strip_regex
                and body_end != -1
                and _regex_body_may_blank(text, body_start - 1)
                and not any(ch in _JS_LINE_TERMINATORS for ch in text[body_start:body_end])
            ):
                # Blank the BODY only, and only for a regex that really closed on its own line (an
                # escaped terminator is skipped by the `\` branch above, hence the explicit check).
                # A `/` the heuristic MISREADS as a regex start would otherwise blank everything up
                # to the next `/` on its line, deleting real code — see `_regex_body_may_blank`.
                for j in range(body_start, body_end):
                    blank(j)
            while i < n and text[i].isalpha():  # regex flags (g, i, m, ...)
                i += 1
            prev = ")"
            continue
        if c == "(":
            is_control = _word_before(text, i) in _CONTROL_KEYWORDS and not _member_access_before(text, i)
            paren_kinds.append(is_control)
        elif c == ")":
            paren_was_control = paren_kinds.pop() if paren_kinds else False
        if c == "`":       # a template literal opens — push a frame, in TEXT (delimiter kept)
            if not tpl:
                tpl_root = i   # outermost opener, for the unterminated cap at EOF
            tpl.append(-1)
            tpl_delims += 1
        elif (
            c in "'\""
            and not _quote_is_jsx_apostrophe(text, i, c)
            and last_quote[c] > i
        ):
            # Opening plain-string delimiter (kept) — unless it is JSX text punctuation; see
            # `_quote_is_jsx_apostrophe` for why the test is the WORD before, not one char.
            #
            # Backticks are NOT tested here: since #541 a template literal is a pushdown frame
            # (`tpl`), handled by the branch above, not a `quote` char. That split is what lets the
            # two rules coexist — the JSX/one-logical-line reasoning below is about `'`/`"` only,
            # and it would be wrong for a template, which may legitimately span lines.
            #
            # The `last_quote[c] > i` test applies the SAME rule the end-of-line cap above applies,
            # but PROSPECTIVELY. A `'...'`/`"..."` literal cannot contain a raw LineTerminator (ES:
            # SingleStringCharacter excludes it), so a quote with no unescaped partner before the end
            # of its LOGICAL line was never an opener. Deciding that BEFORE entering string mode is
            # what makes it a no-op; deciding it afterwards (the cap) still lets the mis-opened
            # "string" swallow the rest of its own line first — blanking a real sink under
            # `strip_strings`, and hiding a real `//` from comment detection without it. Both were
            # live CRITICAL/HIGH regressions (#440 gate, 2026-08-02). Template literals are exempt:
            # they legitimately span lines.
            #
            # "LOGICAL" is the whole correctness of this test, and two rounds got it wrong in opposite
            # directions. The window is `_logical_line_end`: it does NOT end at a VT/FF/NEL (not ES
            # LineTerminators — ending there refused a legal string and deleted a sink, #440 re-gate)
            # and it does NOT end at a LineTerminator carried by a LineContinuation (`"a\<LF>b"` IS a
            # valid one-literal, two-physical-line string — asserting otherwise was #440 gate F2). The
            # earlier claim here, "one that does not close on its line is not valid JS", was false for
            # exactly that construct. The cap above stays as the backstop for the template-literal
            # path and for a window that over-reaches a `//`-comment continuation.
            #
            # The partner is found on the FLAT line, so one inside a later template, string, comment
            # or regex counts too. That is an accepted residual, not an oversight: see the #558
            # paragraph of the docstring for why a frame-aware lookahead is circular.
            quote = c
        if not c.isspace():
            prev = c
        i += 1
    if tpl and tpl_root >= 0:
        # BLAST-RADIUS CAP. A template literal still open at EOF never closed, which means either the
        # source is invalid/truncated or WE mis-tracked it. Both readings say the same thing: nothing
        # from that opener on was reliably classified, so blanking it would be deleting source on a
        # guess. It is what makes a misparse structurally incapable of losing MORE than the pre-#541
        # scanner did: a desync that leaves frames still open (a stray quote pair in a substitution,
        # an escaped partner quote, a genuinely unterminated template) lands here. (An unbalanced `{`
        # in a regex or comment inside a substitution used to be the example; #543 lexes it now.)
        #
        # NOT the same mechanism as the unterminated-`/*` cap above, however much it rhymes. That one
        # declines to blank FORWARD and keeps lexing, so later comments are still stripped. This one
        # RETROACTIVELY UN-BLANKS an already-scanned region, so a commented-out example inside it
        # comes back and can fire a guard. Recovery and that FP are one mechanism, measured 1:1 over
        # a 40k-case differential, and cannot be separated without a real parser. Accepted knowingly:
        # a revived comment is visible, a deleted sink is not. Pinned by
        # `test_..._the_cap_revives_comments_after_a_desync_accepted_trade` so it stays a decision.
        #
        # Only observable under `strip_strings=True`: in default mode nothing inside a still-open
        # template was ever blanked, so this restore is a no-op there.
        out[tpl_root:] = list(text[tpl_root:])
    if strip_strings and tpl_delims % 2 == 1:
        # PARITY CAP (#910). An odd number of template delimiters means a stray backtick exists
        # somewhere — a missing closer on a CSS-in-JS template, a lone one in JSX prose — and a
        # single left-to-right pass cannot tell WHICH pairing it broke: from the stray on, every
        # "template" span the scanner blanked may be real code (the #910 repro is a broken
        # `styled.div` opener that paired with the next template's opener and swallowed a
        # `setTimeout` sink, which the EOF cap above never reaches because that pairing CLOSED).
        # So restore every closed outermost template span verbatim. Comments and plain strings the
        # scanner blanked in CODE mode are NOT in this set and stay blanked, which is what keeps an
        # earlier valid template's trailing `// example` silenced — the multi-opener FP a naive
        # revive-from-first-opener introduces (measured; pinned by
        # `test_..._parity_revive_keeps_code_mode_comments_blanked`). The still-open tail is the
        # EOF cap's job, and the two regions are disjoint by construction.
        #
        # Why parity and not a smarter pairing: one stray delimiter in a valid file ALWAYS leaves
        # the count odd, and an even count with blanked code is either two or more lexical errors
        # or valid JS whose string content looks like code — correctly blanked. Any rule that
        # guesses which backtick is the stray is a heuristic on a heuristic.
        #
        # Cost: a valid template BEFORE the stray has its content revived too — a visible FP for a
        # consumer matching string content, confined to files that are not valid JS. Pinned as a
        # decision by `test_..._parity_revive_restores_earlier_templates_accepted_trade`. On 65,480
        # real js/ts files (21,427 with a backtick) it changes 2, both vendor, and no consumer
        # finding changes on either. A revived template can also carry a brace into a consumer's
        # structural walk that trusts "string contents are blanked", exactly as the EOF cap above
        # can (#912 review). dom_xss_sinks no longer trusts it: its bracket matcher skips literals
        # itself (#909), pinned by `test_parity_cap_revive_inside_a_callback_body_no_longer_fires`.
        # Only observable under `strip_strings=True`: default mode never blanked template text.
        for span_start, span_end in tpl_closed_spans:
            out[span_start:span_end] = list(text[span_start:span_end])
    return "".join(out)


# The ONLY Go line terminator (Go spec, "Comments": a line comment "stops at the end of the
# line"; "line" there means U+000A only — Go defines no other newline character). Deliberately
# NOT `_JS_LINE_TERMINATORS`/`_JS_LINE_BOUNDARIES` (#555 review, Dean, Critical 2 + Major 3,
# verified both directions): those are JS-specific character classes. U+2028/U+2029 (JS line
# terminators) are ordinary characters inside a Go string, so using the JS terminator set to
# decide when an interpreted-string literal bails let a string containing one desync the scanner
# mid-string and delete real code after it (Critical 2). And `\v`/`\f`/`\x1c`-`\x1e` are not
# Go line-comment stop characters either, so using the broader JS boundary set as the `//`-loop's
# stop condition left live comment tail un-blanked whenever it contained one of those (Major 3,
# false-positive direction — commented-out text reads as live code). A `\n` embedded in a raw
# string (backtick) is not covered by this constant at all: `in_raw` never consults it, by design,
# since raw strings are explicitly allowed to span lines.
_GO_LINE_TERMINATOR = "\n"


# === helpers: Comment & string blanking =====================================================================
def strip_go_comments(text: str) -> str:
    """Blank Go `//` and `/* */` comments, preserving layout. String/rune/raw-string-aware, so a
    `//` or `/*` inside a literal is not mistaken for a comment.

    Go has three quoting forms, each with different rules — unlike a single plain-quote path,
    this needs all three tracked distinctly (Go spec, "String and character literals"):

    - `"..."`  interpreted string: backslash-escaped, must not span a physical line (real Go
      treats an unterminated one as a syntax error; this scanner bails at end-of-line the same
      way, re-entering code mode rather than reading the rest of the file as string content).
    - `'.'`    rune literal: identical escaping/single-line rule to a double-quoted string,
      just a different delimiter — a bare `'` inside code (there is no other use of it in Go)
      always opens one.
    - `` `...` `` raw string literal: NO escape processing at all — a backslash is a literal
      character, not an escape — and MAY span multiple physical lines. The only way to close
      it is a matching backtick; nothing inside it (including `//`/`/*`) is ever a comment.

    Deliberately simpler than `strip_js_comments`: Go has no regex-literal syntax, so there is
    no division-vs-regex ambiguity to resolve — every `/` outside a string/comment is always an
    operator. And Go's backtick strings do not support `${}`-style interpolation or nesting at
    all (unlike JS template literals), so there is no template-literal-desync class of bug here
    to guard against — a raw string is either open or closed, nothing more to track.

    Two things this does NOT reuse from `strip_js_comments`, both closed as review findings
    (#555, Dean) rather than assumed safe by analogy:

    - The `//`-stop and interpreted-string-bail conditions use `_GO_LINE_TERMINATOR` (`\n` only,
      per the Go spec), not `_JS_LINE_TERMINATORS`/`_JS_LINE_BOUNDARIES`. Those JS sets include
      characters (U+2028/U+2029, `\v`/`\f`/`\x1c`-`\x1e`) that are ordinary content in Go source —
      reusing them either deleted real code following a string that contained one (a scanner
      desync) or left a real comment's tail un-blanked (a false positive on commented-out text).
    - An unterminated raw string (a stray backtick with no closer anywhere in the tail) is capped
      the same way an unterminated `/* */` is: treated as ordinary code rather than swallowing
      everything after it as "still raw" to end of file, which would otherwise silence every real
      comment/string for the rest of the file, including a commented-out secret.

    Every blanked character becomes a single space and every `str.splitlines()` boundary
    character is left intact, so line numbers and column offsets computed from the result map
    back to the source unchanged."""
    out = list(text)
    i, n = 0, len(text)
    quote = ""  # active delimiter for a "..." or '.' literal, else ""
    in_raw = False  # inside a `...` raw string literal — nothing inside it is ever a comment
    block_close_absent = False  # once */ is absent from the tail it is absent for every later /*
    raw_close_absent = False  # once ` is absent from the tail it is absent for every later `

    def blank(j: int) -> None:  # replace with a space, but never a line-boundary char (keeps alignment)
        if text[j] not in _JS_LINE_BOUNDARIES:
            out[j] = " "

    while i < n:
        c = text[i]
        if in_raw:
            if c == "`":
                in_raw = False
            i += 1
            continue
        if quote:
            if c == "\\":  # escape — this char + the next are literal, can't close the string
                i += 2
                continue
            if c == quote:
                quote = ""
                i += 1
                continue
            if c == _GO_LINE_TERMINATOR:
                # Unterminated on this line — bail without consuming the terminator, so the next
                # pass re-reads it as ordinary code (real Go: this is a syntax error either way).
                quote = ""
                continue
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "/":  # // line comment
            # blank(), not a direct out[i] write: the loop must keep going past a character like
            # \r/\x0b/\x1c that is NOT a Go line terminator (Major 3) without overwriting it if it
            # IS one of Python's own splitlines() boundary characters — blank() already skips those,
            # same protection the /* */ span below relies on.
            while i < n and text[i] != _GO_LINE_TERMINATOR:
                blank(i)
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":  # /* block comment */
            # Cache a failed close-search: guarantees failure for every later /*, so a pathological
            # "/*"*N input can't re-scan the whole tail at each one (the same O(n) cap
            # strip_js_comments/blank_block_comments use, PR #407 r4).
            close = -1 if block_close_absent else text.find("*/", i + 2)
            if close == -1:  # unterminated — do NOT blank to EOF (blast-radius cap)
                block_close_absent = True
                i += 1
                continue
            for j in range(i, close + 2):
                blank(j)
            i = close + 2
            continue
        if c == "`":
            # Blast-radius cap (#555 review, Dean, Critical 1, verified), mirroring the /* */ one
            # above: an unterminated raw string has no correct answer (real Go: syntax error
            # either way), so — same choice as the /* */ cap — treat this backtick as ordinary
            # code rather than swallowing the rest of the file as "still raw." Without this, a
            # stray unterminated backtick anywhere in the file (a Go template fragment, generated
            # output, a testdata/ fixture of intentionally-broken source — all real on
            # corpus-scanned public repos) silences every real comment/string after it for the
            # rest of the file, including a commented-out secret that should have been blanked.
            close = -1 if raw_close_absent else text.find("`", i + 1)
            if close == -1:
                raw_close_absent = True
                i += 1
                continue
            in_raw = True
            i += 1
            continue
        if c in "\"'":
            quote = c
            i += 1
            continue
        i += 1
    return "".join(out)


_PHP_LINE_TERMINATOR = "\n"

# A heredoc/nowdoc opener: `<<<EOT`, `<<<"EOT"` (heredoc — interpolated), or `<<<'EOT'`
# (nowdoc — literal, no interpolation), always the last token on its line (PHP grammar).
_PHP_HEREDOC_OPEN = re.compile(
    r"<<<\s*(?:'(?P<nowdoc_tag>[A-Za-z_]\w*)'|\"?(?P<heredoc_tag>[A-Za-z_]\w*)\"?)\s*$"
)


def _blank_line_keep_terminator(line: str) -> str:
    r"""Replace every non-terminator character in `line` (a fragment from `splitlines(keepends=True)`,
    so its only line boundary is its trailing terminator) with a space, preserving that terminator.

    The terminator must be preserved across the SAME character set `str.splitlines()` breaks on
    (`_JS_LINE_BOUNDARIES`), not merely `\n`/`\r`/`\r\n`. Callers pair `text.splitlines()` with
    `strip_php_heredocs(text).splitlines()` by index under `zip(..., strict=True)` (see
    `php_code_injection`/`php_command_injection`). If a heredoc body happens to contain a
    `splitlines()` boundary char that is not `\n`/`\r` (`\v`, `\f`, `\x1c`-`\x1e`, `\x85`, LS/PS),
    blanking it to a space would drop a split point from the stripped copy, desync the two line
    lists, and raise `ValueError` — silently disabling the whole guard on that repo (#884 review,
    a regression this helper introduced). So preserve any trailing `_JS_LINE_BOUNDARIES` char, the
    same boundary-preserving rule `strip_php_comments::blank()` and the sibling strippers follow.
    The fragment's interior is boundary-free by construction (splitlines already broke there), so the
    body is safe to fill with plain spaces."""
    if line.endswith("\r\n"):
        return " " * (len(line) - 2) + "\r\n"
    if line and line[-1] in _JS_LINE_BOUNDARIES:
        return " " * (len(line) - 1) + line[-1]
    return " " * len(line)


def strip_php_heredocs(text: str) -> str:
    r"""Blank PHP heredoc/nowdoc BODIES (`<<<EOT ... EOT` / `<<<'EOT' ... EOT`) to spaces, preserving
    layout exactly like `strip_php_comments` — same invariant, so callers can compose the two (this
    one MUST run first; see below).

    #848 corpus scan / Dean's PR #884 review: `php_code_injection.py`/`php_command_injection.py`
    each carry their own cross-line `open_quote` state (needed for the matomo multi-line
    `.`-concatenated string case) ON TOP of `strip_php_comments`'s output. `strip_php_comments`
    itself is safe from cross-line heredoc desync — its own internal quote-tracking deliberately
    bails at every line terminator (see its docstring) rather than carrying state across lines. But
    a heredoc BODY is ordinary prose that can contain an odd number of `'`/`"` characters (an
    English contraction, an embedded SQL identifier) with no PHP significance at all, and neither
    `strip_php_comments` nor the guards' own carried `open_quote` knows that — so an odd-quote-count
    heredoc left the guards' tracker stuck "inside a string" and silently swallowed every later real
    sink in the file. Blanking heredoc bodies to spaces BEFORE anything else runs removes the
    apostrophes/quotes from existence, so no downstream quote-tracker — this module's or a guard's
    own — can ever be desynced by them.

    PHP 7.3+ flexible heredoc syntax allows the closing identifier to be indented; matched here as
    the first non-whitespace token on its line. Only the identifier ITSELF is blanked on the closing
    line — real PHP code after it (`EOT;`, `EOT . $more`) is preserved untouched, not blanked.

    Total: never raises. An unterminated heredoc (no matching closer before EOF) blanks to the end
    of the text — the safe direction for a guard: fails toward treating trailing content as inert
    rather than risking a false positive inside genuinely malformed, truncated source."""
    lines = text.splitlines(keepends=True)
    out: list[str] = []
    tag: str | None = None
    close_re: re.Pattern[str] | None = None
    for line in lines:
        if tag is not None:
            assert close_re is not None  # nosec B101 (type-narrowing only: always set together with tag)
            m = close_re.match(line)
            if m is None:
                out.append(_blank_line_keep_terminator(line))
                continue
            tag = None
            close_re = None
            out.append(" " * m.end() + line[m.end():])
            continue
        m2 = _PHP_HEREDOC_OPEN.search(line)
        if m2:
            tag = m2.group("nowdoc_tag") or m2.group("heredoc_tag")
            # Exactly one of the two named groups always participates when m2 matches at all —
            # the regex's top-level alternation requires it — but pyright can't derive that
            # guarantee from the group names alone, so it types .group() as `str | None`.
            assert tag is not None  # nosec B101 (type-narrowing only: one of the two capture groups matched)
            close_re = re.compile(r"[ \t]*" + re.escape(tag) + r"\b")
        out.append(line)
    return "".join(out)


def strip_php_comments(text: str) -> str:
    r"""Blank PHP `//`, `#`, and `/* */` comments, preserving layout. String-aware, so a comment
    delimiter inside a `'...'`/`"..."` literal is not mistaken for a comment.

    A simplified sibling of `strip_go_comments`/`strip_java_comments`: PHP has TWO line-comment
    forms (`//` and `#`, either one runs to end-of-line, per the PHP manual's "Comments" section) in
    addition to `/* */`. One exception is load-bearing: a PHP 8 attribute, `#[Attribute(...)]`, opens
    with `#[` — that is NOT a comment, and blanking it would delete real, security-relevant
    annotation syntax (e.g. framework route/permission attributes). `#` followed immediately by `[`
    is therefore left alone; every other `#` still opens a line comment.

    Deliberately NOT handled, documented residuals rather than silently assumed away (the same
    honesty standard `strip_go_comments`/`strip_ruby_comments` hold for their own gaps):

    - **Heredoc/nowdoc** (`<<<EOT ... EOT`) bodies are NOT specially recognized by THIS function —
      a `'`/`"` inside one is read as an ordinary quote. This scanner's own internal quote-tracking
      bails at every line terminator regardless (see below), so it cannot itself be desynced across
      lines by heredoc content. A caller that also carries cross-line quote state on TOP of this
      function's output (as `php_code_injection.py`/`php_command_injection.py` do) DOES need heredoc
      awareness — call `strip_php_heredocs(text)` FIRST and pass its result in here, not raw `text`.
    - **PHP/HTML mode-switching** (`<?php ... ?>` boundaries) is not tracked — the whole file is
      scanned uniformly. Literal HTML text outside PHP tags is not real PHP code, so it cannot itself
      contain a genuine PHP comment, but a stray `//`/`#`/`'`/`"` in HTML/markup content could in
      principle desync this scanner's state across the boundary. Not observed in the call-site shapes
      these guards target (functions/superglobals/literals), so not specially handled.

    Every blanked character becomes a single space and every `str.splitlines()` boundary character is
    left intact, so line numbers and column offsets computed from the result map back to the source
    unchanged."""
    out = list(text)
    i, n = 0, len(text)
    quote = ""  # active delimiter for a "..." or '...' literal, else ""
    block_close_absent = False  # once */ is absent from the tail it is absent for every later /*

    def blank(j: int) -> None:  # replace with a space, but never a line-boundary char (keeps alignment)
        if text[j] not in _JS_LINE_BOUNDARIES:
            out[j] = " "

    while i < n:
        c = text[i]
        if quote:
            if c == "\\":  # escape — this char + the next are literal, can't close the string
                i += 2
                continue
            if c == quote:
                quote = ""
                i += 1
                continue
            if c == _PHP_LINE_TERMINATOR and quote == "'":
                # A single-quoted PHP string CAN legally span lines (unlike Go/Java's "..."), so
                # only bail the '...' form here would be wrong — but a genuinely unterminated one
                # (no closing quote anywhere in the file) must not swallow the rest of the file as
                # "still a string" either. Simpler, safer choice matching the sibling strippers: bail
                # at the first line terminator regardless of quote kind — real PHP allows a literal
                # newline inside '...'/"..." (both are multi-line-legal, unlike Go's interpreted
                # string), so this IS a conservative narrowing (a multi-line single/double-quoted
                # string's later lines are scanned as ordinary code) rather than a correctness gap in
                # the common single-line call-site shapes these guards target.
                quote = ""
                continue
            if c == _PHP_LINE_TERMINATOR and quote == '"':
                quote = ""
                continue
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "/":  # // line comment
            while i < n and text[i] != _PHP_LINE_TERMINATOR:
                blank(i)
                i += 1
            continue
        if c == "#" and not (i + 1 < n and text[i + 1] == "["):  # # line comment (not #[Attribute])
            while i < n and text[i] != _PHP_LINE_TERMINATOR:
                blank(i)
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":  # /* block comment */
            close = -1 if block_close_absent else text.find("*/", i + 2)
            if close == -1:  # unterminated — do NOT blank to EOF (blast-radius cap)
                block_close_absent = True
                i += 1
                continue
            for j in range(i, close + 2):
                blank(j)
            i = close + 2
            continue
        if c in "\"'":
            quote = c
            i += 1
            continue
        i += 1
    return "".join(out)


_JAVA_LINE_TERMINATOR = "\n"


def strip_java_comments(text: str) -> str:
    """Blank Java `//` and `/* */` comments, preserving layout. String/char-literal-aware, so a
    `//` or `/*` inside a literal is not mistaken for a comment.

    A simplified sibling of `strip_go_comments` (same shape, same blast-radius caps), with the
    one piece Go needed and Java does not: Go's backtick RAW string literal, which spans lines
    with no escape processing. Java has no equivalent third quoting form for this scanner to
    special-case — just a plain double-quoted string (interpreted, backslash-escaped, may not
    span a physical line) and a single-quoted char literal (identical escaping/single-line rule,
    different delimiter — a bare single quote inside code always opens one, there being no other
    use of it in Java). Java 17+ triple-double-quoted TEXT BLOCKS are a real third form this
    deliberately does not special-case: the triple-quote is read as an empty double-quoted string
    immediately followed by a new one opening — a rare, documented residual (text blocks are
    uncommon in the security-sensitive code this scans), not a silent one.

    Every blanked character becomes a single space and every `str.splitlines()` boundary
    character is left intact, so line numbers and column offsets computed from the result map
    back to the source unchanged."""
    out = list(text)
    i, n = 0, len(text)
    quote = ""  # active delimiter for a "..." or '.' literal, else ""
    block_close_absent = False  # once */ is absent from the tail it is absent for every later /*

    def blank(j: int) -> None:  # replace with a space, but never a line-boundary char (keeps alignment)
        if text[j] not in _JS_LINE_BOUNDARIES:
            out[j] = " "

    while i < n:
        c = text[i]
        if quote:
            if c == "\\":  # escape — this char + the next are literal, can't close the string
                i += 2
                continue
            if c == quote:
                quote = ""
                i += 1
                continue
            if c == _JAVA_LINE_TERMINATOR:
                # Unterminated on this line — bail without consuming the terminator, so the next
                # pass re-reads it as ordinary code (real Java: this is a syntax error either way).
                quote = ""
                continue
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "/":  # // line comment
            while i < n and text[i] != _JAVA_LINE_TERMINATOR:
                blank(i)
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":  # /* block comment (incl. /** javadoc) */
            close = -1 if block_close_absent else text.find("*/", i + 2)
            if close == -1:  # unterminated — do NOT blank to EOF (blast-radius cap)
                block_close_absent = True
                i += 1
                continue
            for j in range(i, close + 2):
                blank(j)
            i = close + 2
            continue
        if c in "\"'":
            quote = c
            i += 1
            continue
        i += 1
    return "".join(out)


def strip_ruby_comments(text: str) -> str:
    """Blank Ruby `#` line comments and `=begin`/`=end` block comments, preserving layout.
    String-aware for `'...'`/`"..."` so a `#` inside a literal (including a `"...#{x}..."`
    interpolation — the scanner just stays "inside the string" until the closing quote, same
    effect as not special-casing interpolation at all) is not mistaken for a comment start.

    Deliberately does NOT track `%w[]`/`%i[]`/`%q()`/`%Q()` percent-literals or heredocs
    (`<<~TEXT`) — Ruby's most exotic string forms, rare in the security-relevant call sites
    these guards target (`system`, `Marshal.load`, `Digest::MD5`, etc. are not typically
    written inside a percent-literal array or a heredoc body). Same "good enough for the
    shapes this guard targets" tolerance `strip_go_comments`/`strip_js_comments` already
    document for their own out-of-scope forms, not an oversight.

    `=begin`/`=end` must each start a physical line (the Ruby spec's own rule) — checked via
    the preceding character being a newline or start-of-text, not via a MULTILINE regex
    anchor, so this stays a single linear char-by-char pass matching the sibling strippers'
    shape.

    Every blanked character becomes a single space; every `str.splitlines()` boundary
    character is left intact, so line numbers computed from the result map back to the
    source unchanged."""
    out = list(text)
    i, n = 0, len(text)
    quote = ""  # active delimiter for a "..." or '...' literal, else ""
    at_line_start = True

    def blank(idx: int) -> None:  # never a splitlines()-boundary char (keeps line-count aligned,
        if text[idx] not in _JS_LINE_BOUNDARIES:  # same helper strip_js_comments/strip_go_comments use
            out[idx] = " "

    while i < n:
        c = text[i]
        if quote:
            if c == "\\":
                blank(i)
                i += 1
                if i < n:
                    blank(i)
                    i += 1
                continue
            if c == quote:
                quote = ""
            i += 1
            at_line_start = False
            continue
        if c == "\n":
            i += 1
            at_line_start = True
            continue
        if at_line_start and text.startswith("=begin", i):
            close = text.find("\n=end", i)
            end = close + 5 if close != -1 else n  # unterminated: blank to EOF (rare, honest)
            for j in range(i, min(end, n)):
                blank(j)
            i = min(end, n)
            at_line_start = False
            continue
        if c == "#":
            j = i
            while j < n and text[j] != "\n":
                blank(j)
                j += 1
            i = j
            continue
        if c in "\"'":
            quote = c
            i += 1
            at_line_start = False
            continue
        if not c.isspace():
            at_line_start = False
        i += 1
    return "".join(out)
class _CommentDialect(NamedTuple):
    """The lexical rules `blank_block_comments` needs, as ONE preset per language.

    Deliberately one preset, never independent keyword arguments: the rules are not free to
    mix. Handing a caller `quotes="'"` without also flipping `backslash_escapes` and
    `strings_span_lines` produces a scanner that is HCL-correct in one place and SQL-wrong in the
    next two — a half-configured dialect (#441 re-review). A preset cannot be half-applied.
    """

    quotes: str
    line_comments: tuple[str, ...]
    backslash_escapes: bool  # `\"` escapes (HCL/Go); standard-conforming SQL doubles instead (`''`)
    strings_span_lines: bool  # a Postgres literal may contain a newline; an HCL quoted one may not
    # Postgres `E'…'` honors `\` escapes even where `backslash_escapes` is off for the plain literal
    # — the two are not the same switch, and conflating them hid findings (issue #500).
    escape_string_prefix: bool
    # The dialect's opaque RAW body, whose contents the language lexes as data with no quote
    # character marking it (issue #602): HCL heredocs, Postgres dollar-quoted literals. The scan
    # SKIPS such a body — a `/*` inside one is never an opener.
    heredocs: bool  # HCL `<<TAG` / `<<-TAG` through the first line whose stripped content is TAG
    dollar_quotes: bool  # Postgres `$$…$$` / `$tag$…$tag$`, tag an unquoted identifier


_COMMENT_DIALECTS: dict[str, _CommentDialect] = {
    "hcl": _CommentDialect(
        '"',
        ("#", "//"),
        backslash_escapes=True,
        strings_span_lines=False,
        escape_string_prefix=False,
        heredocs=True,
        dollar_quotes=False,
    ),
    "sql": _CommentDialect(
        "'",
        ("--",),
        backslash_escapes=False,
        strings_span_lines=True,
        escape_string_prefix=True,
        heredocs=False,
        dollar_quotes=True,
    ),
}

# The heredoc intro, matched only in code context (never inside a string/comment/other body, so a
# phantom is already unlikely — HCL has no `<<` operator). Forward-shape only, deliberately broader
# than `_TF_HEREDOC_OPEN`'s `=`-anchored form: heredocs legitimately open after `(`, `,` or `[`
# (`base64encode(<<EOF`), which the brace-walkers may ignore but a blanking pass must not. The tag
# is identifier-shaped (`[^\W\d]\w*`, no digit lead), which is what kills the `1 <<2` phantom the
# `=`-anchor exists to kill. A phantom that slips through anyway only SKIPS text (FP-side; nothing
# can be hidden), see `blank_block_comments`.
_HCL_HEREDOC_INTRO = re.compile(r"<<-?(?P<tag>[^\W\d]\w*)[ \t]*\r?\n")
_HCL_HEREDOC_TAG = re.compile(r"[^\W\d]\w*")  # the intro's tag shape, alone — for indexing lines

# A dollar-quote delimiter at one position: `$$` or `$tag$`, tag an unquoted identifier (PG rules:
# no digit lead, no `$` inside — so `$1` positional params never match).
_SQL_DOLLAR_DELIM = re.compile(r"\$(?:[^\W\d]\w*)?\$")
# Every delimiter START in a text, overlapping (`$$$$$` has starts at 0,1,2,3). At any position the
# greedy capture is unique and equals `text[p:p+len]` for exactly the delimiters occurring at p, so
# "first indexed start >= from" is equivalent to `text.find(delim, from)` — proven by the adjacent
# equivalence test.
_SQL_DOLLAR_DELIM_ANYWHERE = re.compile(r"(?=(\$(?:[^\W\d]\w*)?\$))")


def _index_heredoc_terminators(text: str) -> dict[str, list[tuple[int, int]]]:
    """One pass over ``text``'s lines: identifier-shaped line -> [(line_start, resume_index)].

    `resume_index` is the first index PAST the line's newline (or EOF). Only lines whose stripped
    content could be a heredoc tag are indexed, so the dict stays small on real files. Built
    lazily by `blank_block_comments` on the first heredoc intro it meets: answering each intro's
    terminator search from the index instead of rescanning the tail keeps a pathological file of
    N unterminated intros O(n) instead of O(n^2).
    """
    idx: dict[str, list[tuple[int, int]]] = {}
    pos, n = 0, len(text)
    while pos < n:
        eol = text.find("\n", pos)
        end = n if eol == -1 else eol
        stripped = text[pos:end].strip()
        if stripped and _HCL_HEREDOC_TAG.fullmatch(stripped) is not None:
            idx.setdefault(stripped, []).append((pos, end + 1 if eol != -1 else n))
        if eol == -1:
            break
        pos = eol + 1
    return idx


def _index_dollar_delims(text: str) -> dict[str, list[int]]:
    """One pass: dollar-quote delimiter -> its (overlapping) start offsets, ascending.

    The lazily-built partner of `_index_heredoc_terminators` for `dialect="sql"`: closing a
    dollar-quoted body is "first start of the SAME delimiter at/after the body start", answered by
    bisect instead of a per-opener `str.find` whose failures are O(n) each.
    """
    idx: dict[str, list[int]] = {}
    for m in _SQL_DOLLAR_DELIM_ANYWHERE.finditer(text):
        idx.setdefault(m.group(1), []).append(m.start())
    return idx


def blank_block_comments(text: str, *, dialect: Literal["hcl", "sql"] = "hcl") -> str:
    r"""Blank `/* … */` block comments; string-aware at the OPENING marker, opaque inside.

    **The invariant.** A block comment runs from the first `/*` in *code* context — not inside a
    string literal, not inside a line comment, not inside an opaque raw body (an HCL heredoc or a
    SQL dollar-quoted literal — see below) — to the first `*/` after it, whatever that `*/` sits
    in. The two ends are asymmetric on purpose, because quote state is live *outside* a comment and
    dead *inside* one: C99 §6.4.9 ("the contents of such a comment are examined only … to find the
    characters `*/` that terminate it"), and HCL/Go, JS and SQL all lex it the same way.

    So the closing search is a plain `find("*/")`, and that is not an oversight (#441 re-review):

    * `/* use a " to quote */ publicly_accessible = true` is valid, ordinary HCL, and the comment
      ends at that `*/`. Making the *closing* search string-aware would let the lone `"` swallow it,
      run the comment on to some later `*/`, and blank the live `publicly_accessible = true` below —
      a silent HIGH miss. A false NEGATIVE, traded for at best a cosmetic gain.
    * The converse input, a `*/` inside a quoted run inside a comment
      (`/* old HCL used a "*/" delimiter */`), does end the comment early — but such a file is a
      *syntax error* in every one of these languages (the quote is unterminated), so there is no
      correct answer to give it, only the reference lexer's answer. Verified: on this input `gcc -E`
      emits byte-for-byte what this function does.

    A naive `re.sub(r"/\*.*?\*/", …, re.S)` over the whole file is NOT safe, which is what the
    opening-side awareness buys: a `/*` inside an ordinary string (`"configs/*catalog"`) or inside a
    `#`/`//` line comment would be read as an opener and everything up to the next `*/` *anywhere
    later in the file* blanked — silently deleting real resource blocks and the findings in them
    (#441 review; the same shape as the PR #407 JS blast-radius bug). So:

    * a `/*` inside a string literal or a line comment is data, never an opener; and
    * an **unterminated** `/*` (no `*/` before EOF) is NOT blanked — the blast-radius cap, so a
      stray opener can never blank to end-of-file. The first missing `*/` is cached, so the scan
      stays O(n) on a pathological `"/*" * N` input.

    Every blanked character becomes a single space and every `str.splitlines()` boundary character
    is left intact, so line numbers *and* column offsets computed from the result map back to the
    source unchanged. Line comments are only *skipped over* (so their `/*` is inert), never blanked
    — blanking them is the caller's own business.

    **Dialects.** `hcl` (default) and `sql` (`'` strings, `--` line comments) — for the SQL guards
    carrying the same unguarded regex (issue #500). The SQL preset is not just a different quote
    character; both other string rules flip with it:

    * *No backslash escape.* With `standard_conforming_strings` (Postgres default since 9.1) a
      backslash is an ordinary character and a quote is escaped by **doubling** it. Doubling needs
      no special case — `'it''s'` scans as two adjacent literals covering exactly the same span —
      but treating `\` as an escape would eat the closing quote of `'C:\'`.
    * *Strings may span lines.* An HCL quoted template may not contain a newline, so bailing at one
      is right there and caps the damage from an odd `"`. A Postgres literal may, and bailing early
      re-enters "code" mode *inside* the literal, where a `/*` in its later lines (`'see docs/*.md\n
      for details'`) is misread as an opener and blanks live SQL below it — a false negative. The
      SQL scan therefore crosses newlines, with the same cap in the other direction: a quote with no
      partner before EOF is rewound and treated as data, never skipped to EOF. That costs no extra
      passes (a failed scan proves no quote follows, so at most one can fail).

    **Opaque raw bodies (issue #602).** Each dialect has one construct whose contents the language
    lexes as raw data with no quote character marking it, so the string-awareness above never sees
    it: the HCL heredoc (`<<TAG` / `<<-TAG` through the first line whose *stripped* content is
    exactly `TAG` — the same terminator rule `_tf_line_scan` uses) and the Postgres dollar-quoted
    literal (`$$…$$` / `$tag$…$tag$`, tag an unquoted identifier). The scan SKIPS such a body —
    `i` moves past it, nothing is blanked — so a `/*` inside one (`cp -r /opt/app/*` in a
    `user_data` script, `docs/*.md` in dollar-quoted prose) is data, never an opener. Skipping is
    the fail-safe direction: a phantom body-match leaves text LIVE (at worst a false positive for
    the caller to report on), it can never blank a finding away. Both carry the no-partner cap
    every other span here has: an intro with no terminator line, or a `$tag$` with no closing
    partner before EOF, is data, never a licence to skip the tail. Terminators are answered from a
    one-pass lazily-built index (`_index_heredoc_terminators` / `_index_dollar_delims`), so a
    pathological file full of distinct unterminated tags stays O(n) — the by-hand `find()` per
    opener it replaces was quadratic there.

    Residual limits. The earlier version of this list claimed they were "all false-POSITIVE-side …
    none can hide a finding". That was measured and is FALSE for two of the three, so they are split
    by direction here — a reader who trusts a blanket safety claim has no reason to construct the
    case that breaks it, which is exactly how issue #500 stayed open (its `E'` item was filed under
    this sentence while silently hiding findings).

    * FALSE-POSITIVE side, i.e. it leaves text live: nested `/* /* */ */` (a Postgres extension)
      closes at the first `*/`, leaving the outer comment's tail live. A phantom opaque-body match
      (above) errs the same direction — text stays live, nothing is hidden.
    * CLOSED as of issue #602, both halves of the opaque-raw-body gap. (a) A `/*` inside an HCL
      `<<EOF` heredoc body was treated as an opener, so with any later `*/` in the file the text
      between them was blanked — measured through `rds-publicly-accessible` (the only
      `dialect="hcl"` consumer): a heredoc carrying one shell glob (`cp -r /opt/app/*`) plus an
      ordinary trailing block comment took a live `publicly_accessible = true` from 1 finding to 0.
      (b) The same shape for SQL: a dollar-quoted body is not a string context, so the `/*` of
      `$$See docs/*.md$$` opened — measured through `rls-permissive-policy`, where it hid a live
      `CREATE POLICY … USING (true)`. Both bodies are now skipped as opaque raw text (above) —
      for a body WITH a partner. An UNTERMINATED body earns no opaqueness: the no-partner cap is
      a classification rule, not a completeness guarantee, so the body is scanned as code exactly
      as pre-#602, and a bare `/*` inside it can still pair with a genuine later `*/` and hide a
      finding — FALSE-NEGATIVE side, on input that is a *syntax error* in the target language
      (an unclosed heredoc / unclosed `$tag$`; #825 review). Pinned by the caps tests in both
      dialects. The sibling `strip_sql_comments` closed the same shape in #442 with a different
      rule, a BOUNDED scope rather than an opaque body, because its callers need the comments
      inside a function or `DO` body stripped; its statement-local mechanism is untouched by #602.
    * CLOSED as of issue #500: a Postgres `E'…'` escape-string backslash is now honored
      (`escape_string_prefix` / `opens_sql_escape_string`). It was the third item on this list and
      was FALSE-NEGATIVE side ON VALID SQL: it blanked a live `CREATE POLICY` and silenced two RLS
      guards. For malformed SQL the sibling `strip_sql_comments` carries a further caveat, stated in
      its own docstring because the mechanism (statement-local comment-immunity) is exclusive to it;
      this function has no statement-boundary logic at all. A 300,000-trial differential fuzz of
      `blank_block_comments(dialect="sql")` across the fix found divergences ONLY in the safe
      direction here (#603 fresh-eyes review).
    """
    d = _COMMENT_DIALECTS[dialect]
    out = list(text)
    i, n = 0, len(text)
    block_close_absent = False  # once `*/` is absent from the tail it is absent for every later `/*`
    heredoc_terminators: dict[str, list[tuple[int, int]]] | None = None  # built on first `<<TAG`
    dollar_delims: dict[str, list[int]] | None = None  # built on first `$tag$`

    def blank(j: int) -> None:  # replace with a space, but never a line-boundary char (keeps alignment)
        if text[j] not in _JS_LINE_BOUNDARIES:
            out[j] = " "

    while i < n:
        c = text[i]
        if c in d.quotes:  # a string literal — its contents are data, never a comment opener
            # A Postgres `E'…'` literal escapes with a backslash even though the plain `'…'` of the
            # same dialect does not, so escape handling is per-LITERAL, not per-dialect. Without
            # this the scan mis-closes at `E'it\'s`, resumes code mode inside the literal, and reads
            # the `/*` in its own text as a real opener — blanking live SQL below (issue #500).
            escapes = d.backslash_escapes or (d.escape_string_prefix and opens_sql_escape_string(text, i))
            j, closed = i + 1, False
            while j < n:
                ch = text[j]
                if escapes and ch == "\\":
                    if not d.strings_span_lines and j + 1 < n and text[j + 1] in _JS_LINE_TERMINATORS:
                        break  # `\` + newline still may not cross a line
                    j += 2  # escape — this char + the next are literal, can't close the string
                    continue
                if ch in _JS_LINE_TERMINATORS and not d.strings_span_lines:
                    break  # unterminated on this line — bail, never cross a line
                j += 1
                if ch == c:
                    closed = True
                    break
            if not closed and d.strings_span_lines:
                i += 1  # no partner before EOF — the quote is data, never skip the whole tail
                continue
            i = j
            continue
        if any(text.startswith(marker, i) for marker in d.line_comments):
            while i < n and text[i] not in _JS_LINE_BOUNDARIES:
                i += 1
            continue
        if text.startswith("/*", i):
            close = -1 if block_close_absent else text.find("*/", i + 2)
            if close == -1:  # unterminated — do NOT blank to EOF (blast-radius cap)
                block_close_absent = True
                i += 1
                continue
            for j in range(i, close + 2):
                blank(j)
            i = close + 2
            continue
        if d.heredocs and c == "<":  # HCL heredoc body — raw data, skipped opaque (issue #602)
            m = _HCL_HEREDOC_INTRO.match(text, i)
            if m is not None:
                if heredoc_terminators is None:  # first intro in this text: index the lines once
                    heredoc_terminators = _index_heredoc_terminators(text)
                lines = heredoc_terminators.get(m.group("tag"), [])
                k = bisect_left(lines, (m.end(), -1))  # first candidate line at/after the body
                if k < len(lines):
                    i = lines[k][1]  # resume just past the terminator line; body left LIVE
                    continue
            i += 1  # not an intro, or no terminator before EOF: `<` is data, never skip the tail
            continue
        if d.dollar_quotes and c == "$":  # dollar-quoted body — same treatment (issue #602)
            m = _SQL_DOLLAR_DELIM.match(text, i)
            if m is not None:
                if dollar_delims is None:  # first delimiter in this text: index the starts once
                    dollar_delims = _index_dollar_delims(text)
                starts = dollar_delims.get(m.group(0), [])
                k = bisect_left(starts, m.end())
                if k < len(starts):
                    i = starts[k] + len(m.group(0))  # resume past the close; body left LIVE
                    continue
            i += 1  # no closing partner before EOF: `$` is data, never skip the tail
            continue
        i += 1
    return "".join(out)


def strip_hash_comments(text: str) -> str:
    """Strip `#` line-comments (YAML / shell / .conf / requirements), one line at a time.

    A `#` is a comment only at line-start or after whitespace, so a `#` INSIDE a token/value
    (`REDIS_PASSWORD: "a#b"`, `--requirepass "p#ss"`) is preserved — unlike a naive
    `line.split("#", 1)[0]`, which clips it (the false-positive class the #358/#360 reviews hit).
    Quote-aware (issue #418): a space-before-`#` *inside* a single-/double-quoted span
    (`msg: "Info #1: {{ secret }}"`) is string content, not a comment, so the tail survives — the
    earlier "~90% / does NOT handle quotes" caveat clipped it, silently dropping whatever a guard
    needed to match after it (a false negative — the worst class for a scanner). We MASK quoted spans
    with equal-length filler to locate the first REAL `#`, then truncate the ORIGINAL line there
    (mirrors `strip_python_line_comment`). Caveat: an *unpaired* quote can pair with a quote inside a
    real comment and mask its `#`, letting that comment survive (`msg: don't fail # it's fine`) — the
    inverse FP-direction miss, strictly safer than the FN it replaces and rarer; an *unterminated*
    quote (`msg: "unclosed # rest`) never pairs, so it strips exactly as before.
    Linear in the input on every shape, with no line-length cap (#508): a 100 KB line is stripped
    exactly as a short one is, so padding a line can neither keep a comment alive nor buy a DoS.
    Not for `//` (JS) / `--` (SQL — see `strip_sql_comments`) / `<!-- -->` (HTML), and not a
    whole-line comment *detector* (see the guards' `^\\s*(?:#|//)` patterns — a different job).
    """
    out = []
    for line in text.splitlines():
        cut = _hash_comment_start(line)
        out.append(line if cut == -1 else line[:cut])
    return "\n".join(out)


def _hash_comment_start(line: str) -> int:
    """Index at which the `#` line-comment of ONE physical line begins (the whitespace before the
    `#` included, as `_HASH_COMMENT` matches it), or -1 when the line carries none. The single
    per-line decision behind `strip_hash_comments` (which truncates there) and the `hash`/`yaml`
    dialects of `comment_view` (which keep from there), so the two can never disagree about what a
    comment is.

    Every line gets the same answer whatever its length. There used to be a 1 KB cap past which
    this answered -1 unmasked (#493), and no fail direction for that was safe: whether a surviving
    comment hides a finding or invents one depends on the calling guard's polarity and on whether
    its regex is anchored, so the cap silenced a Critical in one guard and raised a spurious High
    in another (#508). `_mask_quoted_spans` is linear, so nothing needs a cap."""
    if "#" not in line:  # the mask only ever writes `x`, so a line with no `#` has no comment
        return -1
    m = _HASH_COMMENT.search(_mask_quoted_spans(line))
    return -1 if m is None else m.start()


_TRIPLE_QUOTE = re.compile(r'(?s)""".*?"""|\'\'\'.*?\'\'\'')
_STRING_PREFIX = "rbfuRBFU"


def _strip_python_strings_regex(text: str) -> str:
    """Regex fallback for `strip_python_strings` — used only when `ast.parse` fails.

    Blanks triple-quoted strings by pattern. NOT lexical-context-aware: a triple-quote inside a `#`
    comment or a single-line string can mis-pair with a later triple-quote and blank the code
    between (issue #366) — which is exactly why the primary path uses `ast`. Retained only so the
    helper stays total on input that doesn't parse (a broken file, already un-analyzable)."""
    def _blank(m: re.Match[str]) -> str:
        return "\n" * m.group().count("\n")
    return _TRIPLE_QUOTE.sub(_blank, text)


# --- run-scoped memo for per-file derived state (issue #544) ---------------------------------
# The audit fans every registered guard over every file, and each guard re-derives what it needs
# from the file text. `strip_python_strings` is therefore called once per (guard, file) pair rather
# than once per file: measured at 13,867 calls over 307 distinct texts (45.2x) on agentsec's own
# package, and 69% of the audit's cumulative time. The tree WALK already solved exactly this
# guard-count multiplication for itself (`walk.walk_run`, "so the tree is walked ~twice instead of
# once per registered guard"); this closes the same gap for file-derived state. Measured 2.21x on
# the self-audit with findings byte-identical.
#
# Safe to share one object between guards ONLY because the value is a `str`, which is immutable — a
# guard cannot mutate another guard's copy. `safe_ast_parse` is now memoised as well (#597, opened by
# this scope through `astutil.parse_cache_run()`), and its trees are mutable, so that memo rests on a
# contract instead: no caller may write to a parsed tree. The mutation audit behind it is recorded at
# `astutil.parse_cache_run` and pinned by `tests/test_run_memo.py`, which audits the canary inside one
# run and compares every cached tree, attribute names included, with a fresh parse.
#
# Active ONLY inside a `derived_state_run()` scope, so nothing is ever served stale between audits
# and a direct call (a unit test, a single guard) always recomputes. Re-entrant: nested scopes share
# one cache, matching `walk_run`.
_derived_depth = 0
_strip_python_strings_cache: dict[str, str] = {}
# The same treatment for the JS/TS side. `strip_js_comments` is the Python function's opposite
# number on a JS/TS target — most of the JS/TS guards call it, so it too runs once per (guard, file)
# pair — and it is the more expensive derivation of the two per character.
#
# No count here on purpose. This comment said "21 guard modules" and the real figure was 15 (Marconi,
# #551 review; independently recounted twice). `doc_counts.py --check-narrative` enforces "prose never
# carries live counts", but its scan surface is README/CONTRIBUTING/docs/wiki `.md` only — a hard count
# in a CODE comment is outside every gate we have, so it drifts silently. `git grep -l
# 'strip_js_comments(' agentsec/guards/` is the answer that cannot go stale.
#
# The purity precondition was checked the same way, not assumed: the transitive call graph is four
# helpers (`_word_before`, `_member_access_before`, `_js_regex_can_start`, `_closes_on_this_line`),
# none declares `global`/`nonlocal`, none reads a mutable module-level object (there are none in
# this module), and none does IO or anything time/locale dependent. The value is a `str`, immutable,
# so one object is safe to share between guards — the identical argument that licenses the table
# above. (A parse tree is not immutable, which is why the parse memo needs its no-write contract.)
#
# Keyed on `(text, strip_strings, strip_regex, keep_substitutions)`, unlike the Python table's bare
# `text`: this function has several output variants per input (default, string-blanked, the #909
# regex-body blanking and the #749 anchor mask) and real audits call it at more than one setting, so a
# key missing any flag would hand one variant to a caller that asked for another. That is a correctness
# bug rather than a cache miss, which is why every flag is in the key and not merely extra tables.
_strip_js_comments_cache: dict[tuple[str, bool, bool, bool], str] = {}
# The third table: `comment_view` (issue #424, the pragma-anchoring rider). Once the guards route
# their suppress-pragma check through it, it too runs once per (guard, file) pair, and its SQL and
# Python dialects are the two most expensive derivations in this module. Keyed on
# `(text, dialect)` for the same reason the JS table carries its flag: one text has one view PER
# DIALECT, and a `.py` and a `.yml` never share a text in practice, but a text-only key would still
# be a correctness bug rather than a cache miss the day two do. Purity holds the same way: every
# dialect is a pure function of its inputs built from the blankers above (see `comment_view`).
_comment_view_cache: dict[tuple[str, str], str] = {}
# The router-resolver views (#538): `router_resolver_view` and `router_code_view` are one derivation
# at two settings, and the router-auth guards call them once per (guard, file) pair, the cross-file
# resolver twice. Keyed on `(text, keep_strings)` for the same reason the JS table carries its flag:
# two output variants per input, so a text-only key would be a correctness bug. Pure for the same
# reason as the tables above: built only from `strip_python_strings` and the token stream.
_router_view_cache: dict[tuple[str, bool], str] = {}
# `_conditional_lines` (#597): the router-auth resolvers call it once per (guard, file) pair, ~8x per
# file on agentsec's own package, and each call is a full parse plus `ast.walk`. Pure: a function of
# `text` only (`filename` names warnings), so it is keyed on the text like the tables above.
_conditional_lines_cache: dict[str, frozenset[int]] = {}
# Bound each table so a pathological target (thousands of large files) cannot balloon memory: past
# the cap we simply stop adding entries and recompute, which is slower but never wrong.
#
# NOTE the ceiling this constant now describes: it is per-table, so the run-scoped memo holds up to
# this many entries TIMES the number of tables above in total. Measured peak on the flagship
# `9_Agent_SaaS` target (the JS-heaviest real target we audit): 103 JS/TS entries, two orders of
# magnitude below the cap, so the multiplier is theoretical there rather than observed. Issue #552
# tracks the separate point that this bound counts ENTRIES and not BYTES; adding a table does
# not change that argument, but it does multiply the number the argument is about, so it is stated
# here rather than left to be rediscovered.
_MAX_DERIVED_ENTRIES = 4096


# === helpers: Per-run memoisation ===========================================================================
@contextmanager
def derived_state_run() -> Iterator[None]:
    """Memoise per-file derived state for the duration of one audit (issue #544).

    Mirrors `walk.walk_run()`: the caches live only inside this scope, are cleared on entry and on
    exit of the outermost scope, and are re-entrant so nested scopes share the same tables. It also
    opens `astutil.parse_cache_run()`, the parse memo, which is keyed by text like these tables and so
    is safe wherever they are."""
    global _derived_depth
    if _derived_depth == 0:
        _strip_python_strings_cache.clear()
        _strip_js_comments_cache.clear()
        _comment_view_cache.clear()
        _router_view_cache.clear()
        _conditional_lines_cache.clear()
    _derived_depth += 1
    try:
        with parse_cache_run():
            yield
    finally:
        _derived_depth -= 1
        if _derived_depth == 0:
            _strip_python_strings_cache.clear()
            _strip_js_comments_cache.clear()
            _comment_view_cache.clear()
            _router_view_cache.clear()
            _conditional_lines_cache.clear()


# === helpers: Comment & string blanking =====================================================================
def strip_python_strings(text: str, *, filename: str | Path = "<unknown>") -> str:
    """Blank triple-quoted string content — memoised while a `derived_state_run()` scope is active.

    The real work is `_strip_python_strings_uncached`; see its docstring for the contract. Outside a
    scope this is a straight pass-through, so behaviour is identical either way.

    `filename` is diagnostic only (see `safe_ast_parse`) and is deliberately NOT part of the cache
    key: the key stays `text`, because two files with identical text derive the identical result and
    keying on the path would only halve the hit rate for a parameter that cannot change the value.
    The visible consequence is that within one `derived_state_run()` scope only the FIRST call for a
    given text reaches the parser, so only that call's `filename` can ever be stamped on a warning —
    a later file with byte-identical text emits nothing at all rather than emitting the wrong path."""
    if _derived_depth == 0 or _MAX_DERIVED_ENTRIES <= 0:
        return _strip_python_strings_uncached(text, filename=filename)
    hit = _strip_python_strings_cache.get(text)
    if hit is not None:
        return hit
    out = _strip_python_strings_uncached(text, filename=filename)
    if len(_strip_python_strings_cache) < _MAX_DERIVED_ENTRIES:
        _strip_python_strings_cache[text] = out
    return out


def strip_js_comments(
    text: str, *, strip_strings: bool = False, strip_regex: bool = False, keep_substitutions: bool = False
) -> str:
    """Blank JS/TS comments — memoised while a `derived_state_run()` scope is active (issue #544).

    The real work is `_strip_js_comments_uncached`; see its docstring for the contract (including
    the `strip_regex` regex-body blanking, #909, and the `keep_substitutions` anchor mask, #749), and
    `_strip_js_comments_cache` above for the purity argument and why every flag is in the key.
    Outside a scope this is a straight pass-through, so behaviour is identical either way."""
    if _derived_depth == 0 or _MAX_DERIVED_ENTRIES <= 0:
        return _strip_js_comments_uncached(
            text, strip_strings=strip_strings, strip_regex=strip_regex, keep_substitutions=keep_substitutions
        )
    key = (text, strip_strings, strip_regex, keep_substitutions)
    hit = _strip_js_comments_cache.get(key)
    if hit is not None:
        return hit
    out = _strip_js_comments_uncached(
        text, strip_strings=strip_strings, strip_regex=strip_regex, keep_substitutions=keep_substitutions
    )
    if len(_strip_js_comments_cache) < _MAX_DERIVED_ENTRIES:
        _strip_js_comments_cache[key] = out
    return out


def js_anchor_is_code(line: str, mask_line: str, pos: int) -> bool:
    """True if the JS anchor at `line[pos]` is live code, not string content.

    `line` is a line of the default `strip_js_comments(text)` view, the one a guard matches on;
    `mask_line` is the same line of `strip_js_comments(text, strip_strings=True,
    keep_substitutions=True)`. The two views share one layout, so an anchor is code exactly when the
    mask left it alone. A guard keeps matching (and reading arguments) on `line`, and drops a match
    whose anchor, typically a call's `(`, is quoted: `"pool.query(...)"` in a docs string is not a
    call, while `` `${pool.query(sql)}` `` is (#749).

    Fails OPEN. A whitespace anchor carries no evidence (a blank in the mask may be either), and a
    position outside the line or a pair of lines of different lengths means the views are not
    aligned; each of these answers True, so misuse can only keep a finding, never silently drop one."""
    if not 0 <= pos < len(line) or len(mask_line) != len(line) or line[pos].isspace():
        return True
    return mask_line[pos] == line[pos]


def js_code_matches(
    pattern: re.Pattern[str],
    code: str,
    mask: str,
    *,
    anchor: Callable[[re.Match[str]], int],
    literal_ok: bool = False,
) -> Iterator[re.Match[str]]:
    """Yield every `pattern` match in `code` whose anchor character is live JS code (#1055).

    `code` is the default `strip_js_comments(text)` view, or one line or slice of it, and `mask` is
    the same span of the anchor mask (`strip_js_comments(text, strip_strings=True,
    keep_substitutions=True)`). The views share one layout, so a whole file works exactly like one
    line. `anchor(m)` picks the character that decides, usually a call's `(` (`m.end() - 1`) or an
    identifier's first character (`m.start()`). It must never be a character the pattern matches
    inside a literal on purpose (`'*'`, a header name, a module specifier), and never a `${`/`}`
    delimiter, which the mask blanks.

    Every match is visited, so a quoted copy earlier in the text cannot hide a real one after it.
    That is the trap of filtering only `.search`'s first hit, which turns a quoted first hit into a
    new false negative. A dropped match does not consume its span either: the scan resumes one
    character past its start, so a long-span pattern (`[\\s\\S]{0,280}`) whose quoted copy runs over a
    real match below it cannot swallow that match the way plain `finditer` would. A yielded match
    consumes its span, as `finditer` does. The `js_anchor_is_code` fail-open contract carries over:
    views that do not line up keep every match.

    `literal_ok=True` also yields a match whose anchor sits in a one-identifier string literal
    (`js_in_identifier_literal`), for a marker that lives in a string by nature: a header name or an
    env or config key. Prose still drops, and the same resume-after-drop scan applies."""
    pos = 0
    while (m := pattern.search(code, pos)) is not None:
        a = anchor(m)
        if js_anchor_is_code(code, mask, a) or (literal_ok and js_in_identifier_literal(code, mask, a)):
            yield m
            pos = max(m.end(), m.start() + 1)
        else:
            pos = m.start() + 1


_JS_IDENTIFIER_LITERAL = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*")


def js_in_identifier_literal(code: str, mask: str, pos: int) -> bool:
    """True if `code[pos]` sits in a real JS string literal whose content is one identifier-shaped token.

    The companion to `js_anchor_is_code` for a credit whose marker lives in a string by nature: a
    header name (`'mcp-method'`), an env or config key (`process.env['MAX_TOOLS']`, `{'limit': 50}`).
    Such a literal credits, while the same word inside prose (`'no limit configured'`) does not
    (#1055, the JS/TS twin of `mcp_toolgate_asymmetry`'s Python H-7b rule). `code` and `mask` are the
    same span of the default view and of the anchor mask. The mask blanks a literal's content and keeps
    its delimiters, so the literal runs out from `pos` over blanked characters to a quote the mask kept,
    and its content, give or take surrounding blanks, must be one `[A-Za-z_][A-Za-z0-9_-]*` token. A
    template literal split by a `${...}` substitution stops at the substitution's code, so it never
    qualifies.

    Fails CLOSED, unlike `js_anchor_is_code`: it widens a credit, so views that do not line up, or a
    position outside them, answer False and leave the decision to the anchor test."""
    if not 0 <= pos < len(code) or len(mask) != len(code):
        return False
    i = pos - 1
    while i >= 0 and mask[i] == " ":
        i -= 1
    j = pos
    while j < len(code) and mask[j] == " ":
        j += 1
    return (
        i >= 0
        and j < len(code)
        and code[i] in "'\"`"
        and code[j] == code[i]
        and mask[i] == code[i]
        and mask[j] == code[j]
        and _JS_IDENTIFIER_LITERAL.fullmatch(code[i + 1 : j].strip()) is not None
    )


# === helpers: Suppress-pragma anchoring =====================================================================
# The comment grammar `comment_view` reads a file under. Every dialect is the INVERSE of a blanker
# this module already has (the `strip_*`/`blank_*` helpers above) or, for Python, the `tokenize`
# pass `open_redirect.py` pioneered — deliberately no new lexer, so a pragma is recognised in
# exactly the comments the detection side already knows how to skip (issue #424).
CommentDialect = Literal["python", "js", "sql", "yaml", "hash", "hcl", "go", "php", "java", "ruby"]


def _comment_only(text: str, blanked: str) -> str:
    """Invert a same-length comment-BLANKED copy of `text` into its comment-only view: every
    character the blanker turned into a space comes back from `text`, everything it left alone
    becomes a space, and a line-boundary character is kept in both (`_JS_LINE_BOUNDARIES`, so
    `splitlines()` counts agree). Exact for every blanker here, because each one replaces a comment
    character with a space and nothing else — a space INSIDE a comment reads equal on both sides
    and lands as a space either way."""
    return "".join(
        c if (c != b or c in _JS_LINE_BOUNDARIES) else " " for c, b in zip(text, blanked, strict=True)
    )


def _python_comment_view(text: str) -> str:
    """The `tokenize`-anchored view: only a COMMENT token survives, so a `#` inside a string, a
    docstring or an f-string is content. Rows from the tokenizer index `text.split("\\n")` — it
    counts only `\\n` as a row break (a lone `\\r` or a form feed ends the comment but not the row),
    so absolute offsets come straight from a line-start table and nothing is normalised.

    Best-effort on a file that does not tokenize (an unterminated string or bracket, a bad dedent):
    every token yielded BEFORE the error is honoured and the tail from the last trusted token is
    kept RAW. A real comment pragma in that tail is still seen (CLAUDE.md rule 4), and a string
    quoting one still suppresses there exactly as it does today — the #370 degrade shape, never
    worse than the raw match this replaces."""
    view = [c if c in _JS_LINE_BOUNDARIES else " " for c in text]
    starts = [0]
    for line in text.split("\n")[:-1]:
        starts.append(starts[-1] + len(line) + 1)
    trusted = 0  # absolute offset up to which the token stream classified the text
    try:
        for tok in tokenize.generate_tokens(io.StringIO(text).readline):
            if tok.type == tokenize.ENDMARKER:
                break
            (row, col), (erow, ecol) = tok.start, tok.end
            if tok.type == tokenize.COMMENT and row - 1 < len(starts):
                off = starts[row - 1] + col
                view[off : off + len(tok.string)] = tok.string  # a COMMENT token never spans a row
            if erow - 1 < len(starts):
                trusted = max(trusted, starts[erow - 1] + ecol)
    except Exception:  # stay total — the guards must never crash on a file that does not parse
        view[trusted:] = text[trusted:]
    return "".join(view)


def _sql_view_literals(probe: str) -> str:
    """`probe` with the CONTENT of every literal space-filled, delimiters kept, same length: the
    take-back half of `_sql_comment_view`. Lexed the way `strip_sql_comments` lexes, so the two
    agree on what is a literal and what is a comment:

      * a `'…'` literal (doubled `''` inside, `E'…'` backslash escapes) is taken back, and so is a
        `"…"` identifier that closes on its own line (#1040, below);
      * a quote with no partner is a stray character, not a literal that runs to EOF;
      * a terminated `$$…$$` / `$tag$…$tag$` body is CODE, a bounded scope (#442, #1040 T2): its
        comments stay, a literal inside it is taken back, and a quote pairs only inside it. A tag
        inside a body is plain text, and a tag with no partner before EOF is plain text too.

    The body rule is the #1040 T2 decision. Postgres re-lexes a function or `DO` body as SQL or
    PL/pgSQL, and every SQL guard's detection (on `strip_sql_comments`) already reads a `CREATE
    POLICY` inside `DO $$ … $$`, so a real `-- security: allow-…` comment there must suppress.
    Taking the whole body back, as `blank_sql_literals` does, voided that opt-out in every anchored
    SQL guard (rule 4). The cost, in the safe direction: a pragma phrase in a dollar-quoted STRING
    that is not a body (`COMMENT ON t IS $$…$$`) reads as a comment too, as it did on raw text.

    On `probe` every comment character is already the sentinel, so a quote or `$` inside a real
    comment cannot open anything here.

    The one-line bound on `"…"` is the one `find_statement_end` and `blank_policy_names` apply, for
    the same reason. A stray `"` pairs with the next `"` however far ahead, and taking that whole
    span back would hide every real comment between the two, a pragma included (rule 4). The cost
    is a pragma phrase inside a MULTI-line identifier that also holds a `;`, which still reads as a
    comment. A `'…'` span is taken back whatever its length, as it always was.

    Linear, by the same means as `strip_sql_comments`: a failed close search is latched per quote
    kind and per scope, and a body's close comes from the one-pass `_index_dollar_delims`."""
    out = list(probe)
    n = len(probe)
    i, hi, tag = 0, n, ""
    absent = {"'": False, '"': False}  # no close ahead in this scope: every later one is stray too
    outer_absent = absent
    delims: dict[str, list[int]] | None = None
    while True:
        while i < hi:
            c = probe[i]
            if c == "'" or c == '"':
                escaped = c == "'" and opens_sql_escape_string(probe, i)
                if escaped:
                    close = _find_sql_close(probe, i + 1, c, hi, backslash_escapes=True)
                else:
                    close = -1 if absent[c] else _find_sql_close(probe, i + 1, c, hi)
                if close == -1:
                    if not escaped:
                        absent[c] = True
                    i += 1
                    continue
                span = probe[i + 1 : close]
                if c == "'" or not any(ch in _JS_LINE_BOUNDARIES for ch in span):
                    out[i + 1 : close] = " " * len(span)
                i = close + 1
                continue
            if c == "$" and hi == n:
                glued = i > 0 and (probe[i - 1].isalnum() or probe[i - 1] == "_")
                m = None if glued else _SQL_DOLLAR_DELIM.match(probe, i)
                if m is not None:
                    if delims is None:
                        delims = _index_dollar_delims(probe)
                    starts = delims.get(m.group(0), [])
                    k = bisect_left(starts, m.end())
                    if k < len(starts):
                        tag, hi, i = m.group(0), starts[k], m.end()
                        outer_absent, absent = absent, {"'": False, '"': False}
                        continue
            i += 1
        if hi == n:
            return "".join(out)
        i, hi, absent = hi + len(tag), n, outer_absent


def _sql_comment_view(sql: str) -> str:
    """`strip_sql_comments(blank=True)` decides what a comment is; `_sql_view_literals` then takes
    back the part of that answer which lies INSIDE a literal: a span whose comment-immunity
    `strip_sql_comments` revoked (#435: it crosses a `;` or a statement start) has its interior
    comment-stripped there, and that text is literal content, not a comment. Composed in that order
    on purpose: the comment characters are first replaced by a sentinel no SQL delimiter rule reads
    (not a quote, not `$`, not an identifier character), so an apostrophe in a real comment
    (`-- don't`) can never open a phantom literal that swallows the next real pragma.

    A dollar-quoted body is code here, as it is to `strip_sql_comments` (#442) and to Postgres:
    a real comment inside `DO $$ … $$` or a function body is in the view (#1040 T2). See
    `_sql_view_literals` for the rule and its cost."""
    stripped = strip_sql_comments(sql, blank=True)
    probe = "".join(c if c == s else "\x01" for c, s in zip(sql, stripped, strict=True))
    literals = _sql_view_literals(probe)
    return "".join(
        c if (c in _JS_LINE_BOUNDARIES or (c != s and p == m)) else " "
        for c, s, p, m in zip(sql, stripped, probe, literals, strict=True)
    )


def _hcl_comment_view(text: str) -> str:
    """`blank_block_comments(dialect="hcl")` for `/* … */` (string- and heredoc-aware), then the
    `#`/`//` line comments via `_blank_line_comment` on each block-blanked line — on the BLANKED
    line, so a `"` inside a block comment cannot leave the line scanner "in a string" past a real
    comment. An attribute heredoc body (`x = <<EOF` … `EOF`, the `blank_policy_noise` rule) is
    skipped whole: its `#` lines are script text, never HCL comments."""
    blocks = blank_block_comments(text, dialect="hcl")
    view = list(_comment_only(text, blocks))
    lines = blocks.split("\n")
    off = 0
    i, n = 0, len(lines)
    while i < n:
        line = lines[i]
        code = _blank_line_comment(line)
        if code != line:
            cut = next(k for k in range(len(line)) if code[k] != line[k])
            view[off + cut : off + len(line)] = text[off + cut : off + len(line)]
        off += len(line) + 1
        i += 1
        m = _TF_HEREDOC_OPEN.search(code)
        if m is None:
            continue
        tag = m.group("tag")
        while i < n and lines[i].strip() != tag:  # body lines: nothing in them is a comment
            off += len(lines[i]) + 1
            i += 1
    return "".join(view)


_YAML_BLOCK_INDICATOR = re.compile(r"[|>](?:[1-9][+-]?|[+-][1-9]?)?")


def _yaml_block_scalar_parent(code: str) -> int:
    """The column a YAML block scalar opened on this comment-free line is nested under (`key: |`
    -> the key's column, `- >-` -> the dash's), or -1 when the line opens none. Quoted spans are
    masked first so a `"|"` value is not an indicator. Indentation-based, like the YAML spec's own
    rule: every following line indented deeper than that column (or blank) is scalar CONTENT."""
    s = _mask_quoted_spans(code).rstrip()
    if not s or s[-1] not in "|>+-123456789":
        return -1
    col = len(s) - len(s.lstrip(" "))
    body = s[col:]
    dash = -1
    while body.startswith("- "):  # sequence entries, possibly nested: `- - key: |`
        dash = col
        rest = body[1:]
        col += len(body) - len(rest.lstrip(" "))
        body = rest.lstrip(" ")
    if ": " in body:
        value, parent = body.split(": ", 1)[1].strip(), col
    elif body.endswith(":"):
        return -1
    else:
        value, parent = body, (dash if dash >= 0 else col)
    return parent if _YAML_BLOCK_INDICATOR.fullmatch(value) else -1


def _hash_comment_view(text: str, *, yaml: bool) -> str:
    """Per physical line, keep from `_hash_comment_start` on (the decision `strip_hash_comments`
    truncates at). With `yaml=True` the lines of a block scalar (`key: |`, `- >`) are string
    content and carry no comment. A line of any length is classified, so a real opt-out comment
    on a long line is honoured and pragma text inside its quoted values is not, as on a short one
    (the 1 KB cap that kept such a line RAW is gone, #508)."""
    out: list[str] = []
    parent = -1  # column the open block scalar is nested under; -1 outside one
    for line in text.splitlines(keepends=True):
        body = line.rstrip(_JS_LINE_BOUNDARIES)
        ending = line[len(body) :]
        if parent >= 0:
            if not body.strip() or len(body) - len(body.lstrip(" ")) > parent:
                out.append(" " * len(body) + ending)
                continue
            parent = -1
        cut = _hash_comment_start(body)
        out.append(" " * len(body) + ending if cut == -1 else " " * cut + body[cut:] + ending)
        if yaml:
            parent = _yaml_block_scalar_parent(body if cut == -1 else body[:cut])
    return "".join(out)


def _php_comment_view(text: str) -> str:
    heredocs = strip_php_heredocs(text)  # bodies gone first, as `strip_php_comments` requires
    return _comment_only(heredocs, strip_php_comments(heredocs))


_COMMENT_VIEWS: dict[str, Callable[[str], str]] = {
    "python": _python_comment_view,
    "js": lambda text: _comment_only(text, strip_js_comments(text)),
    "sql": _sql_comment_view,
    "yaml": lambda text: _hash_comment_view(text, yaml=True),
    "hash": lambda text: _hash_comment_view(text, yaml=False),
    "hcl": _hcl_comment_view,
    "go": lambda text: _comment_only(text, strip_go_comments(text)),
    "php": _php_comment_view,
    "java": lambda text: _comment_only(text, strip_java_comments(text)),
    "ruby": lambda text: _comment_only(text, strip_ruby_comments(text)),
}


def comment_view(text: str, dialect: CommentDialect) -> str:
    """A same-length copy of `text` in which ONLY its comments survive: every comment character
    and every line-boundary character is kept at its own offset, everything else — code AND string
    content — is a space. The view a suppress pragma is matched against (issue #424): a pragma
    counts only when it is written as a comment, the form every design doc, skill and remediation
    string shows, and never when a docstring, string literal, YAML scalar or SQL literal merely
    quotes it. Memoised while a `derived_state_run()` scope is active (issue #544).

    Same-length is the load-bearing property. A guard that slices `text` per line, window, block
    or statement slices the view at identical offsets, so a pragma's REACH — line, window, whole
    file, whole repo — is exactly what it was on the raw text: this changes what counts as a
    pragma, never how far one reaches (#622 established that scope is deliberate UX). Prefer
    `pragma_present` / `pragma_line_set` over matching the view by hand.

    The one thing the space-fill changes for a pattern: blanked code is whitespace, so a
    `^\\s*#…` pattern under `re.MULTILINE` matches a TRAILING comment on a code line where the raw
    line would not have. A guard that means "a whole-line comment only" keeps that test on its raw
    line; the view answers "is this text a comment", nothing more.

    Dialects, each the inverse of a blanker this module already had (see the `_COMMENT_VIEWS`
    table) — so every known limit of that blanker is inherited, and the residuals below are stated
    by DIRECTION, because the two directions are not equally safe here. "More view" means string
    content that can still suppress (a false negative, exactly today's behaviour on that text);
    "less view" means a real comment the check cannot see, which voids a user's own opt-out
    (CLAUDE.md rule 4) and is the direction each dialect is built to avoid:

    * `python` — `tokenize`, best-effort: past a tokenize error the tail is kept RAW (more view).
    * `js` — `strip_js_comments`; an unterminated `/*` is not a comment there, so not here either.
    * `sql` — `strip_sql_comments(blank=True)` minus the inside of `'…'` and `E'…'` literals and
      one-line `"…"` identifiers. A terminated `$$…$$` / `$tag$…$tag$` body is code (#1040 T2): its
      comments are in the view, its literals are not. More view: a pragma phrase in a dollar-quoted
      STRING that is not a body (`COMMENT ON t IS $$-- …$$`); the data rows of a terminated
      `COPY … FROM stdin;` section are blanked by the stripper and read as comment here. Less view,
      on MALFORMED SQL only: a comment
      inside the span two stray quotes confer statement-local immunity on (the stripper's
      documented residual) is not seen.
    * `yaml` — `#` per line via the quote-aware locator `strip_hash_comments` uses, and a block
      scalar (`key: |`, `- >-`) is content by indentation. A pragma inside a `run: |` script is
      therefore NOT a YAML comment: whether a guard wants the script's shell comments honoured too
      is a per-guard adoption choice (`hash` honours them). More view: a `#` on the continuation
      line of a multi-line quoted scalar.
    * `hash` — the same per-line `#` rule with no scalar tracking, for shell / `.env` / TOML /
      requirements / Dockerfile. More view: shell heredocs and TOML triple-quoted strings.
    * `hcl` — `blank_block_comments` plus string-aware `#`/`//` per line; attribute heredoc bodies
      are skipped. More view: a heredoc that is not an attribute value (`jsonencode(<<EOF`).
    * `go`, `java`, `ruby`, `php` — the respective `strip_*_comments`; PHP heredoc bodies are
      blanked first. More view: a Java text block, a Ruby `%w[]`/heredoc, PHP's HTML mode.

    Never raises on any input; a dialect name outside `CommentDialect` is a programming error and
    does raise (a crash is safer than a check that silently matched nothing)."""
    if _derived_depth == 0 or _MAX_DERIVED_ENTRIES <= 0:
        return _COMMENT_VIEWS[dialect](text)
    key = (text, dialect)
    hit = _comment_view_cache.get(key)
    if hit is not None:
        return hit
    out = _COMMENT_VIEWS[dialect](text)
    if len(_comment_view_cache) < _MAX_DERIVED_ENTRIES:
        _comment_view_cache[key] = out
    return out


def pragma_present(pragma: str | re.Pattern[str], text: str, *, dialect: CommentDialect | None) -> bool:
    """True if the suppress pragma is written as a COMMENT somewhere in `text` — the one check
    every guard's `if _PRAGMA in text` / `_PRAGMA.search(text)` should route through (issue #424).
    A `str` pragma is a substring test and a compiled one a `search`, both over
    `comment_view(text, dialect)`, so a guard keeps its own `_PRAGMA` constant and its own scope
    (pass it the same slice — line, block, whole file — it matched on before) and only the VIEW
    changes: a docstring quoting `# security: allow-<id>` no longer silences the file.

    `dialect=None` — what `comment_dialect_for` answers for a grammar with no comment dialect here
    (`.json`, `.md`, …) — matches the RAW text, exactly today's behaviour for that file: more view,
    never less, so a guard iterating several file types through one check site adopts with
    `pragma_present(_PRAGMA, text, dialect=comment_dialect_for(f))` and loses nothing."""
    view = text if dialect is None else comment_view(text, dialect)
    return pragma in view if isinstance(pragma, str) else pragma.search(view) is not None


def pragma_line_set(
    pragma: str | re.Pattern[str], text: str, *, dialect: CommentDialect | None
) -> frozenset[int]:
    """The 1-based `str.splitlines()` line numbers of `text` whose COMMENT carries the pragma —
    for the per-line callers that keep a `pragma_lines` set and test the finding's own line (or a
    window around it) against it, the `open_redirect.py` shape. Same view as `pragma_present`
    (and the same raw-text answer for `dialect=None`), so the two never disagree about what a
    pragma is; a compiled pragma is searched per line."""
    view = text if dialect is None else comment_view(text, dialect)
    if isinstance(pragma, str):
        return frozenset(i for i, line in enumerate(view.splitlines(), 1) if pragma in line)
    return frozenset(i for i, line in enumerate(view.splitlines(), 1) if pragma.search(line))


_DIALECT_BY_SUFFIX: dict[str, CommentDialect] = {
    ".py": "python", ".pyi": "python",
    ".js": "js", ".jsx": "js", ".ts": "js", ".tsx": "js", ".mjs": "js", ".cjs": "js",
    ".sql": "sql",
    ".yml": "yaml", ".yaml": "yaml",
    ".tf": "hcl", ".hcl": "hcl", ".tfvars": "hcl",
    ".go": "go", ".php": "php", ".java": "java", ".kt": "java", ".rb": "ruby",
    ".toml": "hash", ".ini": "hash", ".cfg": "hash", ".conf": "hash", ".env": "hash", ".sh": "hash",
    ".bash": "hash", ".zsh": "hash", ".dockerfile": "hash", ".properties": "hash",
}
# Dotfiles have NO suffix to `pathlib` (`Path(".npmrc").suffix == ""`), so the `#`-comment ones are
# matched by name below, never through the table above.
_HASH_DOTFILES = frozenset({".npmrc", ".yarnrc", ".pypirc", ".gitconfig", ".bashrc", ".zshrc", ".profile"})


def comment_dialect_for(path: str | Path) -> CommentDialect | None:
    """The `comment_view` dialect a file's grammar is read under, from its NAME — for the guards
    that iterate several file types through one pragma check site. `.py` → `python`; the JS/TS
    family → `js`; `.sql`; `.yml`/`.yaml` → `yaml` (block scalars are content); `.tf`/`.hcl` →
    `hcl`; `.go`/`.php`/`.java`/`.rb`; and the `#`-comment configs — `.toml`, `.ini`, `.cfg`,
    `.conf`, `.env*`, shell, `Dockerfile*`/`*.dockerfile`, `requirements*.txt`, `.npmrc` — →
    `hash`. None for a grammar with no comment dialect here (`.json`, `.md`, a generic `.txt`, a
    key or certificate), which `pragma_present` reads as "match the raw text": today's behaviour
    for that file, never a dropped comment (`.ini`'s `;` comment form is not read — a `;` pragma
    there is unseen, the one less-view case, and no guard documents that form).

    A real extension wins, and the name-based cases (`Dockerfile*`, `.env*`, the dotfiles) answer
    only for a name the table cannot: `dockerfile_generator.py` is Python and `.environment.py` is
    Python, not `hash`: under `hash` a `#` line inside their docstrings would read as a comment,
    the very false negative the view exists to close (#990 review, H1). `.kt` reads as `java`,
    whose comment, string and char-literal grammar it shares. `.rs` is deliberately None: a Rust
    lifetime (`'a`) would open a phantom char literal in that lexer and hide a same-line `//`
    pragma (the less-view direction), so Rust stays a raw match until it has a dialect."""
    name = Path(path).name.lower()
    suffix = Path(path).suffix.lower()
    known = _DIALECT_BY_SUFFIX.get(suffix)
    if known is not None:
        return known
    if name.startswith((".env", "dockerfile")) or name in ("containerfile",) or name in _HASH_DOTFILES:
        return "hash"
    if suffix == ".txt" and name.startswith(("requirements", "constraints")):
        return "hash"
    return None


def _char_col(line: str, byte_col: int) -> int:
    """Convert an `ast` node's `col_offset`/`end_col_offset` (a UTF-8 BYTE offset — CPython has
    reported these as byte offsets, not code-point indices, since 3.8) to the character index
    `line` needs for `str` slicing, which is code-point-indexed. Using the byte number directly
    overshoots on any multi-byte character earlier on the line, so every offset downstream of it
    (the string's own open/close quotes, an f-string interpolation span) drifts by however many
    extra bytes those characters cost — silently blanking real code past the drift point, or
    leaving string content unblanked (#568, Dean). A valid parse's offsets always land on a
    character boundary, so decoding the byte-sliced prefix and measuring its length recovers the
    exact code-point index; `errors="ignore"` is a defensive no-op on well-formed input, matching
    this module's other byte-boundary-safe reads rather than trusting that invariant blindly."""
    return len(line.encode("utf-8")[:byte_col].decode("utf-8", errors="ignore"))


class _PyLiteralSpan(NamedTuple):
    """One physical string literal from the token stream — see `_python_string_literal_spans`."""

    start: tuple[int, int]          # (row, char-col) of the literal's first prefix/quote character
    end: tuple[int, int]            # (row, char-col) one past its closing quote
    content_start: tuple[int, int]  # first character of the literal's CONTENT
    content_end: tuple[int, int]    # one past the last content character (start of the closer)
    triple: bool


def _python_string_literal_spans(text: str) -> list[_PyLiteralSpan] | None:
    """Every top-level string literal in `text` as exact (row, char-col) spans, or None.

    `ast` folds implicitly concatenated adjacent literals into ONE Constant/JoinedStr node, so
    node positions cannot say where one physical literal ends and the next begins — the token
    stream can (#776). Literals nested inside an f-string interpolation are skipped: they sit
    inside a `FormattedValue` keep-span, which the blanker preserves wholesale. Columns are
    code-point indices (tokenize slices `str` lines), NOT the byte offsets `ast` reports — the
    two must never be mixed without `_char_col` (#568). Returns None when tokenization fails,
    in which case the caller keeps the single-literal-per-node behavior."""
    try:
        tokens = list(tokenize.generate_tokens(io.StringIO(text).readline))
    except Exception:
        return None                              # stay total — the guards must never crash
    spans: list[_PyLiteralSpan] = []
    depth = 0                                    # f-string nesting depth (3.12 tokenizer)
    opener: tokenize.TokenInfo | None = None     # the depth-0 FSTRING_START
    for tok in tokens:
        if tok.type == tokenize.FSTRING_START:
            if depth == 0:
                opener = tok
            depth += 1
        elif tok.type == tokenize.FSTRING_END:
            depth -= 1
            if depth < 0:
                return None                      # malformed stream — refuse to guess
            if depth == 0 and opener is not None:
                head = opener.string.lstrip(_STRING_PREFIX)
                spans.append(_PyLiteralSpan(
                    start=opener.start, end=tok.end,
                    # FSTRING_START spans exactly prefix+quotes and FSTRING_END exactly the
                    # closer, so the content sits between the two tokens.
                    content_start=opener.end, content_end=tok.start,
                    triple=head[:3] in ('"""', "'''"),
                ))
                opener = None
        elif tok.type == tokenize.STRING and depth == 0:
            head = tok.string.lstrip(_STRING_PREFIX)
            triple = head[:3] in ('"""', "'''")
            quote = 3 if triple else 1
            prefix = len(tok.string) - len(head)
            spans.append(_PyLiteralSpan(
                start=tok.start, end=tok.end,
                content_start=(tok.start[0], tok.start[1] + prefix + quote),
                content_end=(tok.end[0], tok.end[1] - quote),
                triple=triple,
            ))
    return spans


def _python_blank_spans(
    text: str,
) -> tuple[list[tuple[int, int]], list[tuple[int, int]]] | None:
    """`(comments, literal_text)` for the router views: absolute `[start, end)` character spans of
    every `#` COMMENT token, and of every string literal's TEXT, from one pass over the token stream.
    None when tokenization fails, so the caller keeps its old behaviour rather than trust half a
    stream. Total: never raises.

    The tokenizer, not a quote-pairing regex, decides what a comment is: on the closing line of a
    multi-line triple-quoted string (`\"\"\"  # restore the "admin" gate: ...`), a per-line masker
    pairs the leftover delimiter quote with a quote inside the comment and hides the `#` (#538).

    Literal text is a plain or bytes literal's content (between its quotes), or an f-string's
    content MINUS its replacement fields, at any nesting depth. A field is code, as
    `strip_python_strings` already treats it, and it is the only part of a single-quoted f-string
    that may span rows (PEP 701), so it must survive whole for the view to stay parseable. Excluding
    only the fields is what lets the text AROUND a multi-row field be blanked: keeping the whole
    literal let `f"router = APIRouter(dependencies=[...]) {\\n name\\n} tail"` mint the auth map
    (#1017 review, High 1). Fields are the `OP` braces at the f-string's own depth; an escaped `{{`
    is never an `OP` token, and a nested f-string or a string inside a field is a literal of its own.

    Rows index `text.split("\\n")`, as `_python_comment_view` documents; columns are code points."""
    starts = [0]
    for line in text.split("\n")[:-1]:
        starts.append(starts[-1] + len(line) + 1)
    comments: list[tuple[int, int]] = []
    literal: list[tuple[int, int]] = []
    # One frame per open f-string: [start of the current literal run, brace depth within it].
    frames: list[list[int]] = []
    try:
        for tok in tokenize.generate_tokens(io.StringIO(text).readline):
            kind = tok.type
            if tok.start[0] > len(starts):
                # With no final newline the stream still closes on the row PAST the last one, where
                # the row table has no entry: the empty DEDENT/ENDMARKER tokens. They place nothing,
                # so they are skipped. Indexing them raised, which read as "no token stream" and sent
                # every such file to the pre-#538 per-line view (#1017 re-review, Critical 1). A
                # token there that carries text is not expected; it still sends the file to that
                # fallback rather than be placed at a guessed offset.
                if tok.string:
                    raise ValueError(f"token past the last row: {tok!r}")
                continue
            start = starts[tok.start[0] - 1] + tok.start[1]
            end = starts[tok.end[0] - 1] + tok.end[1] if tok.end[0] - 1 < len(starts) else start
            if kind == tokenize.COMMENT:
                comments.append((start, end))
            elif kind == tokenize.STRING:
                head = tok.string.lstrip(_STRING_PREFIX)
                quote = 3 if head[:3] in ('"""', "'''") else 1
                literal.append((start + len(tok.string) - len(head) + quote, end - quote))
            elif kind == tokenize.FSTRING_START:
                frames.append([end, 0])
            elif kind == tokenize.FSTRING_END and frames:
                literal.append((frames.pop()[0], start))
            elif kind == tokenize.OP and frames and tok.string in ("{", "}"):
                frame = frames[-1]
                if tok.string == "{":
                    if frame[1] == 0:
                        literal.append((frame[0], start))  # the text run ends where a field opens
                    frame[1] += 1
                else:
                    frame[1] -= 1
                    if frame[1] == 0:
                        frame[0] = end                       # the next run starts after the field
    except Exception:  # stay total — the guards must never crash on a file that does not parse
        return None
    return comments, literal


def _strip_python_strings_uncached(text: str, *, filename: str | Path = "<unknown>") -> str:
    """Blank triple-quoted string CONTENT (line numbers preserved), so anti-pattern EXAMPLES in
    docstrings/templates don't produce false positives in the guards that search for code patterns.

    Lexer-aware via `ast` (issue #366): only *real* triple-quoted string nodes are blanked. A
    triple-quote inside a `#` comment or a single-line string is not an AST node, so it can never be
    mistaken for a docstring delimiter (the regex-only approach mis-paired those and blanked real
    code between them — a silent false negative across the guards). Triple-quoted f-strings
    (`ast.JoinedStr`, e.g. a multi-line prompt template) are blanked too — a naive `STRING`-token
    pass would miss them in 3.12+ and leak an anti-pattern inside the template. Single-line strings
    are left intact (a guard matching inside one is an unlikely but acceptable FP — unchanged
    contract). On parse failure it falls back to the regex, so the helper stays total.

    Implicitly concatenated adjacent literals fold into ONE node (#776), so a node is blanked
    per physical literal (boundaries from the token stream): each triple-quoted constituent —
    wherever it sits in the concatenation — loses its content, while single-quoted constituents
    and the comments between them survive. Treating such a node as one literal kept only the
    first opener plus the last three characters and wiped every interior delimiter, leaving
    text that no longer lexed as Python: every consumer line-scans a silently misaligned file.
    """
    # Parse via the shared total-parse helper (#370/#372) — None on any parser-exhaustion failure.
    # The walk below uses ast.walk (iterative), so nothing beyond the parse needs a guard.
    tree = safe_ast_parse(text, filename=filename)
    if tree is None:
        return _strip_python_strings_regex(text)
    lines = text.splitlines(keepends=True)
    literal_spans = _python_string_literal_spans(text)

    def _is_triple_quoted(node: ast.Constant | ast.JoinedStr) -> bool:
        # A string/f-string opens with `"""`/`'''` after an optional prefix. The prefix is up to two
        # chars (`rb`/`rf`/`fr`/... — #369 review), so slice prefix(2) + quotes(3) before stripping.
        line = lines[node.lineno - 1]
        col = _char_col(line, node.col_offset)
        head = line[col:col + 5].lstrip(_STRING_PREFIX)
        return head[:3] in ('"""', "'''")

    def _keep_spans(node: ast.Constant | ast.JoinedStr) -> list[tuple[int, int, int, int]]:
        """Sub-spans of `node` that are real CODE and must survive the blanking.

        In an f-string the `{expr}` interpolations are code, not string content, and they are
        precisely the signal that a value is dynamic. Blanking them made a triple-quoted
        f-string shell command indistinguishable from a constant one (#439 review). Requires
        Python 3.12+ for per-`FormattedValue` positions, which `requires-python` guarantees;
        a span that is not strictly inside the node is ignored, so an unexpected shape
        degrades to the old blank-everything behavior rather than corrupting offsets."""
        if not isinstance(node, ast.JoinedStr):
            return []
        spans: list[tuple[int, int, int, int]] = []
        for sub in ast.walk(node):
            if not isinstance(sub, ast.FormattedValue):
                continue
            if sub.end_lineno is None or sub.end_col_offset is None:
                continue
            # Byte offsets compared against byte offsets — a valid ordering check on its own
            # (byte length is monotonic in code-point count within one line), but the SPANS this
            # returns feed `_protected()`, which is compared against character indices, so those
            # must be converted before being stored.
            inside = (sub.lineno, sub.col_offset) > (node.lineno, node.col_offset) and (
                (sub.end_lineno, sub.end_col_offset) < (node.end_lineno, node.end_col_offset)
            )
            if inside:
                spans.append((
                    sub.lineno, _char_col(lines[sub.lineno - 1], sub.col_offset),
                    sub.end_lineno, _char_col(lines[sub.end_lineno - 1], sub.end_col_offset),
                ))
        return spans

    def _protected(row: int, col: int, spans: list[tuple[int, int, int, int]]) -> bool:
        return any(
            (sl, sc) <= (row, col) < (el, ec) for sl, sc, el, ec in spans
        )

    def _blank_content(
        srow: int, scol: int, erow: int, ecol: int, keep: list[tuple[int, int, int, int]]
    ) -> None:
        for row in range(srow, erow + 1):
            line = lines[row - 1]
            start = scol if row == srow else 0
            end = ecol if row == erow else len(line.rstrip("\n"))
            if end <= start:
                continue
            blanked = "".join(
                c if (c == "\n" or _protected(row, start + i, keep)) else " "
                for i, c in enumerate(line[start:end])
            )
            lines[row - 1] = line[:start] + blanked + line[end:]

    for node in ast.walk(tree):
        if not isinstance(node, (ast.Constant, ast.JoinedStr)):
            continue
        # Blank triple-quoted str AND bytes constants (parity with the old regex, which was
        # prefix-agnostic), plus f-strings (JoinedStr). Skip numeric/None/other constants.
        if isinstance(node, ast.Constant) and not isinstance(node.value, (str, bytes)):
            continue
        if node.end_lineno is None or node.end_col_offset is None:
            continue
        # Implicit concatenation folds ADJACENT literals into this one node (#776). When the
        # token stream shows more than one physical literal inside the node span, blank each
        # triple-quoted constituent's own content: the single-literal arithmetic below would
        # keep only the FIRST opener plus the LAST 3 characters and wipe every interior
        # delimiter (unbalanced quotes — the stripped text stops lexing as Python, and every
        # line-scanning consumer sees a misaligned file from there to EOF). Per-literal
        # handling also blanks a triple-quoted literal that is NOT first, which the node-head
        # `_is_triple_quoted` gate used to skip wholesale.
        if literal_spans is not None:
            node_start = (node.lineno, _char_col(lines[node.lineno - 1], node.col_offset))
            node_end = (node.end_lineno, _char_col(lines[node.end_lineno - 1], node.end_col_offset))
            parts = [
                lit for lit in literal_spans
                if node_start <= lit.start and lit.end <= node_end
            ]
            if len(parts) > 1:
                keep = _keep_spans(node)
                for lit in parts:
                    if lit.triple:
                        _blank_content(*lit.content_start, *lit.content_end, keep)
                continue
        if not _is_triple_quoted(node):
            continue
        # Blank the CONTENT, keeping the delimiters — which is what this function's own
        # docstring always promised. Blanking the node span INCLUDING its `f"""` / `"""` left
        # `os.system(f"""tar {d}""")` as `os.system(              )`, so the consumer saw an
        # empty argument and every dynamic-value check went silent (#439 review).
        open_col = _char_col(lines[node.lineno - 1], node.col_offset)
        head = lines[node.lineno - 1][open_col:open_col + 5]
        open_len = len(head) - len(head.lstrip(_STRING_PREFIX)) + 3   # prefix + `"""`
        first_col = open_col + open_len
        last_col = _char_col(lines[node.end_lineno - 1], node.end_col_offset) - 3   # closing `"""`
        _blank_content(node.lineno, first_col, node.end_lineno, last_col, _keep_spans(node))
    return "".join(lines)


def _dedupe_overlapping_scan_dirs(dirs: list[Path]) -> list[Path]:
    """Drop any directory that is itself, or a subdirectory of, another directory already in
    the list. `iter_files`/`walk_files` recurse, so a caller that iterates `[root, root/"guards"]`
    would walk every file under `guards/` TWICE — once via each entry — and any guard using the
    ``for d in python_scan_dirs(...): for f in iter_files(d, ...)`` double-loop pattern (the vast
    majority of them) would emit a duplicate `Finding` for every match found in the overlap.
    Confirmed live, not theoretical: agentsec's own `profile.python_dirs` resolves to BOTH `.`
    (root) and several of its own subdirectories (`guards`, `checklist`, `ci`, `hostaudit`,
    `runners`, `ai`) simultaneously, so this bug fires on agentsec's own self-audit for any guard
    whose pattern happens to match something under one of those subdirectories — caught via
    `test_self_audit.py`'s 1:1 baseline-count assertion when `llm-json-output-unvalidated` emitted
    the identical finding twice for one line in `guards/llm_output_secrets_unscanned.py` (#701).
    Order-independent: sorts by path length first so a shorter (more likely ancestor) directory is
    kept over a longer descendant regardless of the input list's original order.
    """
    kept: list[Path] = []
    for d in sorted(dirs, key=lambda p: len(str(p))):
        if not any(d == k or d.is_relative_to(k) for k in kept):
            kept.append(d)
    return kept


# === helpers: Scan roots ====================================================================================
def python_scan_dirs(root: Path, profile: StackProfile) -> list[Path]:
    """Resolve the detected python dirs to absolute paths (fallback: root)."""
    dirs = [root / d for d in profile.python_dirs if d != "."]
    if "." in profile.python_dirs or not dirs:
        dirs.append(root)
    return _dedupe_overlapping_scan_dirs([d for d in dirs if d.is_dir()])


def go_scan_dirs(root: Path, profile: StackProfile) -> list[Path]:
    """Resolve the detected go dirs to absolute paths (fallback: root). Mirrors
    `python_scan_dirs` exactly — same shape, same fallback rule, different source field."""
    dirs = [root / d for d in profile.go_dirs if d != "."]
    if "." in profile.go_dirs or not dirs:
        dirs.append(root)
    return _dedupe_overlapping_scan_dirs([d for d in dirs if d.is_dir()])


def php_scan_dirs(root: Path, profile: StackProfile) -> list[Path]:
    """Resolve the detected php dirs to absolute paths (fallback: root). Mirrors
    `python_scan_dirs`/`go_scan_dirs` exactly — same shape, same fallback rule, different source field."""
    dirs = [root / d for d in profile.php_dirs if d != "."]
    if "." in profile.php_dirs or not dirs:
        dirs.append(root)
    return _dedupe_overlapping_scan_dirs([d for d in dirs if d.is_dir()])


def java_scan_dirs(root: Path, profile: StackProfile) -> list[Path]:
    """Resolve the detected java dirs to absolute paths (fallback: root). Mirrors
    `python_scan_dirs`/`go_scan_dirs` exactly — same shape, same fallback rule, different source field."""
    dirs = [root / d for d in profile.java_dirs if d != "."]
    if "." in profile.java_dirs or not dirs:
        dirs.append(root)
    return _dedupe_overlapping_scan_dirs([d for d in dirs if d.is_dir()])


def ruby_scan_dirs(root: Path, profile: StackProfile) -> list[Path]:
    """Resolve the detected ruby dirs to absolute paths (fallback: root). Mirrors
    `python_scan_dirs`/`go_scan_dirs` exactly — same shape, same fallback rule, different
    source field (brakeman research batch)."""
    dirs = [root / d for d in profile.ruby_dirs if d != "."]
    if "." in profile.ruby_dirs or not dirs:
        dirs.append(root)
    return _dedupe_overlapping_scan_dirs([d for d in dirs if d.is_dir()])


_DEF = re.compile(r"(?P<indent>[ \t]*)(?:async[ \t]+)?def[ \t]+\w+[ \t]*\(")
# Only used by `_iter_functions_lines` to track the enclosing-scope chain (a `class` opens a
# scope that is NOT a function body), so it can reproduce the ast path's `include_closures`
# decision without a parse tree.
_CLASS_DEF = re.compile(r"(?P<indent>[ \t]*)class[ \t]+\w+")
# Escape-aware single-line string literal: a quote, then any run of escaped chars (`\\.`) or
# non-quote/non-backslash chars, then the closing quote. Without the `\\.` alternative an escaped
# quote (`"a \" b"`) mis-splits and leaks the bracket that follows it into the balance count.
_SL_STRING = re.compile(r'"(?:\\.|[^"\\\n])*"|\'(?:\\.|[^\'\\\n])*\'')
_OPENERS = "([{"
_CLOSERS = ")]}"


# === helpers: Comment & string blanking =====================================================================
def strip_python_line_comment(line: str) -> str:
    """Remove a trailing `#` line-comment from one physical line of Python, WITHOUT clipping a
    `#` that lives inside a single-line string literal (`logger.info("tag #%s", x)` keeps `x`).

    The Python-context complement of `strip_hash_comments` (which is for whole-`#`-comment formats
    like YAML/shell, where any `#` starts a comment). In Python a `#` is only a comment *outside* a
    string, so a naive `line.split("#", 1)[0]` clips a string that contains a `#` and silently
    drops the real code after it (the false-positive class #362 exists to kill). We MASK single-line
    string literals (equal length, no surviving `#`) to locate the first REAL `#`, then truncate the
    ORIGINAL line there — so string CONTENT a caller still needs (`event["id"]`, or a bracket inside
    a string for `_bracket_delta`) survives. Triple-quoted strings are out of scope: blank them
    upstream with `strip_python_strings` first. Even then, the CLOSING line of a multi-line one keeps
    its delimiter, whose odd quote count can pair with a quote inside a trailing comment and hide
    its `#` (`\"\"\"  # the "admin" gate`); a caller that must not miss a comment there reads the
    token stream instead, as `router_resolver_view` does (#538)."""
    masked = _SL_STRING.sub(lambda m: " " * len(m.group()), line)
    cut = masked.find("#")
    return line if cut == -1 else line[:cut]


def _bracket_delta(line: str) -> int:
    """`closes - opens` for the round/square/curly brackets on one physical line, ignoring
    bracket characters that are not real structure: those inside a single-line string literal
    (`"/items("`) or a trailing `#` comment (`# note (see X`). A bracket miscount silently drops
    or merges a route, so both are stripped before counting. Triple-quoted strings are already
    blanked upstream by `iter_functions`/`strip_python_strings`."""
    src = _SL_STRING.sub("", strip_python_line_comment(line))  # drop the comment (string-safe), then strings
    return sum(c in _CLOSERS for c in src) - sum(c in _OPENERS for c in src)


# A REGISTRATION decorator: one that publishes the function it decorates as an externally
# reachable entry point — an HTTP route (`@app.post`, `@router.api_route`, `@app.websocket`)
# or an agent tool (`@tool`, `@mcp.tool`, `@agent.tool_plain`).
# `iter_functions(include_closures=False)` uses it to tell a factory-REGISTERED nested `def`
# (a real route/tool, which must be analysed on its own) from a private nested helper. Merely
# HAVING a decorator is NOT enough: `@functools.lru_cache` / `@staticmethod` / `@retry` on an
# inner helper do not make it a route, and treating them as one resurrected the exact false
# positive `include_closures=False` exists to kill (#452 re-review).
#
# Deliberately shape-based rather than a per-guard allowlist: the six decorator-gated consumers
# re-check decorator CONTENT themselves, so this only has to be right for the annotation-gated
# one. Three deliberate narrowings, each from sweeping every decorator stack in a 3k-file corpus
# (stdlib + site-packages + this repo) and reading what it accepted:
#   * the HTTP verb REQUIRES a receiver (`@app.post`, not bare `@post`) — matching the house
#     shape in `bola`/`privileged_field_assignment` — because bare `@patch(...)` is
#     `unittest.mock.patch`, not a PATCH route (8 hits in the corpus);
#   * a receiver that is a MOCK PATCHER (`_is_mock_receiver`) is rejected: `@mock.patch`,
#     `@unittest.mock.patch`, and equally `@webmock.patch` / `@apimock.patch` / `@redis_mock.patch`;
#   * `head`/`options` are omitted: those verbs carry no request body (so no upload route uses
#     them) and `options` is the most over-matchable word in the alternation.
# After these, the corpus accepts 4 distinct stacks, all genuine routes, out of 763.
#
# Style note: the route decorators in the prose above are written WITHOUT their trailing `(` on
# purpose. `@app.post(` spelled literally in this file is exactly what the route-shaped guards
# scan for, and it made agentsec self-report a route inside `base.py`.
_ROUTE_VERB = r"get|post|put|patch|delete|websocket|api_route|route"
_REGISTRATION_DECORATOR = re.compile(
    # HTTP route: a verb on a receiver — `@app.post`, `@router.api_route`. The receiver is
    # captured rather than excluded by a lookbehind, because a lookbehind cannot be shared with
    # the alias-binding rule below — both need the SAME receiver test (`_is_mock_receiver`).
    rf"@\s*(?P<recv>[\w.]+)\s*\.\s*(?P<verb>{_ROUTE_VERB})\b"
    # Agent tool: bare `@tool`, or `@mcp.tool()` / `@agent.tool_plain`.
    r"|@\s*(?:[\w.]+\s*\.\s*)?tool(?:_plain)?\b",
    re.IGNORECASE,
)
# A bare, single-name decorator — `@post(...)`, `@post`. Only a registration when the name is
# bound to a route method elsewhere in the same module; see `route_decorator_aliases`.
_BARE_DECORATOR = re.compile(r"@\s*(?P<name>[A-Za-z_]\w*)\s*(?:\(|$)")
# `post = router.post` / `get = app.get` — the local-alias idiom. A decorator using the alias is a
# real route registration, and missing it collapsed the route into its factory's block, where a
# SIBLING route's cap suppressed it: a genuinely unguarded upload route went 1 -> 0 (#452 gate).
#
# The receiver is CAPTURED (not `[\w.]+` anonymous) so the binding gets the same `_is_mock_receiver`
# test as a direct decorator: without it, an ordinary `patch = mock.patch` re-admitted the bare
# `@patch(...)` mock form through the alias door — the very shape the receiver requirement above
# rejects (#452 gate, finding 2).
#
# A trailing `#` comment is tolerated: `post = router.post  # shorthand` is the same statement, and
# anchoring `[ \t]*$` straight after the verb meant two spaces and a `#` restored the CRITICAL
# false negative verbatim (#452 gate, finding 3).
#
# KNOWN RESIDUALS of this rule's shape, deliberately left open. The first two LOSE a route rather
# than invent one (the safe direction), and each widens the LHS/receiver grammar on an axis with no
# corpus evidence, so each needs its own FP battery before it ships; both are pinned by name in
# `tests/guards/test_base.py` so a future widening is a deliberate flip:
#   * an ANNOTATED assignment, `post: Any = router.post`;
#   * a CALL receiver, `@get_router().post(...)` (pre-existing, not introduced by the alias rule).
# The third is a false POSITIVE and is kept only because it is empirically empty: a dict/cache
# lookup binding (`get = cache.get`) is indistinguishable from a route alias by shape, so a module
# that also uses a bare `@get` decorator would promote a private helper. Measured over 1815
# stdlib+site-packages modules: 8 bind an alias, ALL of them a `.get` lookup, and ZERO use the
# bound name as a bare decorator — so the FP path exists but is unoccupied. Narrowing it (dropping
# `get` from the binding verbs, the way `head`/`options` are already dropped) is the obvious move
# if that ever changes; it is not made blind here.
_ROUTE_ALIAS_BINDING = re.compile(
    rf"^[ \t]*(?P<alias>[A-Za-z_]\w*)[ \t]*=[ \t]*(?P<recv>[\w.]+)\.(?:{_ROUTE_VERB})"
    # `\r` is tolerated in the tail so the rule survives CRLF source. `read()` normalizes line
    # endings before a guard ever sees a file, but `iter_functions` is a shared helper and its
    # parity tests feed CRLF directly — a `$`-anchored rule that silently dies on `\r\n` is the
    # kind of Windows-shaped footgun this repo has swept twice (#75/#77).
    r"[ \t]*(?:#[^\r\n]*)?[ \t\r]*$",
    re.IGNORECASE | re.MULTILINE,
)


def _is_mock_receiver(recv: str) -> bool:
    """True if a decorator/binding receiver is a mock patcher rather than a route object.

    `@mock.patch` / `@unittest.mock.patch` are `unittest.mock`, and so — by every reading of their
    names — are `@webmock.patch`, `@apimock.patch`, `@redis_mock.patch`. None of them is an HTTP
    PATCH route, so the test is "the LAST dotted segment ENDS in `mock`". Segment-scoped so it is
    anchored (the old unanchored `(?<!mock\\.)` lookbehind was a raw 5-character substring test),
    but not segment EQUALITY: equality re-admitted the `*mock` receivers as routes, a measured
    0 -> 1 false positive against the parent commit (#452 gate, finding 5)."""
    return recv.split(".")[-1].lower().endswith("mock")


# === helpers: FastAPI routes & cross-file auth ==============================================================
def route_decorator_aliases(text: str) -> frozenset[str]:
    """Names bound to a route method in this module (`post = router.post`).

    Module-scoped and binding-based rather than name-based: only a name actually assigned from a
    `<receiver>.<verb>` counts, so an ordinary local called `post` never promotes a helper. A mock
    receiver (`patch = mock.patch`) is not a route method and binds nothing.

    **Contract: pass source whose triple-quoted strings are already blanked**
    (`strip_python_strings`). A `post = router.post` sitting in a docstring or an example snippet
    is PROSE, not a binding, and promoting every bare `@post` helper in the module off the back of
    it re-opened the exact closure false positive `include_closures=False` exists to kill
    (#452 gate, finding 1). Both call sites in this module strip first, and
    `test_alias_rule_ast_line_walker_parity` pins that they agree.
    """
    return frozenset(
        m.group("alias")
        for m in _ROUTE_ALIAS_BINDING.finditer(text)
        if not _is_mock_receiver(m.group("recv"))
    )


def _is_registration(deco_lines: list[str], aliases: frozenset[str] = frozenset()) -> bool:
    """True if this decorator stack contains a registration decorator (`_REGISTRATION_DECORATOR`).

    Takes the raw decorator-stack LINES (interleaved blank/comment lines are fine) so the ast path
    and `_iter_functions_lines` share one decision and stay construct-for-construct identical.

    Trailing `#` comments and single-line string literals are removed first, so neither a
    commented-out route decorator nor a decorator *argument* that merely quotes one
    (``@register("@app.post")``) can promote a private helper to a route.

    `aliases` are module-local names bound to a route method (`route_decorator_aliases`); a bare
    `@post(...)` counts only when it is one of them."""
    for ln in deco_lines:
        cleaned = _SL_STRING.sub("", strip_python_line_comment(ln))
        for m in _REGISTRATION_DECORATOR.finditer(cleaned):
            recv = m.group("recv")
            # `@mock.patch` / `@webmock.patch` are patchers, not the HTTP verb — one shared
            # receiver test with the alias-binding rule, so neither door lets a mock through.
            if recv and _is_mock_receiver(recv):
                continue
            return True
        if aliases:
            bare = _BARE_DECORATOR.match(cleaned.strip())
            if bare and bare.group("name") in aliases:
                return True
    return False


def _deco_lines(node: ast.FunctionDef | ast.AsyncFunctionDef, lines: list[str]) -> list[str]:
    """The physical source lines of a `def`'s decorator stack — the ast path's input to
    `_is_registration`. Spans from the first decorator through the line before the ``def``, so a
    multi-line decorator call and any interleaved comment/blank line are included, exactly like
    `_iter_functions_lines`' `deco` buffer (the two must agree construct-for-construct)."""
    if not node.decorator_list:
        return []
    start = min(d.lineno for d in node.decorator_list)
    return lines[start - 1:node.lineno - 1]


def _blank_nested_registered(
    spans: list[tuple[int, int, int]],
    nested: list[tuple[int, int, int]],
    lines: list[str],
) -> list[tuple[int, str]]:
    """Materialize `(def_lineno, block-text)` from line spans, blanking every REGISTRATION-decorated
    nested ``def`` out of the block of each function that ENCLOSES it.

    The shared tail of both walkers, so the ast path and `_iter_functions_lines` produce identical
    text by construction rather than by two implementations agreeing.

    ``spans`` is `(def_lineno, first_line, last_line)` — 1-based, inclusive — for every block being
    emitted. ``nested`` is the same triple for the subset of registration-decorated ``def``\\ s that
    sit inside another function.

    **Why (issue #502).** `iter_functions` emits a nested ``def`` as its own entry *and* leaves its
    source inside the enclosing function's block, which makes the enclosing block a strict superset
    of every block nested in it. A consumer that decides "is this a route?" by searching the whole
    block therefore inherits its children's decorators: an undecorated ``def make_app():`` that
    registers one ``@app.post`` route matched the route gate too, and the same real route was
    reported twice — once anchored on the factory, which carries no decorator at all. Measured on
    `bola`, `auth-dependency-not-applied`, `privileged-field-assignment`,
    `unauthenticated-file-download` and (through its ``UploadFile``-annotated parameter gate rather
    than a decorator) `upload-no-size-limit`.

    The claim that made this ship is still worth reading, because it was reasonable and wrong:
    "emitting both is safe for the decorator-gated guards, an undecorated enclosing factory does not
    match their route/tool patterns" (966427bd). True of the factory's own ``def`` line; false of its
    block text, which is where those guards actually look.

    **Restricted to REGISTRATION-decorated defs on purpose.** Blanking *every* nested ``def`` — the
    obvious reading — trades this duplicate for a false negative: a route whose sink sits in an
    ordinary private closure (``def _load(): return Order.query.get(oid)``) would lose that sink
    from the route's own block and stop firing. A closure is not separately reported (it matches no
    route/tool pattern), so it must stay visible to its parent. Only a nested ``def`` that is
    *itself* emitted as a route/tool — i.e. one carrying a registration decorator — is removed from
    its ancestors, because that block already carries the finding.

    Blanked to EMPTY LINES, never deleted: every consumer's block offsets and the physical line
    numbers inside a block stay exactly as they were, so nothing downstream has to know this ran.
    """
    out: list[tuple[int, str]] = []
    for lineno, start, end in spans:
        segment = list(lines[start - 1:end])
        for nested_lineno, nested_start, nested_end in nested:
            if nested_lineno == lineno:
                continue                                  # this block's OWN def is never blanked
            if nested_start < start or nested_end > end:
                continue                                  # not enclosed by this block
            for physical in range(nested_start, nested_end + 1):
                segment[physical - start] = ""
        out.append((lineno, "\n".join(segment)))
    return out


def _iter_functions_lines(
    text: str, *, include_closures: bool = True, filename: str | Path = "<unknown>"
) -> list[tuple[int, str]]:
    """Line-based fallback for `iter_functions`, used only when `ast.parse` fails (issue #281).

    A bracket-balance heuristic that re-implements Python lexing with regex. `iter_functions`
    now prefers an `ast` pass (correct by construction); this walker survives as the
    never-crash fallback for input that does not parse. It is bracket-aware so the shapes a
    naive line-by-line walk drops — each of which otherwise makes a decorated route invisible
    (a silent false negative) — are handled:

      * **Multi-line decorator calls** (`@router.post(\\n  "/x",\\n  status_code=201,\\n)`):
        the continuation lines and the closing ``)`` are pulled into the stack by unwinding
        bracket balance upward, not only lines that literally start with ``@``. The unwind is
        provisional — committed only when the line that re-balances it is itself a decorator —
        so an unrelated multi-line expression sitting above the decorator is not absorbed.
      * **Comment/blank lines interleaved in the stack** (e.g. a ``# security: ...`` pragma
        between the last decorator and the ``def``): buffered and kept only once a decorator is
        confirmed above them, so a plain leading comment on an un-decorated function is not
        wrongly pulled in.
      * **Multi-line function signatures** (`def f(\\n  a,\\n) -> dict:`): the whole header is
        consumed before the body scan begins, so the body — and any pragma / ``current_user``
        reference in it — is not truncated at the closing ``) -> ...:`` line, which sits at the
        ``def``'s own indent.

    Triple-quoted string content is blanked first (via `strip_python_strings`, line numbers
    preserved) so a stray bracket inside a triple-quoted ``description=`` OpenAPI doc — a common
    shape in a route decorator/signature — cannot skew the bracket-balance count and silently drop
    or merge a route. (Single-line string brackets are handled separately in `_bracket_delta`.)

    ``include_closures`` mirrors `iter_functions`' parameter of the same name — see it for the
    definition. Reproduced here without a parse tree by tracking the ``def``/``class`` header
    indents as a scope stack, so the two paths stay construct-for-construct identical under both
    settings.
    """
    text = strip_python_strings(text, filename=filename)
    lines = text.splitlines()
    n = len(lines)
    # From the STRING-BLANKED text. Computed under BOTH `include_closures` settings since #502:
    # `_is_registration` used to be reachable only for the closure decision (`include_closures=False`),
    # and now also decides which nested defs are blanked out of their enclosing block, which every
    # caller needs. See `iter_functions`, which must compute this identically for the two paths to
    # stay construct-for-construct equal.
    aliases = route_decorator_aliases(text)
    # `(def_lineno, first_line, last_line)` per emitted block, 1-based inclusive — the text is
    # materialized once at the end by `_blank_nested_registered`, shared with the ast path.
    spans: list[tuple[int, int, int]] = []
    nested_registered: list[tuple[int, int, int]] = []
    # Enclosing block headers as (indent, opens_a_function_scope). A `class` pushes False: a
    # method of a top-level class is not a closure, but a def inside a class inside a function
    # is (matching how the ast path threads `in_func` through a ClassDef unchanged).
    scopes: list[tuple[int, bool]] = []
    depth = 0                               # open-bracket depth carried across physical lines
    i = 0
    while i < n:
        line = lines[i]
        stripped = line.strip()
        # Scope bookkeeping runs only on a line that STARTS a statement. A blank/comment line
        # carries no indentation meaning, and a CONTINUATION line inside brackets actively
        # lies: the `) -> int:` closing a multi-line signature sits at column 0 and would pop
        # the very `def` it belongs to.
        starts_stmt = depth == 0 and bool(stripped) and not stripped.startswith("#")
        depth = max(0, depth - _bracket_delta(line))     # delta is closes - opens
        indent = len(line) - len(line.lstrip())
        m = _DEF.match(line)
        if starts_stmt:
            # Any statement dedenting to <= a header's indent closes that header's suite —
            # not only another `def`/`class`. Without this, a `def` under a module-level
            # `if TYPE_CHECKING:` would still look nested inside the last top-level function.
            while scopes and scopes[-1][0] >= indent:
                scopes.pop()
        in_func = any(is_func for _, is_func in scopes)
        if starts_stmt and (m is not None or _CLASS_DEF.match(line) is not None):
            scopes.append((indent, m is not None))
        if not m:
            i += 1
            continue
        def_indent = len(m.group("indent"))

        # Walk UP to gather the decorator stack. `buf` holds comment/blank lines pending a
        # decorator above them (kept only if one is found).
        deco: list[str] = []
        buf: list[str] = []
        j = i - 1
        while j >= 0:
            line = lines[j]
            stripped = line.lstrip()
            if stripped.startswith("@"):
                deco[:0] = buf
                buf = []
                deco.insert(0, line)
                j -= 1
            elif not stripped or stripped.startswith("#"):
                buf.insert(0, line)
                j -= 1
            elif _bracket_delta(line) > 0:
                # A net-closing line (e.g. a lone `)`) may close a multi-line decorator
                # above. Unwind brackets upward provisionally; commit only if the line that
                # re-balances the stack is a decorator (else it's unrelated code — stop).
                temp = [line]
                bal = _bracket_delta(line)
                p = j - 1
                while p >= 0 and bal > 0:
                    temp.insert(0, lines[p])
                    bal += _bracket_delta(lines[p])
                    p -= 1
                if bal == 0 and lines[p + 1].lstrip().startswith("@"):
                    deco[:0] = buf
                    buf = []
                    deco[:0] = temp
                    j = p
                else:
                    break
            else:
                break

        # Walk DOWN. First consume the (possibly multi-line) def header: the def line opens
        # the signature's `(`, so cumulative bracket depth returns to <= 0 exactly at the line
        # that closes the signature (line `i` itself for a single-line signature).
        #
        # `sig_depth` is deliberately NOT named `depth`: it used to be, which CLOBBERED the outer
        # `depth` that carries bracket balance across physical lines for `starts_stmt`. The outer
        # loop advances by one line, so the next iteration read this signature-local leftover as
        # the true per-line state. When a multi-line signature's closing line sits at the `def`'s
        # own indent (black's layout for a trailing-comma parameter list, and any top-level `def`
        # at column 0), the def's scope was popped before its body, so a genuinely nested closure
        # saw `in_func=False` and was emitted even under `include_closures=False` — breaking
        # ast/line-walker parity (#452 re-review).
        sig_depth = 0
        h = i
        while h < n:
            sig_depth += -_bracket_delta(lines[h])
            if sig_depth <= 0:
                break
            h += 1
        # Body: until a non-blank line dedents to <= the def's indent.
        k = h + 1
        while k < n:
            ln = lines[k]
            if ln.strip():
                indent = len(ln) - len(ln.lstrip())
                if indent <= def_indent:
                    break
            k += 1
        registered = _is_registration(deco, aliases)
        # `deco` is always the contiguous run of physical lines immediately above the `def` (the
        # walk-up commits its comment/blank buffer only behind a decorator), so the block's first
        # line is the `def` line minus the stack height.
        start = i + 1 - len(deco)
        if include_closures or not in_func or registered:
            spans.append((i + 1, start, k))
        if in_func and registered:
            # A route/tool registered inside another function: it is emitted as its own block, so
            # it is blanked out of every block that encloses it (#502). See
            # `_blank_nested_registered`.
            nested_registered.append((i + 1, start, k))
        # Advance ONE line, not past the whole body, so a `def` nested inside this one is
        # found too — keeping this fallback's output shape identical to the ast path's
        # (see `iter_functions._visit`). Skipping the body made a factory-registered tool or
        # route invisible on files that fail to parse, and made the two paths disagree about
        # the same construct (#452 review).
        i = i + 1
    return _blank_nested_registered(spans, nested_registered, lines)


# === helpers: Text & call-site scanning =====================================================================
def iter_functions(
    text: str, *, include_closures: bool = True, filename: str | Path = "<unknown>"
) -> list[tuple[int, str]]:
    """Split a module into ``(def-line-number, block-text)`` pairs — the decorator stack above a
    ``def`` plus the ``def`` header and its indented body.

    Shared by the function-scoped guards (`bola`, `auth-dependency-not-applied`,
    `unauthenticated-file-download`, `privileged-field-assignment`, `tool-chaining-exfil`,
    `tool-callback-enforcement`, `upload-no-size-limit`, `webhook-signature-not-verified`) plus,
    via `enclosing_function()` below, the fixed-window-to-enclosing-body migration
    (`zip-bomb`, `websocket-origin`, `zip-slip`, `agent-tool-audit-log`, `no-cache-on-sensitive`,
    `langchain-load-prompt-traversal`). Each puts the ``lineno`` in its finding location and
    regex-scans the ``block``, so both are load-bearing:

      * ``lineno`` is the 1-based physical line of the ``def`` (``node.lineno``).
      * ``block`` is the source from the first decorator (or the ``def`` if undecorated) through
        the body, with triple-quoted string content **blanked** (line numbers preserved) so a
        docstring anti-pattern doesn't fire and a stray bracket in an OpenAPI ``description=``
        can't skew anything. Comment lines (route-scoped ``# security: allow-...`` pragmas)
        survive verbatim, in the decorator stack **and** the body tail.

    Uses Python's own parser (`ast`) rather than a line-based bracket heuristic: strings,
    comments, bracket nesting, multi-line decorators/signatures, and "unrelated expression above
    the decorator" are all handled correctly by construction (issue #281). Two boundary rules
    reproduce the exact block the guards expect:

      * The body extends past ``end_lineno`` (which stops at the last *statement*) over any
        trailing blank / comment / more-indented line, so a pragma placed after the final
        statement is still inside the block.
      * Nested ``def``\\ s (inside another function body) ARE emitted as their own entry, in
        addition to the enclosing function's block: an ``@tool``/``@router.post``-decorated
        function registered inside a factory is a real route/tool, and collapsing it into the
        factory's block let any token elsewhere in that factory suppress it (#452 review).
      * A nested ``def`` that carries a REGISTRATION decorator is then blanked out of the block of
        every function that encloses it (blank lines, so line numbers are untouched). Without that,
        the enclosing block is a strict superset of the nested one, and a consumer that asks "is
        this a route?" of the whole block inherits its children's decorators — a factory was
        reported as a second copy of the route it registers (#502). An undecorated closure is NOT
        blanked: it is never emitted separately, so its parent has to keep seeing it. See
        `_blank_nested_registered`.

    ``include_closures`` (default ``True``) controls that last rule. A *closure*, here, is a
    ``def`` nested inside another function body that is NOT registered as an entry point — a
    private helper. A nested ``def`` carrying a REGISTRATION decorator (`_REGISTRATION_DECORATOR`:
    an HTTP-route or agent-tool decorator — the factory-registered route/tool above) is not a
    closure and is emitted under either setting. The test is decorator CONTENT, not "has any
    decorator": a private helper wearing an unrelated ``@functools.lru_cache`` / ``@staticmethod``
    / ``@retry`` is still a closure (#452 re-review).

    Pass ``include_closures=False`` when the caller decides
    "is this a route?" from something OTHER than the decorator stack — today only
    `upload-no-size-limit`, which gates on a ``: UploadFile`` PARAMETER ANNOTATION. An inner
    helper that merely *receives* the route's ``UploadFile`` carries that annotation too, so with
    closures included the helper was reported as an unguarded upload route even though the
    enclosing route enforced the cap (#452 re-review). The six decorator-gated consumers
    (`bola`, `auth-dependency-not-applied`, `privileged-field-assignment`, `tool-chaining-exfil`,
    `unauthenticated-file-download`, `tool-callback-enforcement`) take the default and are
    unaffected: an undecorated closure never matches their route/tool patterns anyway.

    That last sentence is about the CLOSURE, and it used to be read as covering the reverse
    direction too. It does not. The *enclosing* block contains a decorated nested route's text and
    therefore does match those patterns, which is why four of those six reported every
    factory-registered route twice until the blanking rule above landed (#502). Nothing in
    `include_closures` protects a consumer that infers a property of one ``def`` from text that may
    belong to a nested one.

    Guards must stay total: on input that does not parse, or that exhausts the parser / this
    walker's own recursion (``SyntaxError``/``ValueError``/``RecursionError``/``MemoryError`` — a
    deeply nested expression can trip any of these), it falls back to the line-based
    `_iter_functions_lines`, which is iterative and never raises.
    """
    # `(def_lineno, first_line, last_line)` per emitted block, 1-based inclusive; `nested_registered`
    # is the subset of registration-decorated defs sitting inside another function. The text is
    # materialized once at the end by `_blank_nested_registered`, shared with the line walker.
    spans: list[tuple[int, int, int]] = []
    nested_registered: list[tuple[int, int, int]] = []
    # Bound below, from the STRING-BLANKED source — NEVER from the raw `text`. Reading raw text
    # let a `post = router.post` sitting in a docstring or an example snippet promote every bare
    # `@post` inner helper in the module to a "route", re-opening the closure false positive and
    # breaking this file's ast/line-walker parity doctrine (the line walker has always computed it
    # post-strip). Measured 0 -> 1 through the real guard, parity 2/2 -> 3/2 (#452 gate, finding 1).
    aliases: frozenset[str] = frozenset()

    def _span(node: ast.FunctionDef | ast.AsyncFunctionDef, lines: list[str], n: int) -> tuple[int, int]:
        """This def's `(first_line, last_line)`, 1-based inclusive — decorator stack through body."""
        start = min((d.lineno for d in node.decorator_list), default=node.lineno)
        def_line = lines[node.lineno - 1]
        def_indent = len(def_line) - len(def_line.lstrip())
        end = node.end_lineno or node.lineno            # 1-based; also the index of the next line
        while end < n:                                  # pull in a trailing body comment/blank tail
            tail = lines[end]
            if tail.strip() and (len(tail) - len(tail.lstrip())) <= def_indent:
                break
            end += 1
        return start, end

    def _visit(node: ast.AST, lines: list[str], n: int, in_func: bool) -> None:
        # Emit a def AND descend into its body, so a def nested inside another function is
        # emitted as its own block.
        #
        # This branch used to stop at the outer def. That made a factory-registered function
        # invisible: an `@tool`-decorated `wipe_users` defined inside `make_tools(db)` collapsed
        # into the factory's block, so any `confirm`-ish token anywhere in that factory — a local
        # helper, or a `# TODO: add a confirmation step` forty lines below — suppressed it
        # (#452 review). Same collapse hid an unguarded nested upload route behind a `max_size`
        # name elsewhere in its factory. `_iter_functions_lines` skipped the body for the same
        # reason and is changed to match, so the two paths still agree construct-for-construct.
        #
        # Emitting both was believed safe for the six surfacing guards that gate on a DECORATOR: an
        # undecorated enclosing factory "does not match their route/tool patterns, so the inner def
        # is added without the outer double-reporting it". The factory's own `def` line does not
        # match; its BLOCK TEXT does, because it contains the inner def verbatim, and four of those
        # six search the whole block. So the inner is also blanked out of the outer's block below
        # (`nested_registered`), which is what actually makes emitting both safe (#502). It is NOT
        # safe on its own for a consumer that
        # gates on a parameter ANNOTATION — an inner helper that merely receives the route's
        # `UploadFile` carries the annotation without being a route — so those pass
        # `include_closures=False` and a nested def is emitted only when its decorator stack
        # REGISTERS it (`_is_registration`); `in_func` tracks the enclosing scope kind. The test
        # is decorator CONTENT, not "has any decorator": a private helper wearing an unrelated
        # `@functools.lru_cache` is still a helper, and accepting it resurrected the very false
        # positive this flag exists to kill (#452 re-review).
        #
        # Expression nodes are still skipped: a `def` is always a statement, so an expression can
        # never contain one, and walking a deep expression tree (a long module-level `a + b + ...`
        # chain) would otherwise recurse to its depth and raise RecursionError — a totality
        # regression vs the line walker (#367).
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                registered = _is_registration(_deco_lines(child, lines), aliases)
                start, end = _span(child, lines, n)
                if include_closures or not in_func or registered:
                    spans.append((child.lineno, start, end))
                if in_func and registered:
                    # A route/tool registered inside another function: it is emitted as its own
                    # block, so it is blanked out of every block that encloses it (#502). See
                    # `_blank_nested_registered`.
                    nested_registered.append((child.lineno, start, end))
                _visit(child, lines, n, True)
            elif not isinstance(child, ast.expr):
                # A ClassDef does not RESET `in_func`: a method of a class defined inside a
                # function is still inside that function's body (and is not a route).
                _visit(child, lines, n, in_func)

    # Guards must stay total. The line walker never raised; the ast path can on pathological but
    # parseable input, so the parse goes through the shared `safe_ast_parse` helper (#370/#372),
    # which catches the full exhaustion set and returns None → fall back to the never-raising line
    # walker. `strip_python_strings` is itself total (its own safe_ast_parse), and `_visit` skips
    # ast.expr so it can't recurse — so nothing beyond the parse needs a guard.
    tree = safe_ast_parse(text, filename=filename)
    if tree is None:
        return _iter_functions_lines(text, include_closures=include_closures, filename=filename)
    stripped = strip_python_strings(text, filename=filename)
    # Computed under BOTH `include_closures` settings since #502: `_is_registration` used to serve
    # only the closure decision, and now also decides which nested defs are blanked out of their
    # enclosing block. Once per call (`route_decorator_aliases` scans the module) — the line walker
    # must compute it identically or the two paths diverge on the same file.
    aliases = route_decorator_aliases(stripped)
    lines = stripped.splitlines()
    _visit(tree, lines, len(lines), False)
    spans.sort()
    return _blank_nested_registered(spans, nested_registered, lines)


def enclosing_function_span(
    text: str,
    anchor_line: int,
    *,
    functions: list[tuple[int, str]] | None = None,
    filename: str | Path = "<unknown>",
) -> tuple[int, int] | None:
    """The 1-based, inclusive ``(start_line, end_line)`` of the function that encloses
    `anchor_line`, or ``None`` if no function encloses it (module-level code).

    Exists so a guard can search "does a mitigating check exist anywhere in the function this
    call lives in" instead of a fixed N-line look-back/look-ahead window around the call site —
    the systemic false-negative class it exists to close: a check written a few lines further from
    the anchor than a fixed window reaches, or inside a same-function nested helper (which
    `iter_functions` already inlines into the enclosing block's text), was invisible before.
    Returning a SPAN (not joined text) lets a directional caller — most of these guards require
    the check to sit *before* (or, for a decorator-gated signal, *after*) the anchor, since a
    check written on the wrong side of the dangerous call doesn't actually mitigate anything —
    slice only its own half, e.g. ``lines[start - 1 : anchor_line]`` for a look-back guard.
    `enclosing_function()` below is the bidirectional convenience wrapper for a caller that
    doesn't need directionality.

    When more than one function contains `anchor_line` (a nested closure and the route/factory
    enclosing it — `iter_functions(include_closures=True)` emits both), the INNERMOST span is
    returned: the outermost choice let a mitigation in one sibling function silence a genuinely
    unprotected sibling nested in the same factory (a `create_app()` route pair, a
    `register_tools(agent)` tool pair) — a silent false-negative regression, since the six
    same-function-contract guards this feeds (`zip_bomb.py`'s own docstring: "a check enforced in
    a DIFFERENT function ... is still not detected") never intended cross-sibling visibility in
    the first place. The innermost span is still every check actually written in the anchor's own
    function body, which is what "the function this check lives in" means for these guards.

    `iter_functions`'s own returned `lineno` is the `def` line, not the block's true first line
    (a decorator stack sits above it) — so the true start is recovered here by locating the
    `def` line's own text within the returned block, rather than assumed via `block.count("\\n")`
    line-count math, which would silently undercount by the decorator line count and risk
    treating a neighbouring construct as still in scope.

    `functions`, if given, is a precomputed ``iter_functions(text)`` result — pass it when calling
    this repeatedly over the same `text` (once per matched anchor line in a file) so the AST isn't
    re-parsed on every call; `iter_functions` itself re-runs a full `safe_ast_parse` +
    `strip_python_strings` per call, which measured ~900x slower over many-function files with no
    caching. Omit it for a one-off call; it is then computed here as before.

    Total like `iter_functions`: never raises, returns ``None`` on anything it can't place
    (out-of-range `anchor_line`, no enclosing function, unparseable input falls through to
    `iter_functions`'s own line-walker fallback).
    """
    lines = text.splitlines()
    if not (1 <= anchor_line <= len(lines)):
        return None
    best: tuple[int, int] | None = None
    for def_lineno, block in (
        functions if functions is not None else iter_functions(text, filename=filename)
    ):
        if not (1 <= def_lineno <= len(lines)):
            continue
        block_lines = block.split("\n")
        def_line_text = lines[def_lineno - 1]
        try:
            idx = block_lines.index(def_line_text)
        except ValueError:
            idx = 0  # no decorator stack (or an unmatched def line) — block starts at def_lineno
        start = def_lineno - idx
        end = start + len(block_lines) - 1
        if start <= anchor_line <= end and (best is None or (end - start) < (best[1] - best[0])):
            best = (start, end)
    return best


def enclosing_function(
    text: str, anchor_line: int, *, filename: str | Path = "<unknown>"
) -> str | None:
    """The full, bidirectional text (decorator stack through body, string content blanked — see
    `iter_functions`) of the function enclosing `anchor_line`, or ``None`` if none does.

    A thin convenience wrapper over `enclosing_function_span()` for a caller that wants the
    whole block, not a directional half — see that function for the span/decorator-offset
    rationale. Most the guard ports want the directional span instead, since a check on the
    wrong side of the dangerous call doesn't mitigate it.
    """
    span = enclosing_function_span(text, anchor_line, filename=filename)
    if span is None:
        return None
    start, end = span
    return "\n".join(strip_python_strings(text, filename=filename).splitlines()[start - 1 : end])


# --- Cross-file FastAPI router-level auth resolution ------------------------------------------
# Shared by the FastAPI route-authorization guards (`auth-dependency-not-applied`,
# `unauthenticated-file-download`, `privileged-field-assignment`, `websocket-no-auth`). Each flags
# the ABSENCE of a per-route auth signal, but auth can be applied at the ROUTER level — either
# constructed (`APIRouter(dependencies=[Depends(...)])`), or included with it
# (`app.include_router(router, dependencies=[Depends(...)])`), which the common multi-file layout
# does in `main.py` for a bare `router = APIRouter()` sitting in `routes/<module>.py`. Resolving
# that (same-file AND cross-file) is what stops every such route from being a false positive.
# Extracted from `auth_dependency_not_applied` (PR #464) so the sibling guards resolve it identically.

# A list-variable assignment `<name> [: anno] = [` — the opening bracket of a dependency list bound
# to a name, referenced later as `dependencies=<name>`. The list body is balance-scanned for an auth
# call (with the caller's `auth_call` strictness), NOT matched inline, so the same variable is judged
# by the same rule as an inline `dependencies=[...]` list.
_LIST_VAR_ASSIGN = re.compile(
    r"^[ \t]*(?P<name>\w+)(?:\s*:[^=\n]+)?\s*=\s*(?P<bracket>\[)",
    re.MULTILINE,
)

# The `dependencies=<deps>` tail shared by construction + inclusion. `<deps>` is captured as either
# the OPENING `[` of an inline list (its contents are balance-scanned in `_deps_carry_auth`, so a
# nested bracket before the auth call does not truncate the search) or a bare identifier resolved
# against the list-variable set.
_DEPS_TAIL = r"[^)]*?dependencies\s*=\s*(?P<deps>\[|\w+)"

# A router constructed with a router-level dependencies= kwarg — every route on that router is
# authenticated without its own Depends(...). The `(?<![\w.])` anchor keeps the leading `\w+` from
# re-attempting inside a long word run (avoids O(n^2) backtracking on a pathological source line).
_ROUTER_CONSTRUCT_DEPS = re.compile(
    r"(?<![\w.])(?P<var>\w+)\s*=\s*(?:APIRouter|FastAPI)\s*\(" + _DEPS_TAIL,
    re.DOTALL,
)

# `X.include_router(<ref>, ..., dependencies=<deps>)` — FastAPI's other idiomatic router-level auth:
# the deps apply to every route on the *included* router. `<ref>` is a bare router var (same-file
# inclusion) or a `module.router` attribute (cross-file: the module — the segment before `.router`
# — maps to the route file by stem).
# The router argument may be passed by KEYWORD (`include_router(router=admin_router, ...)`) and the
# keywords may appear in ANY order (`include_router(prefix="/x", router=r)`) — both are ordinary Python.
#
# This is resolved by parsing the argument list, NOT by a cleverer regex. The regex approach failed
# twice: first it captured the keyword NAME as the ref (so a router called `router`, the most common
# name for one, was recorded as authed by a mount that authed something else), and the lookahead fix
# for that made any call whose first argument is some other keyword INVISIBLE. That second failure was
# the worse one: an invisible bare mount cannot flip `mounts[key]` to False, so the dual-mount defense
# silently stopped firing and a CRITICAL privilege-escalation route reported zero findings (#473
# agentic gate). "Recording no ref" is only conservative in isolation; in composition it IS a
# suppression, because the dual-mount check has to SEE the bare mount.
_INCLUDE_CALL = re.compile(r"\.include_router\s*\(")
# A bare positional ref (`admin.router`) or an explicit `router=` keyword. Anything else is a kwarg
# we do not care about (`prefix=`, `tags=`, `dependencies=`).
_REF_ARG = re.compile(r"^\s*(?:router\s*=\s*)?(?P<ref>[\w.]+)\s*$")
_KWARG_ARG = re.compile(r"^\s*(?P<name>\w+)\s*=")


# === helpers: FastAPI routes & cross-file auth ==============================================================
def include_router_ref(text: str, call_start: int) -> str | None:
    """The router reference of the `.include_router(` call whose match starts at `call_start`.

    Order-independent: takes the first bare positional argument, else an explicit `router=` keyword,
    whichever the call actually uses. Returns None if the parens are unbalanced or no ref is present.
    Total: never raises."""
    open_idx = text.find("(", call_start)
    if open_idx == -1:
        return None
    args = split_call_args(text, open_idx, python=True)
    if not args:
        return None
    for arg in args:
        m = _REF_ARG.match(arg)
        if m:
            return m.group("ref")          # bare positional, or `router=<ref>`
        k = _KWARG_ARG.match(arg)
        if k and k.group("name").lower() == "router":
            inner = _REF_ARG.match(arg.split("=", 1)[1])
            if inner:
                return inner.group("ref")
    return None


def _include_router_refs(text: str) -> list[tuple[int, str]]:
    """Every `(match_start, ref)` for the `.include_router(` calls in `text`, in source order."""
    out: list[tuple[int, str]] = []
    for m in _INCLUDE_CALL.finditer(text):
        ref = include_router_ref(text, m.start())
        if ref is not None:
            out.append((m.start(), ref))
    return out


_INCLUDE_ROUTER_DEPS = re.compile(
    _INCLUDE_CALL.pattern + _DEPS_TAIL,
    re.DOTALL,
)

# What counts as an "auth call" inside a router-level `dependencies=[...]` list — the caller picks
# the strictness so the router-level path mirrors the guard's own function-level policy:
#   ANY   — any `Depends(...)`/`Security(...)` call: a `Depends(...)` is ASSUMED to be auth,
#           whatever it wraps. NO GUARD USES THIS TODAY — the NAMED tightening moved the last two
#           (`auth-dependency-not-applied`, `websocket-no-auth`) onto NAMED, because "their
#           function-level checks are equally loose anyway" stopped being a justification once
#           those checks went router-level and one `Depends(RateLimiter(...))` could silence
#           every route in a file. Retained as the resolvers' default (and for a future guard
#           that genuinely wants presence-only), but a NEW caller should reach for NAMED first
#           and say why if it does not.
#   NAMED — a `Security(...)` (auth-by-construction) OR a `Depends(<auth-named callable>)` (via the
#           shared `AUTH_DEP_SIGNAL`). Matches `privileged-field-assignment` /
#           `unauthenticated-file-download` (issue #307) and, since the NAMED tightening,
#           `auth-dependency-not-applied` / `websocket-no-auth`. These deliberately do NOT treat a
#           bare `Depends(get_db)` as auth; using ANY reopens that hole at the router level. The
#           accepted residual cost is on `AUTH_DEPENDS_SIGNAL` above: auth behind a non-auth-named
#           wrapper is not recognized.
#   PRIV  — a dependency that checks the caller's PRIVILEGE, not merely their identity:
#           `require_admin`, `get_current_admin`, `verify_role`, `check_permissions`,
#           `Security(..., scopes=[...])`. `privileged-field-assignment` uses this: that guard is
#           about privilege ESCALATION, so a router-level `Depends(get_current_user)` proves only
#           that the caller is logged in — exactly the reasoning that kept `bola` out of the
#           router-level work — and must not silence a CRITICAL `user.role = body.role` write
#           (#473 review §2). A bare `Security(...)` with no scopes is authentication too, so it
#           counts here only with a `scopes=` argument.
AUTH_CALL_ANY = re.compile(r"(?:Depends|Security)\s*\(")

# FastAPI's own built-in security-scheme classes (`fastapi.security`), plus `JWTBearer` — the
# conventional name of the custom `HTTPBearer` subclass shipped in FastAPI's own JWT-auth
# tutorials and this project's flagship reference app. None of these carries an `_AUTH_NAME` stem
# (`HTTPBearer`/`JWTBearer` have no `auth`/`token`/etc. substring), so `Depends(HTTPBearer())` read
# as unauthenticated — confirmed via `piv-review-pr` on 2 separate guards.
# A closed, explicit class-name allowlist rather than widening the stem vocabulary: stem widening
# already reopened issue #345's over-suppression once (an ordinary `token`/`role`/`user` mention
# reading as auth) and a security-scheme CLASS NAME is a precise, unambiguous signal that carries
# no such risk.
_SECURITY_SCHEME_CLASSES = (
    r"HTTPBasic|HTTPBearer|HTTPDigest|JWTBearer|"
    r"OAuth2PasswordBearer|OAuth2AuthorizationCodeBearer|OAuth2|"
    r"APIKeyCookie|APIKeyHeader|APIKeyQuery|OpenIdConnect"
)
# `auto_error=False` (or `None`/`0`) is FastAPI's own idiom for "this scheme does not enforce" —
# the dependency returns `None` instead of raising 401/403, so the route body still runs
# unauthenticated. A security-scheme class instantiated with that flag is NOT an auth signal
# (fix-round review, Critical 2 — `grep -rn auto_error tests/ agentsec/ wiki/` was zero
# hits before this fix; verified 15/16 shapes both directions, the one pre-existing miss —
# `Depends(OAuth2PasswordBearer(..., auto_error=False))` — already matches independently via the
# `oauth` stem in `AUTH_DEP_SIGNAL`, unrelated to this guard).
#
# (Dean, review): the first version of this exclusion was a bounded negative lookahead
# — `{0,200}` chars, a character class excluding `)` and `\n` — reasoned as a trade against
# `AUTH_CALL_NAMED`'s contract being a plain regex STRING (concatenated raw into other compiled
# patterns, e.g. `unauthenticated_file_download.py`'s `_AUTH_IN_SIG_TAIL`), which seemed to rule
# out a `split_call_args`-style two-step check. Dean tested 4 character-class variants trying to
# widen the window; the 2 that closed the multi-line/nested-paren bypasses each introduced a new
# false positive — a bounded lookahead structurally cannot know where the constructor call ends,
# no matter how the class is tuned. His own audit also found the "concatenated raw in several
# places" premise didn't hold: `AUTH_CALL_NAMED.pattern` is spliced as a string in exactly ONE
# place codebase-wide.
#
# The fix moves the check OUT of the compiled pattern entirely: `blank_disabled_security_schemes`
# (below) finds every `<SecurityScheme>(...)` constructor call via `matching_close_paren` — real
# balanced-paren scanning, multi-line and nested-paren tolerant by construction, not a
# fixed-width guess — and blanks out (to whitespace, preserving every line/column offset) any
# whose OWN top-level arguments set a disabling `auto_error`. Every AUTH_CALL_NAMED-based consumer
# calls this ONCE on a file's text right after reading it (see `websocket_no_auth.py`,
# `auth_dependency_not_applied.py`, `unauthenticated_file_download.py`), so by the time either
# `_SECURITY_SCHEME_DEPENDS_CALL` (inline `Depends(HTTPBearer(...))`) or `_TOP_LEVEL_ASSIGN`
# (variable-bound `bearer_scheme = HTTPBearer(...)`) runs, a disabled instance has already
# disappeared from the text — one mechanism closes BOTH shapes, since both are just
# `<SecurityScheme>(...)` constructor calls to the same blanking pass. Neither pattern below
# needs its own auto_error exclusion anymore; `AUTH_CALL_NAMED.pattern`'s string-concatenation
# contract is unaffected, since the exclusion no longer lives inside the pattern at all.
#
# #764: the flag is read from the call's top-level ARGUMENTS on a code-only view, never searched
# for in its raw span. A raw-span search blanked an ENFORCING scheme whenever the text
# `auto_error=False` sat inside it as a comment (`# do NOT set auto_error=False here`), inside a
# string (`description="set auto_error=False for optional auth"`) or as a nested call's own kwarg
# (`scheme_name=describe(auto_error=False)`), so all three consumers fired on authenticated
# routes. Splitting the RAW text into arguments is not the fix either: a comment line ahead of the
# kwarg (`HTTPBearer(\n    # optional\n    auto_error=False,\n)`) lands in the same argument, an
# argument-anchored match then misses a scheme that really is disabled, and its route goes silent.
# And `matching_close_paren` has no comment state, so a quote in a comment (`# don't ...`) left the
# span unresolvable on raw text (as a triple-quoted description holding its own quote character did
# until #613), which blanked an enforcing scheme through the token-only arm below. Blanking comments
# and string contents FIRST (`_python_code_chars`, the router views' index-aligned core) fixes all of these at
# once. `_AUTO_ERROR_ARG` is anchored at the start of an argument but is a prefix match, not a full
# one, so `auto_error=False if DEV else True` still counts as disabled, exactly as it did before.
_AUTO_ERROR_KV = re.compile(r"\bauto_error\s*=\s*(?:False|None|0)\b")
_AUTO_ERROR_ARG = re.compile(r"\s*auto_error\s*=\s*(?:False|None|0)\b")
_SECURITY_SCHEME_CTOR = re.compile(r"\b(?:" + _SECURITY_SCHEME_CLASSES + r")\s*\(")


def blank_disabled_security_schemes(text: str) -> str:
    """`text` with every `<SecurityScheme>(...)` constructor call blanked to whitespace (line/
    column offsets preserved — same strategy as `router_resolver_view`/`strip_python_strings`)
    when that call's OWN argument span sets a disabling `auto_error` — covers both the inline
    `Depends(HTTPBearer(...))` shape and the variable-bound `bearer_scheme = HTTPBearer(...)`
    shape identically, since in both cases the disabling call disappears before any
    `AUTH_CALL_NAMED`-based search runs. Callers apply this ONCE, immediately after reading a
    file's text, before it reaches any auth-signal check (see the block comment
    above `_AUTO_ERROR_KV` for why a compiled-pattern-only fix could not close this).

    A constructor that is CODE is judged on `_python_code_chars` (comments and string contents
    blanked, index-aligned with `text`): its span is resolved there, and it is disabled only when
    one of its own top-level arguments starts `auto_error=False|None|0` (#764). With no token
    stream, or for a constructor that is itself inside a string or comment, the raw-span search
    that predates #764 runs unchanged: without trustworthy offsets, over-blanking is the safe side."""
    out = list(text)
    view: str | None = None
    view_built = False
    for m in _SECURITY_SCHEME_CTOR.finditer(text):
        open_paren = m.end() - 1
        if not view_built:
            # Built lazily, so a file with no security-scheme constructor never tokenizes here.
            view = _python_code_chars(text, strip_python_strings(text), keep_strings=False)
            view_built = True
        if view is not None and view[m.start()] == text[m.start()] and view[open_paren] == "(":
            args = split_call_args(view, open_paren, python=True)
            close = matching_close_paren(view, open_paren, python=True) if args is not None else None
            disabled = args is not None and any(_AUTO_ERROR_ARG.match(a) for a in args)
        else:
            close = matching_close_paren(text, open_paren, python=True)
            disabled = close is not None and bool(_AUTO_ERROR_KV.search(text[m.start() : close + 1]))
        # An UNRESOLVABLE span means we cannot tell where this call ends, and the two wrong
        # answers are not symmetric.
        #
        # Falling back to `len(text)` (the original) blanked from here to EOF on any later
        # `auto_error` hit: subsequent routes, their auth signals and any inline pragma all
        # vanished from the guard's view, with nothing disclosed, so a file the guard could no
        # longer see reported as a clean run.
        #
        # Simply skipping is no better, and is worse than it looks: nothing downstream re-examines
        # the call, and neither `_TOP_LEVEL_ASSIGN` nor `security_scheme_var_names` knows anything
        # about `auto_error`. Leaving the text intact is therefore not "no opinion", it positively
        # asserts the scheme enforces, so a disabled one reads as auth and its route goes silent.
        # That is the exact false negative this pass exists to prevent (#761 re-review).
        #
        # So blank the constructor TOKEN only (`<Class>(`), never a guessed span. The ambiguous
        # scheme stops counting as an auth signal, which surfaces its routes for review, and
        # nothing past the token is touched, so no later route or pragma can be swallowed. The
        # cost is a false positive when the unresolvable scheme was in fact enforcing, and that
        # is the direction this guard family has chosen in writing: "a false negative is worse
        # than the residual false positive ... which the pragma covers" (`_AUTH_DECORATOR`, this
        # guard's own note), and "over-firing is the safe direction" (the design docs).
        #
        # Reachability: on the code view, string contents and comments are already blanked, so
        # only genuinely unbalanced parens get here. On the raw path (no token stream, i.e. a file
        # the tokenizer rejects), the walk runs in Python mode, so a triple-quoted argument is one
        # span (#613: before that, an apostrophe inside a triple-quoted literal could resync on a later quote
        # and return a confidently WRONG index, which this arm cannot catch). A quote inside a
        # COMMENT still desyncs the raw walk, since it has no `#` state: that can return None
        # (handled here) or, on a later resync, a wrong index. It is the residual this path keeps.
        if close is None:
            for i in range(m.start(), m.end()):
                if out[i] != "\n":
                    out[i] = " "
            continue
        if disabled:
            for i in range(m.start(), close + 1):
                if out[i] != "\n":
                    out[i] = " "
    return "".join(out)


# `Depends(HTTPBearer())` — the class instantiated INLINE at the Depends() call site. Static and
# file-independent, so it is baked directly into `AUTH_CALL_NAMED` below. the fix-round
# review, Medium: this reaches every guard whose PER-ROUTE signal is actually BUILT FROM
# `AUTH_CALL_NAMED` (`unauthenticated_file_download.py`, after that round's fix) — it does NOT
# reach a guard that intentionally uses a narrower or different pattern for its per-route check.
# `privileged_field_assignment.py` is a deliberate case, not an oversight: it uses the stricter
# `AUTH_CALL_PRIVILEGED` because a bare authentication scheme (proves "logged in") is not evidence
# of the PRIVILEGE check that guard requires (#473 review) — extending it here would UNDER-detect
# exactly the class of bug it targets, so it correctly stays out of scope for this allowlist.
_SECURITY_SCHEME_DEPENDS_CALL = r"\bDepends\s*\(\s*(?:" + _SECURITY_SCHEME_CLASSES + r")\s*\("

# Any top-level (column-zero) simple/annotated assignment — `name = ...` or `name: Type = ...`.
# Column-zero, not `[ \t]*`-padded: a genuinely nested/indented binding (inside a function body,
# a conditional) is function-local, not a module-level name a `Depends(name)` anywhere else in
# the file could legitimately refer to (fix-round review, Critical 1 shape (c) — the
# padded anchor let a purely local `bearer_scheme = HTTPBearer()` inside an unrelated helper leak
# into the whole file's alias set). `is_scheme` is OPTIONAL: every top-level assignment matches
# (so reassignment to something else is visible too, not just scheme assignments), and the group
# only fills in when the RHS itself starts with a security-scheme class instantiation. Matches are
# walked in source order below, so the LAST assignment to a name wins (Critical 1 shape (b) — a
# `bearer_scheme = HTTPBearer()` later REBOUND to `bearer_scheme = get_db()` before use must not
# still read as an auth scheme).
_TOP_LEVEL_ASSIGN = re.compile(
    r"^(?P<name>[A-Za-z_]\w*)[ \t]*(?::[^=\n]+)?=[ \t]*"
    r"(?P<is_scheme>(?:[\w.]*\.)?(?:" + _SECURITY_SCHEME_CLASSES + r")\s*\()?",
    re.MULTILINE | re.IGNORECASE,
)


def security_scheme_var_names(text: str) -> frozenset[str]:
    """Names whose LAST top-level assignment in `text` instantiates a FastAPI/known
    security-scheme class (`bearer_scheme = HTTPBearer()`), so a caller can recognize
    `Depends(bearer_scheme)` as an auth signal even though the class name itself isn't at the
    `Depends()` call site. Exact-name matched against a closed class list (see
    `_SECURITY_SCHEME_CLASSES`) — not a stem widening. Last-assignment-wins and column-zero-only:
    see `_TOP_LEVEL_ASSIGN`'s own docstring for why (fix-round review, Critical 1)."""
    last_is_scheme: dict[str, bool] = {}
    for m in _TOP_LEVEL_ASSIGN.finditer(text):
        last_is_scheme[m.group("name")] = m.group("is_scheme") is not None
    return frozenset(name for name, is_scheme in last_is_scheme.items() if is_scheme)


def auth_call_named_with_aliases(*texts: str) -> re.Pattern[str]:
    """`AUTH_CALL_NAMED`, extended with the security-scheme variable names bound in `texts`, so
    `Depends(bearer_scheme)` is recognized the same way `Depends(HTTPBearer())` already is via
    `AUTH_CALL_NAMED` alone. Falls back to the shared `AUTH_CALL_NAMED` singleton (no per-run
    compile) when nothing in `texts` binds one, which is the overwhelming common case.

    **Callers scope `texts` to whatever files a name reference in should be allowed to resolve
    against — usually ONE file's own text, not every file in a run.** Passing the whole run's
    file set here reopens the fix-round review Critical 1 shape (a): an unrelated file's
    OWN local `bearer_scheme = HTTPBearer()` would silently authorize `Depends(bearer_scheme)`
    anywhere else in the tree, including a genuinely unauthenticated route in a different file
    that merely reuses the same, extremely common, FastAPI-tutorial variable name."""
    names: set[str] = set()
    for text in texts:
        names |= security_scheme_var_names(text)
    if not names:
        return AUTH_CALL_NAMED
    alt = "|".join(re.escape(n) for n in sorted(names))
    return re.compile(
        AUTH_CALL_NAMED.pattern + r"|\bDepends\s*\(\s*(?:" + alt + r")\s*\)",
        re.IGNORECASE,
    )


AUTH_CALL_NAMED = re.compile(
    r"\bSecurity\s*\(|" + _SECURITY_SCHEME_DEPENDS_CALL + r"|" + AUTH_DEP_SIGNAL, re.IGNORECASE
)
# Privilege-check identifier stems, boundaried through the SHARED `boundaried_stems` helper —
# the one that exists because `scope` is a substring of `telescope` and `role` of `payroll`
# (issue #307/#345). Writing the alternation raw made `Depends(get_telescope_status)` read as
# a privilege check, so a genuine unauthenticated `user.role = body.role` returned ZERO
# findings — the same class of bug, in the fix for it (#473 second-pass review).
# Prefix stems (long, unambiguous, derivations continue lowercase) vs segment stems (short,
# can be a substring of an ordinary word, so boundaried on both sides + optional plural).
_PRIV_NAME = boundaried_stems(r"role|scope|staff", r"admin|superuser|permission|privileg")
AUTH_CALL_PRIVILEGED = re.compile(
    r"\bSecurity\s*\([^)]*\bscopes\s*="
    r"|\bDepends\s*\(\s*[\w.]*" + _PRIV_NAME
    # Mirrors `AUTH_DEP_ALIAS`: the `\w*` padding is what lets a compound alias like
    # `AdminReadDep` match, since the stems are now boundaried.
    + r"|\b\w*" + _PRIV_NAME + r"\w*Dep(?:ends)?\b",
    re.IGNORECASE,
)

# A RATE-LIMIT dependency, for the two rate-limit-absence guards (#472). Nothing in the router
# resolvers below is auth-specific: `auth_call` is a generic "does this dependency list carry X"
# predicate, so this rides `cross_file_authed_routers` / `same_file_authed_routers` unchanged and
# inherits their dual-mount, conditional-mount and stem-collision rules. Matches fastapi-limiter's
# `Depends(RateLimiter(times=5, seconds=60))` and a project's own `Depends(rate_limit)` /
# `Depends(deps.check_rate_limit)` / `Depends(rate_limiter(10, 60))`. The stem is boundaried the
# `_SEG_BEFORE` way, plus an UpperCamel `Rate` (`RedisRateLimiter`), so `Depends(moderate_limit)`
# does not read as one. It must be followed by a call, a `,` or the closing `)`, so a non-limiter
# reached through a limiter-named module (`Depends(rate_limits.get_db)`) is not credited.
RATE_LIMIT_CALL = re.compile(
    r"\bDepends\s*\(\s*[\w.]*(?:" + _SEG_BEFORE + r"rate|(?-i:Rate))_?limit\w*\s*[,()]",
    re.IGNORECASE,
)


def _deps_carry_auth(
    text: str, deps_start: int, deps_token: str, auth_vars: set[str], auth_call: re.Pattern[str]
) -> bool:
    """Does a `dependencies=<deps>` value carry a real auth dependency? For an inline list
    (`deps_token == "["`), balance-scan from the opening bracket to its match and look for an
    `auth_call` match anywhere inside — nested brackets are tolerated, so a list like
    `[limiter(times=[5]), Depends(get_user)]` is not truncated at the first `]`. For a bare
    identifier, resolve it against the known auth-dep list variables (already filtered by the same
    `auth_call`). The scan is O(n) with no backtracking (ReDoS-free)."""
    if deps_token != "[":  # nosec B105 (a parser token, not a password)
        return deps_token in auth_vars
    depth = 0
    for i in range(deps_start, len(text)):
        c = text[i]
        if c == "[":
            depth += 1
        elif c == "]":
            depth -= 1
            if depth == 0:
                return bool(auth_call.search(text[deps_start : i + 1]))
    return bool(auth_call.search(text[deps_start:]))  # unterminated list: scan the tail


def _auth_dep_list_vars(text: str, auth_call: re.Pattern[str]) -> set[str]:
    """Names of list variables bound to a dependency list that carries an `auth_call` match, e.g.
    `_admin = [Depends(get_current_admin)]` referenced later as `dependencies=_admin`. The list body
    is balance-scanned (nested brackets tolerated) with the caller's strictness, so a variable is
    judged the same way as an inline list."""
    out: set[str] = set()
    for m in _LIST_VAR_ASSIGN.finditer(text):
        if _deps_carry_auth(text, m.start("bracket"), "[", set(), auth_call):
            out.add(m.group("name"))
    return out


# #859 / #872: a BARE auth-factory call sitting inside a route's own `dependencies=[...]`. The
# idiomatic FastAPI "returns nothing" guard is attached un-wrapped:
#     @router.post("/x", dependencies=[requires_authenticated()])
#     @router.post("/y", dependencies=[_auth.requires_system_write_role()])
# It is neither `Depends(...)`/`Security(...)`-wrapped nor a `*Dep`/`*Depends` alias, so no
# `AUTH_CALL_NAMED`-based signal recognizes it and the (correctly-authed) route over-fired (issue
# #859: 43 of 44 flagged routes on the reporting repo were this shape, in
# `auth-dependency-not-applied`; #872: the same false positive in its three per-route siblings).
#
# The two matchers below are read ONLY through `route_deps_carry_auth`, which scopes them to the
# decorator's own list CONTENTS, never the whole route block, so a bare `get_db()`/`RateLimiter(...)`
# still fires (stays closed). Each guard opts in at its own call site with its own
# strictness. Never splice one into a block-wide signal or into `AUTH_CALL_NAMED` /
# `AUTH_CALL_PRIVILEGED`: unscoped, a bare match reads `get_db()` anywhere in the block as auth, in
# every consumer of those shared matchers at once.
#
# `PER_ROUTE_AUTH_FACTORY` answers "is anyone authenticated?". A CURATED stem set, deliberately NOT
# the full `_AUTH_NAME`: only stems that name an access-control GUARD unambiguously — `require`(s),
# `role`, `scope`, `auth`, `authenticat*`, `authoriz*`, `permission*`. The broad `_AUTH_NAME`
# members (`user`/`token`/`current`/`login`/`verify`) are left out on purpose: a NON-guard
# dependency can carry them (`track_login_attempt()`, `Depends(get_current_timestamp)`), and
# silencing one of those would be a false NEGATIVE — the unsafe direction. Boundaried through the
# SHARED `boundaried_stems`, so a stem can't bleed into an ordinary word (`scope`⊄`telescope`,
# `require`⊄`required`, `auth`⊄`author`, `role`⊄`payroll` — issue #307). A returns-nothing guard
# named OUTSIDE this curated set (e.g. `verify_jwt()`) still over-fires — the safe direction,
# covered by the pragma / a `Depends()` wrap.
PER_ROUTE_AUTH_FACTORY = re.compile(
    boundaried_stems(r"require|role|scope|auth", r"authenticat|authoriz|permission") + r"\w*\s*\(",
    re.IGNORECASE,
)
# `PER_ROUTE_PRIV_FACTORY` answers "is the caller privileged?" (#872, `privileged-field-assignment`).
# A `dependencies=[...]` entry's return value is discarded, so the handler never receives the caller
# and cannot check privilege itself: the slot is semantically the ROUTER level, where that guard
# already demands a privilege-named dependency. So an authentication-only factory
# (`requires_authenticated()`) does not match here: logged-in is not privileged.
#
# The `_PRIV_NAME` vocabulary alone is NOT enough for a bare call (#1041 round-1 review, R1-M1):
# every privilege stem is a noun, so `log_admin_access()`, `audit_role_change()` and
# `get_scope_filter()` carry one without checking anything, and silencing them hides a CRITICAL
# escalation, the unsafe direction. So, as the curated `PER_ROUTE_AUTH_FACTORY` leaves out the
# ambiguous auth stems, the identifier must also be GUARD-shaped: it opens (after any leading `_`)
# with a whole guard-verb segment (`requires_admin`, `has_permission`, `is_staff`), or it ends in a
# `_required` / `_only` segment (`admin_required`, `superuser_only`). The verb must start the
# identifier, so `audit_has_role()` is not a check; `(?<!\w)` lets a dotted module prefix
# (`_auth.requires_admin()`) through. This is stricter than the wrapped form `AUTH_CALL_PRIVILEGED`
# accepts (`Depends(get_role_cache)` still reads as a check there), the #859 precedent for the
# bare-call slot. A privilege guard named outside both shapes (`admin_gate()`) still over-fires,
# the safe direction, covered by the pragma or a `Depends()` wrap.
#
# Linear by construction: `(?<!\w)` admits only an identifier's first character, and the ATOMIC
# `(?>\w*?<stem>)` commits to the FIRST privilege stem. That loses no match, because the tail from
# any later stem reaches the same identifier end; without it a long stem-dense identifier backtracks
# quadratically through every stem.
_PRIV_GUARD_VERB = (
    r"(?:requires?|ensures?|checks?|verify|verifies|asserts?|enforces?|has|is|must"
    r"|allow(?:s|ed)?|restrict(?:s|ed)?|only)"
)
PER_ROUTE_PRIV_FACTORY = re.compile(
    r"(?<!\w)_*" + _PRIV_GUARD_VERB + _SEG_AFTER + r"(?>\w*?" + _PRIV_NAME + r")\w*+\s*\("
    + r"|(?<!\w)(?>\w*?" + _PRIV_NAME + r")\w*?_(?:required|only)\s*\(",
    re.IGNORECASE,
)
# The opening `[` of a route decorator's own inline `dependencies=[...]` list. Located inside the
# decorator's balanced paren span (see `route_deps_carry_auth`), not with a `[^)]*` window, so a
# nested-call `)` appearing before the kwarg cannot hide it (the failure mode #473 removed the old
# local regexes for).
_PER_ROUTE_DEPS_LIST = re.compile(r"dependencies\s*=\s*(?P<bracket>\[)")


def blank_line_comments(text: str) -> str:
    """``text`` with every real ``#`` line-comment blanked to spaces, LENGTH- and offset-preserving,
    so an index into the result still points at the same character as in ``text``.

    Reuses the string-aware `strip_python_line_comment` (a ``#`` inside a single-line string is not a
    comment) and re-pads each line to its original width (that helper TRUNCATES, which would shift
    every later offset). Splits on ``\\n`` only, so no character is added or dropped whatever other
    line-boundary characters the text carries. Triple-quoted strings are out of scope: a caller
    working on an `iter_functions` block already has them blanked. Needed so a DEAD (commented-out)
    `dependencies=[requires_authenticated()]` sitting above a route's real `dependencies=[get_db()]`
    cannot fake protection — the per-route counterpart of the #532 `router_resolver_view` fix for the
    router-level resolvers, which comment-strip for the same reason. Single-line strings are
    intentionally left intact; unlike the router-level resolvers, which read `router_code_view` since
    #538, the per-route scan still carries that residual (see each guard's Known bypasses)."""
    out: list[str] = []
    for ln in text.split("\n"):
        stripped = strip_python_line_comment(ln)  # truncates at the first real `#`
        out.append(stripped + " " * (len(ln) - len(stripped)))  # re-pad to the original width
    return "\n".join(out)


def route_deps_carry_auth(view: str, open_idx: int, bare_call: re.Pattern[str]) -> bool:
    """True when the route decorator whose ``(`` is at ``open_idx`` lists a ``bare_call`` match in
    its own inline `dependencies=[...]` (#859 sub-fix A, shared with the per-route siblings in #872).

    ``view`` must already be comment-blanked by `blank_line_comments` (length-preserving, so an
    offset taken from the raw text is valid in it). The caller blanks, not this helper, so a
    whole-file caller blanks once rather than once per decorator. Blanking means a commented-out
    `dependencies=[...]` cannot fake protection and a stray paren in a comment cannot skew
    `matching_close_paren` (#532 dead-code doctrine, per-route).

    The `dependencies=` search is bounded to the decorator's balanced span (`matching_close_paren`,
    quote/escape-aware), so a `dependencies=[` in the body or in an unrelated decorator is never
    picked up, and, unlike a bounded `[^)]*` lookahead, a nested-call `)` before the kwarg does not
    hide it. The list body is then bracket-balance-scanned by `_deps_carry_auth`, so a multi-element
    list (`[get_db(), requires_auth()]`) is searched in full. That scan is clipped to the decorator
    span as well, so an unterminated `[` can neither run on into the handler body (where a body call
    would fake protection) nor, for a whole-file caller, to end of file once per decorator. Note
    `matching_close_paren` itself runs to the end of ``view`` on an unbalanced ``(``: a caller that
    does not hold an `iter_functions` block passes a per-decorator window (see `websocket_no_auth.py`).

    ``bare_call`` is the caller's strictness: `PER_ROUTE_AUTH_FACTORY`, `PER_ROUTE_PRIV_FACTORY`,
    or a union with the wrapped forms for a caller that has no block-wide signal of its own. Only the
    inline-list (`[`) form is resolved; a per-route `dependencies=<var>` is out of scope and still
    fires (the safe direction). Total: returns False on an unbalanced decorator, a missing list, or
    an ``open_idx`` that does not point at a ``(`` in ``view``."""
    if not 0 <= open_idx < len(view) or view[open_idx] != "(":
        return False
    close_idx = matching_close_paren(view, open_idx, python=True)
    if close_idx is None:
        return False
    dm = _PER_ROUTE_DEPS_LIST.search(view, open_idx, close_idx + 1)
    if dm is None:
        return False
    return _deps_carry_auth(view[dm.start("bracket") : close_idx + 1], 0, "[", set(), bare_call)


def _router_view_uncached(text: str, *, keep_strings: bool, filename: str | Path) -> str:
    """The real work behind `router_resolver_view` / `router_code_view` — see their docstrings.

    Built in length-preserving passes over the ORIGINAL text's coordinates, then the same
    `splitlines()` normalisation the view has always had (so its rows, and every line number a
    consumer computes from it, are unchanged): `strip_python_strings` blanks triple-quoted content;
    every COMMENT token is blanked; and, unless `keep_strings`, the TEXT of every literal is blanked
    too (`_python_blank_spans`: a literal's content, an f-string's minus its replacement fields,
    which are code). Line-boundary characters are never blanked, so both settings split into the
    same rows and stay offset-aligned with each other.

    Quotes and fields are kept, so the view still parses (`_conditional_lines` reads it with `ast`,
    and a view that stopped parsing would silently count a mount under an `if` as protection). A
    continuation backslash before a row break inside a literal is kept for the same reason; a row
    break inside a single-quoted f-string can otherwise only sit in a field, which is kept whole.

    Falls back to the pre-#538 per-line pass (`strip_python_line_comment`, never the YAML-flavoured
    `strip_hash_comments`, see `router_resolver_view`) when the token stream or the length-preserving
    AST blank is unavailable, because then no offset can be trusted. Total: never raises."""
    base = strip_python_strings(text, filename=filename)
    chars = _python_code_chars(text, base, keep_strings=keep_strings)
    if chars is None:
        return "\n".join(strip_python_line_comment(ln) for ln in base.splitlines())
    return "\n".join(chars.splitlines())


def _python_code_chars(text: str, base: str, *, keep_strings: bool) -> str | None:
    """The router views' blanking (see `_router_view_uncached`) BEFORE their `splitlines()`
    normalisation: exactly `len(text)` long and index-aligned with `text`, CRLF included, so a
    position found in it is the same position in `text`. `base` is
    `strip_python_strings(text, ...)`, passed in so the router views' per-line fallback can reuse
    it. None when the token stream or the length-preserving AST blank is unavailable, because then
    no offset can be trusted; callers keep their raw-text behaviour. `blank_disabled_security_schemes`
    reads a constructor's arguments from it (#764). Total: never raises."""
    spans = _python_blank_spans(text)
    if len(base) != len(text) or spans is None:
        return None
    comments, literal = spans
    chars = list(base)
    for s, e in comments:
        for i in range(s, e):
            if chars[i] not in _SPLITLINES_BREAKS:
                chars[i] = " "
    if not keep_strings:
        for s, e in literal:
            for i in range(s, e):
                c = chars[i]
                if c in _SPLITLINES_BREAKS or (
                    c == "\\" and text[i + 1 : i + 2] in _SPLITLINES_BREAKS
                ):
                    continue
                chars[i] = " "
    return "".join(chars)


def _router_view(text: str, *, keep_strings: bool, filename: str | Path) -> str:
    """`_router_view_uncached`, memoised while a `derived_state_run()` scope is active (#538). The
    key is `(text, keep_strings)`; `filename` is diagnostic only, as in `strip_python_strings`."""
    if _derived_depth == 0 or _MAX_DERIVED_ENTRIES <= 0:
        return _router_view_uncached(text, keep_strings=keep_strings, filename=filename)
    key = (text, keep_strings)
    hit = _router_view_cache.get(key)
    if hit is not None:
        return hit
    out = _router_view_uncached(text, keep_strings=keep_strings, filename=filename)
    if len(_router_view_cache) < _MAX_DERIVED_ENTRIES:
        _router_view_cache[key] = out
    return out


def router_resolver_view(text: str, *, filename: str | Path = "<unknown>") -> str:
    """`text` with `#` comments and triple-quoted strings blanked out; single-line strings kept.
    For the router readers that need a string VALUE (a router `prefix="/auth"`, an
    `@app.middleware("http")` marker); the auth resolvers themselves read `router_code_view`.

    The resolvers scan source with regexes, so a COMMENTED-OUT include
    (`# app.include_router(admin.router, dependencies=[Depends(require_admin)])`) or the same
    line quoted inside a module docstring/example read as a live auth mount and silenced every
    route on that router — a failure that presents as success (#473 review, HIGH 2/3). Blanking
    preserves rows, so the view stays line-for-line with the real source.

    Comments are located by the TOKENIZER (#538). The per-line quote-pairing masker this used
    before could not know a line begins at the close of a multi-line literal: on
    `\"\"\"  # restore the "admin" gate: widgets = APIRouter(dependencies=[...])` it paired the
    leftover delimiter quote with the quote inside the comment, hid the `#`, and the dead
    `dependencies=` minted the auth map (0 findings where the control has 2) and, spelled
    `include_router(router, prefix="/auth")`, a phantom prefix.

    When there is no token stream the old per-line pass is the fallback, and that pass MUST be
    `strip_python_line_comment`, not `strip_hash_comments`. The latter is the YAML/shell helper: it
    requires whitespace before a `#`, and its single-quote masking is deliberately not
    backslash-escape-aware — both wrong for Python, where `\\'` is a legal escape. Using it here
    broke BOTH consumers of this view, in opposite directions, from one root cause (#473 re-gate).
    Given `APIRouter(description='it\\'s legacy # internal', prefix="/admin")`:

      * the PREFIX map failed **OPEN** — the escaped quote closed the masker's idea of the string
        early, the `#` then truncated the line through the router's closing `)`, and the DOTALL
        `[^)]*` in `_ROUTER_PREFIX` bled into the NEXT router and stole its prefix. A genuinely
        unauthenticated `POST /admin/token` read as `/auth/token` and was exempted (1 -> 0).
      * the AUTH map failed **CLOSED** — a real `dependencies=[Depends(...)]` sitting after that
        kwarg was truncated away, so the router stopped counting as authed and every route on it
        over-fired (0 -> 1).
    """
    return _router_view(text, keep_strings=True, filename=filename)


def router_code_view(text: str, *, filename: str | Path = "<unknown>") -> str:
    """`router_resolver_view` with every literal's TEXT blanked too, so only code survives: quotes
    and f-string replacement fields (which are code) are kept, so the view still parses. What the
    router-auth resolvers match against (#538): a one-line
    `HINT = "router = APIRouter(dependencies=[Depends(require_admin)])"` used to mint the auth map
    for every route on `router`, because only triple-quoted strings were blanked and the identical
    text inside one WAS handled, which made the gap arbitrary rather than principled.

    Offset-aligned with `router_resolver_view` (same rows, same length per row), so a reader that
    needs a value matches STRUCTURE here, where a call quoted inside a string cannot match, and
    reads the value from `router_resolver_view` at the same span."""
    return _router_view(text, keep_strings=False, filename=filename)


# Any `X.include_router(<ref>, ...)` — with or without a `dependencies=` kwarg. Needed to see the
# BARE mounts, which `_INCLUDE_ROUTER_DEPS` (kwarg-required) can't match, and which are precisely
# the ones that leave a router's routes reachable without auth. Refs come from
# `_include_router_refs`, which parses the argument list and is therefore order-independent.


def _conditional_lines(text: str, *, filename: str | Path = "<unknown>") -> frozenset[int]:
    """Line numbers inside an `if`/`else` body — statements that are not guaranteed to run.

    A router mounted only under a condition (`if settings.ENABLE_AUTH:
    app.include_router(r, dependencies=[Depends(require_admin)])`) is not unconditional proof of
    auth: flip the setting and every route on `r` is exposed. Treating it as protective was
    fail-open (#473 review §2). Uses the AST so an `if` inside an app-factory function is located
    precisely (indentation alone can't tell a factory body from a conditional). Total: an
    unparseable file yields an empty set, which is the pre-existing (permissive) behavior — the
    conditional check is a refinement, not the safety property itself.

    Memoised by `text` inside a `derived_state_run()` scope (`_conditional_lines_cache`)."""
    if _derived_depth and _MAX_DERIVED_ENTRIES > 0:
        hit = _conditional_lines_cache.get(text)
        if hit is not None:
            if not hit:
                # Empty is also what a parse FAILURE yields. Ask the (memoised) parser again so a
                # second file with the same broken text is still recorded for #1001's disclosure.
                safe_ast_parse(text, filename=filename)
            return hit
    tree = safe_ast_parse(text, filename=filename)
    out: frozenset[int] = frozenset()
    if tree is not None:
        lines: set[int] = set()
        for node in ast.walk(tree):
            if not isinstance(node, ast.If):
                continue
            for stmt in (*node.body, *node.orelse):
                end = stmt.end_lineno or stmt.lineno
                lines.update(range(stmt.lineno, end + 1))
        out = frozenset(lines)
    if _derived_depth and len(_conditional_lines_cache) < _MAX_DERIVED_ENTRIES:
        _conditional_lines_cache[text] = out
    return out


def cross_file_authed_routers(
    files: list[tuple[Path, str]], *, auth_call: re.Pattern[str] = AUTH_CALL_ANY
) -> dict[str, set[str]]:
    """Pass-1 (repo-wide), PER ROUTER: `{module stem -> {router attribute names included with a
    real auth dependency}}`. `main.py` doing
    `include_router(admin.admin_router, dependencies=[Depends(require_admin)])` yields
    `{"admin": {"admin_router"}}`.

    Supersedes the STEM-level `cross_file_authed_stems` (removed). A stem-level answer means
    "some router in this module is authed", and callers used it as a whole-file bail — so in the
    standard public+admin layout (two routers in one module, one mounted with auth and one
    without), mounting the admin router silenced every route on its public sibling, including a
    CRITICAL privileged-field write (#473 review, HIGH 1). Callers merge the per-stem set into
    their same-file router set and keep matching per route decorator receiver.

    Three fail-open holes are closed here, all in the "protection must be UNCONDITIONAL and
    UNAMBIGUOUS" direction (#473 review §2):
      * **dual mount** — the same router mounted twice, once with auth and once without, leaves
        every route reachable unauthenticated through the bare mount. A router is protected only
        if EVERY mount of it carries auth, so one bare mount defeats the whole set.
      * **conditional mount** — an `include_router` inside an `if` (`if settings.ENABLE_AUTH:`)
        is not guaranteed to run, so it counts as an unauthed mount. Any mount, authed or not,
        that sits under a conditional is recorded as unauthed.
      * **stem collision** — the module key is a file STEM, so two product files named
        `admin.py` (say `routes/admin.py` and `v2/admin.py`) are indistinguishable and an authed
        mount of one would protect the other. A stem carried by more than one file in `files` is
        dropped entirely.

    `files` is `(path, already-read text)` pairs so callers read each file once. `auth_call`
    selects strictness (see `AUTH_CALL_NAMED` / `AUTH_CALL_PRIVILEGED`). Despite the name it is a
    generic dependency predicate: `rate_limit_wiring` passes `RATE_LIMIT_CALL` (#472). Bare-var includes are
    same-file and are NOT reflected here — that is `same_file_authed_routers`'s job. Total: never
    raises."""
    stem_counts: dict[str, int] = {}
    for f, _raw in files:
        stem_counts[f.stem] = stem_counts.get(f.stem, 0) + 1

    # (stem, router) -> False as soon as ANY mount of it is unauthed or conditional.
    mounts: dict[tuple[str, str], bool] = {}
    for f, raw in files:
        text = router_code_view(raw, filename=f)
        auth_vars = _auth_dep_list_vars(text, auth_call)
        conditional = _conditional_lines(text, filename=f)
        for m in _INCLUDE_ROUTER_DEPS.finditer(text):
            ref = include_router_ref(text, m.start())
            if ref is None:
                continue
            parts = ref.split(".")
            if len(parts) < 2:
                continue  # a bare-var include is same-file; handled by same_file_authed_routers
            authed = _deps_carry_auth(text, m.start("deps"), m.group("deps"), auth_vars, auth_call)
            if text.count("\n", 0, m.start()) + 1 in conditional:
                authed = False
            key = (parts[-2], parts[-1])
            mounts[key] = mounts.get(key, True) and authed

    # A bare `include_router(<ref>)` with no `dependencies=` at all never matches
    # `_INCLUDE_ROUTER_DEPS` (the pattern requires the kwarg), so the dual-mount case needs its own
    # sweep for the deps-less form — that bare mount is exactly the one that leaves routes open.
    for f, raw in files:
        text = router_code_view(raw, filename=f)
        for start, ref in _include_router_refs(text):
            parts = ref.split(".")
            if len(parts) < 2:
                continue
            key = (parts[-2], parts[-1])
            if key in mounts and not _INCLUDE_ROUTER_DEPS.match(text, start):
                mounts[key] = False

    protected: dict[str, set[str]] = {}
    for (stem, router), authed in mounts.items():
        if authed and stem_counts.get(stem, 0) <= 1:
            protected.setdefault(stem, set()).add(router)
    return protected


# The router object a route decorator is called on — `@admin_router.post("/x")` -> `admin_router`,
# `@app.routers.admin.get(...)` -> `admin` (last dotted segment before the HTTP method).
_ROUTE_RECEIVER = re.compile(
    r"@\s*(?P<var>[\w.]+)\.(?:get|post|put|patch|delete|head|options|websocket)\s*\("
)


def route_receiver(block: str) -> str | None:
    """The router variable name a decorated route in `block` is registered on (last dotted
    segment), or None if `block` has no route decorator. The counterpart to
    `cross_file_authed_routers`: a route is router-level authed iff its receiver is in the
    authed set for that file. Total: never raises."""
    m = _ROUTE_RECEIVER.search(block)
    return m.group("var").split(".")[-1] if m else None


def same_file_authed_routers(
    text: str, *, auth_call: re.Pattern[str] = AUTH_CALL_ANY, filename: str | Path = "<unknown>"
) -> set[str]:
    """Router variable names authed WITHIN one file — constructed with a router-level
    `dependencies=<auth>` (an `APIRouter`/`FastAPI` constructor's `dependencies=` kwarg) or included in
    this same file with one (`app.include_router(router, dependencies=...)`). The deps may be an
    inline list or a variable bound to one. `auth_call` selects what counts as auth (`AUTH_CALL_ANY`
    default; pass `AUTH_CALL_NAMED`/`AUTH_CALL_PRIVILEGED` for the stricter guards), and is a generic
    dependency predicate: `rate_limited_routes` passes `RATE_LIMIT_CALL` (#472). A cross-file
    `module.router` include is NOT resolved here — that is `cross_file_authed_routers`'s job.

    Constructor deps are authoritative: FastAPI applies them on every mount of that router, so no
    later include can undo them. An include-derived auth is NOT — a second, bare
    `include_router(router)` re-mounts the same routes with no dependency, and a mount under an
    `if` may not run at all. Both defeat include-derived protection (#473 review §2).

    "Authoritative" is about MOUNTS, not about REACHABILITY, and conflating the two left a hole:
    a construction under an `if` is no more guaranteed to run than a mount under one, so
    `if flag: router = APIRouter(dependencies=[...])` / `else: router = APIRouter()` was read as
    protection and silenced every route on the router for the whole flag-off configuration. Both
    branches of the rule now use the same `_conditional_lines` test (#473 full gate).
    Total: never raises."""
    text = router_code_view(text, filename=filename)
    auth_vars = _auth_dep_list_vars(text, auth_call)
    conditional = _conditional_lines(text, filename=filename)
    authed: set[str] = set()
    for cm in _ROUTER_CONSTRUCT_DEPS.finditer(text):
        # A construction under an `if` is not guaranteed to run, exactly as a mount under one is
        # not. `if settings.ENABLE_AUTH: router = APIRouter(dependencies=[...])` with an `else:
        # router = APIRouter()` rebinding the same name leaves every route on it open whenever the
        # flag is off. "Constructor deps are authoritative" answers a different question (no later
        # mount can strip them from the router that WAS built); it says nothing about whether this
        # construction is the one that runs.
        if text.count("\n", 0, cm.start()) + 1 in conditional:
            continue
        if _deps_carry_auth(text, cm.start("deps"), cm.group("deps"), auth_vars, auth_call):
            authed.add(cm.group("var"))
    include_authed: dict[str, bool] = {}
    for start, ref in _include_router_refs(text):
        if "." in ref:
            continue  # cross-file; `cross_file_authed_routers`' job
        dm = _INCLUDE_ROUTER_DEPS.match(text, start)
        ok = dm is not None and _deps_carry_auth(
            text, dm.start("deps"), dm.group("deps"), auth_vars, auth_call
        )
        if text.count("\n", 0, start) + 1 in conditional:
            ok = False
        include_authed[ref] = include_authed.get(ref, True) and ok
    authed |= {ref for ref, ok in include_authed.items() if ok}
    return authed


# --- Cross-file FastAPI middleware registration (#954, #472) -----------------------------------
# A control-ABSENCE guard flags a route whose own file lacks the control, but an app normally
# registers its middleware and global controls ONCE, in `main.py`. These primitives answer "is it
# registered, unconditionally, in this route's app scope?". `no-cache-on-sensitive` built them
# privately (#954); they moved here when the #472 guard families became the second caller.


def middleware_scope(root: Path, f: Path) -> str:
    """The top-level directory `f` sits in under `root` (`""` for a root-level file): the unit an
    app-wide control registered in `f` is credited to, so one app's middleware or global limit
    does not cover another app's routes in a monorepo. `""` covers the whole tree, since a
    root-level `main.py` is the app for everything under it. The unit is the DIRECTORY, not the app
    object, so two FastAPI apps in one top-level directory share coverage (the #954 rule, a
    known bypass on each consumer's design doc). Total: a path outside `root` is its own scope."""
    try:
        parts = f.relative_to(root).parts
    except ValueError:
        return str(f)
    return parts[0] if len(parts) > 1 else ""


def conditional_nodes(tree: ast.AST) -> set[int]:
    """`id()` of every node inside an `if`/`else` body. A control registered only when a setting is
    on (`if settings.RATE_LIMIT: app.add_middleware(...)`) is not proof that it runs: the rule
    `_conditional_lines` applies to a conditional `include_router` (#473 review §2)."""
    out: set[int] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.If):
            for stmt in (*node.body, *node.orelse):
                out.update(id(n) for n in ast.walk(stmt))
    return out


def _ast_tail(node: ast.AST) -> str | None:
    """The last name of a `Name` / `Attribute` chain (`SlowAPIMiddleware`, `slowapi.Limiter`)."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return None


def is_http_middleware(decorator: ast.AST) -> bool:
    """`<app>.middleware("http")`: Starlette's decorator form of HTTP middleware, which is itself
    the registration, whether it decorates a function or is called on one."""
    if not (
        isinstance(decorator, ast.Call)
        and _ast_tail(decorator.func) == "middleware"
        and decorator.args
    ):
        return False
    arg = decorator.args[0]
    return isinstance(arg, ast.Constant) and arg.value in ("http", b"http")


def registered_names(call: ast.Call) -> list[str]:
    """The middleware class / function names one call registers: `add_middleware(Cls, ...)`,
    `Middleware(Cls, ...)` (an entry of a `middleware=[...]` list), the class passed by keyword
    instead (Starlette names it `middleware_class=` on `add_middleware` and `cls=` on `Middleware`),
    the `dispatch=fn` keyword of either, and the functional decorator form
    `<app>.middleware("http")(fn)`. A dotted reference (`mw.SecurityHeaders`) yields its last name.
    `[]` for any other call, including a bare constructor call such as `X(app)`: a caller that
    proves coverage from the body of every name returned must not read a response class built with
    `NoStoreResponse(content)` as a registration (#1016 review)."""
    refs: list[ast.AST] = []
    tail = _ast_tail(call.func)
    if tail in ("add_middleware", "Middleware"):
        class_keyword = "middleware_class" if tail == "add_middleware" else "cls"
        refs.extend(call.args[:1])
        refs.extend(k.value for k in call.keywords if k.arg in (class_keyword, "dispatch"))
    elif is_http_middleware(call.func):
        refs.extend(call.args[:1])
    return [n for n in map(_ast_tail, refs) if n]


# Every registration form `registered_names` reads is spelled with the word `middleware`
# (`add_middleware`, `Middleware`, `<app>.middleware("http")`), and a direct ASGI wrap is credited
# only when the wrapping class's own name ends in `middleware`, so a file without the word registers
# nothing. A caller filters on it before keeping a file's text for pass 1 (#771 cost class).
MIDDLEWARE_PREFILTER = re.compile(r"middleware", re.IGNORECASE)


def _wrapped_middleware_name(call: ast.Call) -> str | None:
    """Direct ASGI wrapping, `app = ContentSizeLimitMiddleware(app, ...)`: the wrapping class's
    name, when the class's name ENDS in `middleware` and the app it wraps (the first positional
    argument, else an `app=` keyword) is an expression that can denote an app: a name, an
    attribute or a call. `None` otherwise (#1016 review, rounds 1 and 2), so these are not
    registrations: a zero-argument construction, a bare reference, an ordinary call such as
    `limit(app)`, a class that only CONTAINS the name (`...MiddlewareError('x')`,
    `...MiddlewareConfig(1000)`), and a literal, `None` or `*args` in the app's place. The
    argument's type is not resolved, so an argument that is not an app still credits when it is a
    variable, an attribute or a call (`X(settings)`, `X(settings.app)`, `X(Settings())`): a known
    accepted gap, pinned in the tests. A call cannot simply be rejected, since `X(create_app())`
    is a real wrap. Rare real wraps outside these shapes (an `await`, subscript or conditional
    argument, a name with a suffix after `Middleware`) get no credit, which fails closed."""
    name = _ast_tail(call.func)
    if not name or name in ("add_middleware", "Middleware", "middleware") or not name.lower().endswith("middleware"):
        return None
    wrapped = call.args[0] if call.args else next((k.value for k in call.keywords if k.arg == "app"), None)
    return name if isinstance(wrapped, (ast.Name, ast.Attribute, ast.Call)) else None


def registered_middleware_scopes(
    root: Path, files: list[tuple[Path, str]], names: re.Pattern[str]
) -> set[str]:
    """Pass 1 (repo-wide) for a middleware-ABSENCE guard (#472): the scopes (`middleware_scope`)
    holding an UNCONDITIONAL registration of a middleware whose name `names` matches. The match is
    a `search` on the registered name, so the caller picks exact or substring matching. A
    registration is any form `registered_names` reads (`add_middleware(X, ...)`, a
    `Middleware(X, ...)` list entry, `X` passed as `middleware_class=` / `cls=`, a `dispatch=X`
    keyword, `<app>.middleware("http")(X)`), or a direct ASGI wrap `X(app, ...)` whose class name
    ends in `middleware` and whose wrapped argument is a name, attribute or call
    (`_wrapped_middleware_name`). The wrap is read here and not in
    `registered_names`, because this pass proves coverage by the NAME alone, against the caller's
    own pattern.

    The NAME is the proof here, which suits a known third-party class (a size-limit middleware);
    `no-cache-on-sensitive` instead proves what its middleware's body writes. `files` is every
    PRODUCT file as `(path, text)`, pragma'd ones included (CLAUDE.md rule 4: a pragma gates where
    a finding is anchored, not what this pass reads). A test or example app's middleware never
    runs in front of the product's routes, so callers drop non-product paths first. A mention
    credits nothing: the pass reads the AST, so a commented-out or quoted registration, a bare
    import and an unregistered class definition do not count, and neither does a registration
    under an `if` (`conditional_nodes`). `""` in the result covers the whole tree. Total: an
    unparseable file contributes no scope."""
    covered: set[str] = set()
    for f, text in files:
        scope = middleware_scope(root, f)
        if scope in covered or not MIDDLEWARE_PREFILTER.search(text):
            continue
        tree = safe_ast_parse(text, filename=f)
        if tree is None:
            continue
        conditional = conditional_nodes(tree)
        if any(
            isinstance(node, ast.Call)
            and id(node) not in conditional
            and any(names.search(n) for n in _registrations(node))
            for node in ast.walk(tree)
        ):
            covered.add(scope)
    return covered


def _registrations(call: ast.Call) -> list[str]:
    """Every middleware name `call` registers, for `registered_middleware_scopes`: the
    `registered_names` forms plus a direct ASGI wrap."""
    wrapped = _wrapped_middleware_name(call)
    return registered_names(call) + ([wrapped] if wrapped else [])


# --- Cross-file FastAPI app-wide rate limiting (#472) ------------------------------------------
# The rate-limit-absence guards (`auth-rate-limit-absent`, `llm-rate-limit-absent`) flag a route
# whose own file has no rate-limiting signal, but an app normally wires rate limiting ONCE, in
# `main.py`. `rate_limit_wiring` resolves that per run and `rate_limited_routes` reads it back per
# route file.

# slowapi enforces global limits only through its middleware, and only with a `Limiter` that has
# limits configured: `SlowAPIMiddleware.dispatch` passes a request straight through when the
# limiter is disabled or the route is `@limiter.exempt` / `@limiter.limit`-decorated, and otherwise
# checks `default_limits` + `application_limits` (slowapi 0.1.10 `middleware.py:116-140`,
# `extension.py:614-633`). Neither half alone limits anything.
_SLOWAPI_MIDDLEWARE = frozenset({"SlowAPIMiddleware", "SlowAPIASGIMiddleware"})
_SLOWAPI_LIMIT_KWARGS = frozenset({"default_limits", "application_limits"})
# `enabled=False` makes the middleware a pass-through (`middleware.py:123`); `auto_check=False`
# skips the global check (`middleware.py:43`).
_SLOWAPI_OFF_SWITCHES = frozenset({"enabled", "auto_check"})
# Only a file naming one of these can hold a slowapi registration, a `Limiter` call or an
# app-level dependency, so only those files are AST-parsed (#771 cost class).
_APP_RATE_LIMIT_PREFILTER = re.compile(r"SlowAPI|\bLimiter\s*\(|\bFastAPI\s*\(")
# `@<limiter>.exempt` on a route: slowapi's middleware never limits it.
_SLOWAPI_EXEMPT = re.compile(r"^[ \t]*@[ \t]*[\w.]+\.exempt\b", re.MULTILINE)


def _slowapi_limits_on(call: ast.Call) -> bool:
    """A slowapi `Limiter` call that enforces something: a configured `default_limits=` or
    `application_limits=`, and no off switch. A literal empty value (`[]`, `None`, `""`) is not
    configured. Any other expression is: a name or a settings attribute cannot be resolved
    statically. An off switch voids the call unless it is a truthy constant, because
    `enabled=settings.RATE_LIMIT_ENABLED` is the keyword spelling of `if
    settings.RATE_LIMIT_ENABLED:`, which `conditional_nodes` already refuses to credit."""
    limits = False
    for kw in call.keywords:
        v = kw.value
        if kw.arg in _SLOWAPI_OFF_SWITCHES:
            if not (isinstance(v, ast.Constant) and v.value):
                return False
        elif kw.arg in _SLOWAPI_LIMIT_KWARGS:
            if isinstance(v, ast.List | ast.Tuple | ast.Set):
                limits = limits or bool(v.elts)
            elif isinstance(v, ast.Constant):
                limits = limits or bool(v.value)
            else:
                limits = True
    return limits


def _deps_rate_limited(value: ast.expr, list_vars: set[str]) -> bool:
    """A `dependencies=` value that carries a `RATE_LIMIT_CALL` dependency: an inline list, judged
    per `Depends(...)` call so a string inside the list cannot count, or a name bound to such a
    list (`list_vars`, from `_auth_dep_list_vars`: the #473 rule for a list variable)."""
    if isinstance(value, ast.Name):
        return value.id in list_vars
    return any(
        isinstance(n, ast.Call)
        and _ast_tail(n.func) == "Depends"
        and RATE_LIMIT_CALL.search(ast.unparse(n)) is not None
        for n in ast.walk(value)
    )


class RateLimitWiring(NamedTuple):
    """Where one run wires rate limiting OUTSIDE a route's own file (#472), built by
    `rate_limit_wiring` and read per route file through `rate_limited_routes`."""

    routers: dict[str, set[str]]  # stem -> rate-limited routers (`cross_file_authed_routers`)
    slowapi_scopes: frozenset[str]  # scopes under slowapi global limits (middleware AND limits)
    dependency_scopes: frozenset[str]  # scopes with a rate-limiting app-level `dependencies=`


class RouteRateLimits(NamedTuple):
    """What rate-limits the routes of ONE file: an app-level control reaching all of them
    (`whole_file`), or the router receivers in `routers` (a rate-limited mount or construction)."""

    whole_file: bool
    routers: frozenset[str]


def rate_limit_wiring(root: Path, files: list[tuple[Path, str]]) -> RateLimitWiring:
    """Pass 1 (repo-wide) for the rate-limit-absence guards (#472): the three ways a FastAPI app
    rate-limits a route from OUTSIDE the route's file.

      * **A rate-limited router mount**: `main.py` doing `include_router(auth.router,
        dependencies=[Depends(RateLimiter(...))])`, resolved by `cross_file_authed_routers` with
        `RATE_LIMIT_CALL`, so a dual mount, a conditional mount and a stem collision all stay
        uncovered exactly as they do for auth.
      * **slowapi global limits**: a scope (`middleware_scope`) holding BOTH an unconditional
        `add_middleware(SlowAPIMiddleware)` / `Middleware(SlowAPIMiddleware)` registration AND an
        unconditional `Limiter` call with limits configured and not switched off. Either half
        alone limits nothing.
      * **An app-level dependency**: an unconditional `FastAPI` constructor whose `dependencies=` carries a
        `RATE_LIMIT_CALL`, which every route of that app inherits.

    `files` is every PRODUCT file as `(path, text)`, pragma'd ones included (CLAUDE.md rule 4: a
    pragma gates where a finding is anchored, not what this pass reads). A test or example app is
    no coverage source, so callers drop non-product paths first. A mention credits nothing: the
    router pass reads a comment- and string-blanked view and the scope pass reads the AST, so a
    commented-out registration, a bare import or a class definition does not count. Deliberately
    NOT credited (fail closed): limits set only through app config (`RATELIMIT_DEFAULT`), a
    `Limiter` in a different top-level directory from the middleware, and anything registered
    under an `if`. Total: an unparseable file contributes no scope."""
    # A file that never says `include_router` holds no mount, so the resolver gets its stem only
    # (stem-collision detection needs every file) and skips its string-blanking and AST parse.
    routers = cross_file_authed_routers(
        [(f, text if "include_router" in text else "") for f, text in files],
        auth_call=RATE_LIMIT_CALL,
    )
    middleware: set[str] = set()
    limits: set[str] = set()
    dependency: set[str] = set()
    for f, text in files:
        if not _APP_RATE_LIMIT_PREFILTER.search(text):
            continue
        tree = safe_ast_parse(text, filename=f)
        if tree is None:
            continue
        scope = middleware_scope(root, f)
        conditional = conditional_nodes(tree)
        list_vars: set[str] | None = None
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call) or id(node) in conditional:
                continue
            name = _ast_tail(node.func)
            if name in ("add_middleware", "Middleware"):
                if node.args and _ast_tail(node.args[0]) in _SLOWAPI_MIDDLEWARE:
                    middleware.add(scope)
            elif name == "Limiter":
                if _slowapi_limits_on(node):
                    limits.add(scope)
            elif name == "FastAPI":
                for kw in node.keywords:
                    if kw.arg != "dependencies":
                        continue
                    if list_vars is None:
                        view = router_resolver_view(text, filename=f)
                        list_vars = _auth_dep_list_vars(view, RATE_LIMIT_CALL)
                    if _deps_rate_limited(kw.value, list_vars):
                        dependency.add(scope)
    return RateLimitWiring(routers, frozenset(middleware & limits), frozenset(dependency))


def rate_limited_routes(root: Path, f: Path, text: str, wiring: RateLimitWiring) -> RouteRateLimits:
    """What rate-limits the routes of route file `f` (`text` its source) from outside its own
    lexical signal, per the run's `wiring`. `whole_file` when an app-level dependency covers the
    file's scope, or slowapi global limits do and no route in the file is `@<limiter>.exempt` (the
    middleware never limits an exempt route, and the exemption is not matched to its route, so
    one exempt route withdraws the slowapi credit from the whole file). Otherwise `routers`: the
    receivers whose mount or construction carries a `RATE_LIMIT_CALL` dependency, in this file or
    from `main.py`, matched to each route through `route_receiver`. A root-level control covers
    the whole tree (`middleware_scope`). Total: never raises."""
    scope = middleware_scope(root, f)

    def under(scopes: frozenset[str]) -> bool:
        return scope in scopes or "" in scopes

    if under(wiring.dependency_scopes) or (
        under(wiring.slowapi_scopes) and not _SLOWAPI_EXEMPT.search(text)
    ):
        return RouteRateLimits(True, frozenset())
    routers = same_file_authed_routers(text, auth_call=RATE_LIMIT_CALL, filename=f)
    return RouteRateLimits(False, frozenset(routers | wiring.routers.get(f.stem, set())))


# === helpers: Path classification (what to skip) ============================================================
def is_llm_framework_repo(root: Path, profile: StackProfile) -> bool:
    """True if this repo IS the LLM framework library being developed (not an agent app
    that USES one). Framework source legitimately has all three trifecta legs / agent
    patterns throughout its product code — that's what an LLM framework provides — so the
    LLM/agent guards self-exclude on it.

    Single source of truth (issue #389): the trifecta analyzer
    (`ai/lethal_trifecta.py`, which re-exports this) and the `system_prompt_exposure`,
    `mcp_tool_unverified`, and `tool_chaining_exfil` guards all call this one definition.

    Checks pyproject.tomls at depths 0–2 to handle monorepos (e.g. langchain stores its
    main package at libs/langchain/pyproject.toml, not the workspace root). Total: a
    malformed/crafted pyproject (non-table `[project]`, non-string `name`) yields False
    rather than raising."""
    if not profile.llm_framework:
        return False
    fw_key = profile.llm_framework.lower().replace("-", "").replace("_", "")
    if not fw_key:
        return False

    def _name_matches(pp: Path) -> bool:
        if not pp.is_file():
            return False
        try:
            with pp.open("rb") as fh:
                data = tomllib.load(fh)
        except Exception:
            return False
        # Totality: `[project]` may not be a table and `name` may be a non-string in a
        # crafted/odd pyproject.toml — coerce rather than let `.get`/`.lower` raise.
        proj = data.get("project")
        raw = proj.get("name") if isinstance(proj, dict) else None
        name = raw.lower().replace("-", "").replace("_", "") if isinstance(raw, str) else ""
        return bool(name and fw_key in name)

    # Depth 0: repo root
    if _name_matches(root / "pyproject.toml"):
        return True
    # Depths 1 and 2: monorepo sub-directories, capped to avoid an exhaustive scan.
    candidates = itertools.islice(
        itertools.chain(root.glob("*/pyproject.toml"), root.glob("*/*/pyproject.toml")),
        15,
    )
    return any(_name_matches(pp) for pp in candidates)


_TF_RESOURCE_OPEN = re.compile(r'^\s*resource\s+"(?P<type>[\w-]+)"\s+"(?P<name>[\w-]+)"\s*\{')
# A top-level `provider "type" { ... }` block opener — the single-label sibling of the
# two-label `resource "type" "name" { ... }` form above.
_TF_PROVIDER_OPEN = re.compile(r'^\s*provider\s+"(?P<type>[\w-]+)"\s*\{')
# A double-quoted HCL string literal (with backslash escapes) — its contents must be
# excluded from structural brace counting so a `}` inside a tag value / string doesn't
# truncate a resource block early.
_TF_DQ_STRING = re.compile(r'"(?:\\.|[^"\\])*"')
# A heredoc opener: `attr = <<EOF` / `attr = <<-EOF` (the `-` form allows an indented
# terminator). The heredoc body is free-form text (which routinely contains braces) and must be
# skipped entirely until its terminator line. Anchored to the RHS of an assignment AND
# end-of-line (a heredoc introducer is always the last token on its line) so a stray `<<` that
# survives string/comment stripping — e.g. `count = 1 << 2` — can't open a phantom heredoc that
# never terminates and swallows every following resource to EOF (a silent false negative).
_TF_HEREDOC_OPEN = re.compile(r"=\s*<<-?\s*(?P<tag>\w+)\s*$")


def _tf_line_scan(line: str, heredoc_tag: str | None) -> tuple[int, str | None]:
    """Return `(brace_delta, new_heredoc_tag)` for one Terraform line, counting only
    *structural* braces — those outside double-quoted strings, `#`/`//` line comments, and
    `<<EOF ... EOF` heredoc bodies. An unbalanced `}` inside a string/comment/heredoc used to
    close a resource block prematurely (dropping every attribute below it → false results);
    this keeps depth accurate. Block comments (`/* */`) are not handled (rare in HCL)."""
    if heredoc_tag is not None:
        # Inside a heredoc body: no structural braces; the (optionally indented) terminator
        # line — its content is exactly the tag — ends it.
        if line.strip() == heredoc_tag:
            return 0, None
        return 0, heredoc_tag
    code = _TF_DQ_STRING.sub('""', line)
    code = re.split(r"#|//", code, maxsplit=1)[0]
    delta = code.count("{") - code.count("}")
    opened = _TF_HEREDOC_OPEN.search(code)
    return delta, (opened.group("tag") if opened else None)


_TF_LINE_COMMENT = re.compile(r"#|//")


def _tf_opening_line_inner(line: str, delta: int) -> str:
    """The text after a block's own opening `{` on its declaration line, up to the matching
    `}` when the block also closes there (`delta == 0`). HCL writes a block on one line only
    as `resource "t" "n" { attr = value }` (one attribute, no nested block), so this is that
    attribute. As in `_tf_line_scan`, a brace inside a `"..."` string or a `#`/`//` comment
    is not structural; the string is masked length-preservingly so offsets map back to `line`."""
    masked = _TF_DQ_STRING.sub(lambda m: '"' + " " * (len(m.group()) - 2) + '"', line)
    comment = _TF_LINE_COMMENT.search(masked)
    end = comment.start() if comment else len(masked)
    open_at = masked.find("{", 0, end)
    if open_at < 0:
        return ""
    if delta == 0:
        close_at = masked.rfind("}", open_at, end)
        if close_at > open_at:
            end = close_at
    return line[open_at + 1 : end]


# === helpers: Terraform & IAM policy ========================================================================
def iter_terraform_resources(
    text: str,
) -> list[tuple[str, str, int, list[tuple[int, str]]]]:
    """Yield `(resource_type, resource_name, start_line, body_lines)` for each top-level
    `resource "type" "name" { ... }` block in a Terraform file. `body_lines` is the block's
    own `(lineno, line)` pairs (1-indexed, the opening line included, the closing `}` line
    excluded) so a guard can regex-search for a specific attribute and report its exact line.

    Brace depth is tracked from the resource's own opening line only — a resource nested
    inside another top-level construct (a `module` block, for example) is not resolved
    relative to that outer nesting, since Terraform resources are always top-level. Brace
    counting is string/comment/heredoc aware (see `_tf_line_scan`), so an unbalanced brace
    inside a tag value, comment, or heredoc body does not truncate the block.
    """
    out: list[tuple[str, str, int, list[tuple[int, str]]]] = []
    lines = text.splitlines()
    i = 0
    n = len(lines)
    while i < n:
        m = _TF_RESOURCE_OPEN.match(lines[i])
        if not m:
            i += 1
            continue
        start = i + 1  # 1-indexed
        delta, heredoc_tag = _tf_line_scan(lines[i], None)
        depth = delta
        body: list[tuple[int, str]] = [(start, lines[i])]
        j = i + 1
        while j < n and depth > 0:
            delta, heredoc_tag = _tf_line_scan(lines[j], heredoc_tag)
            depth += delta
            if depth > 0:
                body.append((j + 1, lines[j]))
            j += 1
        out.append((m.group("type"), m.group("name"), start, body))
        i = j
    return out


def literal_bool_state(attr: str, text: str) -> str:
    """`"true"` / `"false"` / `"nonliteral"` (e.g. a variable reference, which cannot be
    proven either way) / `"absent"` for an `attr = ...` boolean attribute anywhere in `text`,
    whether written bare (`attr = true`) or quoted (`attr = "true"` — Terraform coerces a
    quoted `"true"`/`"false"` string to the bool, so both spellings carry the same meaning).
    Use this instead of a bare `attr\\s*=\\s*true` regex whenever a "fire on absence or
    false, stay silent on true" guard needs to also stay silent on a non-literal value —
    firing on `attr = var.x` as though it held the unsafe literal is a recurring
    false-positive class (review doctrine: a suppression/narrowing needs the
    opposite-direction test too). A quoted value counts only when it is exactly `"true"` /
    `"false"` or an interpolation (`"${...}"`, or the `"$(...)"` that `neutralize_interpolations`
    leaves, which reads `"nonliteral"`): any other quoted word (a tag value such as
    `tags = { encrypted = "no" }`) is not this attribute and the search moves past it, so it
    cannot silence a caller (PR #1162 round-3 L-1). The attribute must START its line (after
    indentation), so a same-named key inside a one-line map (`tags = { encrypted = "true" }`)
    is never read as the attribute (round-4 M2). Returns the FIRST matching `attr = ...` in
    `text`; a key inside a MULTI-line map does start its line, so every caller passes the text
    of the one block that owns the attribute -- `top_level_attribute_text` of the code view
    for a resource-level attribute, or a nested block's own inner text. `attr` is a
    fixed caller-supplied name, not user input, but is still `re.escape`d as a matter of hygiene
    (round-2 review: this is the one per-call dynamic pattern in the ReDoS linter's documented
    unresolved-site budget, see `tests/test_regex_redos_safety.py`)."""
    match = re.search(
        rf'(?m)^[ \t]*{re.escape(attr)}[ \t]*=[ \t]*(?:"(true|false)"|"(\$[({{])|([A-Za-z_][\w.]*))',
        text,
    )
    if match is None:
        return "absent"
    word = match.group(1) or match.group(3)
    return word if word in ("true", "false") else "nonliteral"


def top_level_attribute_text(body_text: str) -> str:
    """The TOP-LEVEL lines only of a resource body — any line inside a nested `{ ... }` block
    is excluded, so a same-named attribute inside a nested block (e.g. a
    `default_action { redirect { protocol = "HTTPS" } } }`'s own `protocol`) cannot be
    mistaken for the outer block's own top-level attribute. `body_text` must be built from an
    `iter_terraform_resources` body (the resource's own opening `resource "type" "name" {`
    line included, its closing `}` line excluded) — depth starts at `-1` precisely to absorb
    that one unmatched opening brace from the resource's own declaration line, so its content
    reads as depth 0, not depth 1. Brace counting is string/comment/heredoc aware (via
    `_tf_line_scan`, the same scanner `iter_terraform_resources` itself uses) — round-2
    review: a naive per-line `{`/`}` tally let a brace inside a `#`/`//` comment, a `"..."`
    string, or a `<<EOF` heredoc body close the top-level scope early, silently dropping every
    attribute below it (a false negative) for the rest of the resource.

    The opening line's own attribute is emitted too, as a line of its own: a one-line
    resource (`resource "aws_efs_file_system" "x" { encrypted = true }`) is a body of that
    single line, and dropping it made an encrypted file system read as unencrypted (PR #1162
    round-5 M1). Emitting it on its own line, without the closing `}`, lets a caller's
    `^`-anchored or end-anchored pattern read it exactly as it reads the multi-line form;
    `tests/test_terraform_layout_invariance.py` holds every caller to that."""
    out_lines: list[str] = []
    depth = -1
    heredoc_tag: str | None = None
    for index, line in enumerate(body_text.splitlines()):
        delta, next_heredoc_tag = _tf_line_scan(line, heredoc_tag)
        if depth == 0:
            out_lines.append(line)
        elif index == 0:
            inner = _tf_opening_line_inner(line, delta)
            if inner.strip():
                out_lines.append(inner)
        heredoc_tag = next_heredoc_tag
        depth += delta
    return "\n".join(out_lines)


# IAM/S3 policy STATEMENT parsing — a statement is the innermost `{...}` object that declares
# an `Effect` and is not the policy root (which holds the `Statement` key). Permissive over both
# the JSON (`"Effect":`) and HCL-map (`Effect =`) forms.
_POLICY_EFFECT_KEY = re.compile(r'"?Effect"?\s*[:=]', re.IGNORECASE)
_POLICY_STATEMENT_KEY = re.compile(r'"?Statement"?\s*[:=]', re.IGNORECASE)


def _blank_line_comment(line: str) -> str:
    """Space-fill (length-preserving) a `#`/`//` line comment that begins OUTSIDE a `"..."`
    string, so an odd quote/brace in the comment can't desync a downstream structural walk."""
    in_str = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_str:
            if ch == "\\":
                i += 2
                continue
            if ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch == "#" or (ch == "/" and i + 1 < n and line[i + 1] == "/"):
            return line[:i] + " " * (n - i)
        i += 1
    return line


def _heredoc_body_is_policy(body: str) -> bool:
    """Does this heredoc BODY carry a policy document? Decided by content — it declares an
    `Effect`/`Statement` key — never by the attribute name on the opening line.

    Naming the variable was the #446 defect: `keep_heredoc = "policy" in line.lower()` blanked
    an `admin_doc = <<EOT` (or `local_file` / `aws_ssm_parameter`) body holding a real wildcard
    grant, so the walker returned no statements and `iam-wildcard` went silent on it."""
    return bool(_POLICY_EFFECT_KEY.search(body) or _POLICY_STATEMENT_KEY.search(body))


def blank_policy_noise(text: str) -> str:
    """Space-fill (length- AND newline-preserving) `#`/`//` line comments and the bodies of
    NON-policy heredocs (a `command = <<EOF` provisioner script), so their braces/quotes can't
    desync a structural brace walk. A heredoc whose BODY is a policy document (it declares an
    `Effect`/`Statement`) is KEPT under any attribute name — those JSON braces ARE the policy
    structure. The body is read ahead of the decision, so the whole heredoc is classified
    before a single line of it is emitted."""
    lines = text.split("\n")
    out: list[str] = []
    i = 0
    n = len(lines)
    while i < n:
        code = _blank_line_comment(lines[i])
        out.append(code)
        i += 1
        m = _TF_HEREDOC_OPEN.search(code)
        if not m:
            continue
        tag = m.group("tag")
        body_start = i
        while i < n and lines[i].strip() != tag:
            i += 1
        body = lines[body_start:i]
        if _heredoc_body_is_policy("\n".join(body)):
            out.extend(body)
        else:
            out.extend(" " * len(line) for line in body)
        if i < n:  # the terminator line itself (absent = unterminated heredoc, blanked to EOF)
            out.append(lines[i])
            i += 1
    return "\n".join(out)


def iter_policy_statement_blocks(text: str) -> list[tuple[int, int, str]]:
    """`(start, end, block_text)` for each IAM/S3 policy STATEMENT object in `text`.

    A statement is the innermost `{...}` that declares an `Effect` and is not the policy root
    (which holds `Statement`). STRING-, COMMENT- (`#`/`//`), and HEREDOC-aware: an odd quote or
    brace inside a `Sid` value, a trailing comment, or a non-policy `local-exec` heredoc can't
    unbalance the walk (PR #446 re-review). Offsets index the ORIGINAL `text` (comment/heredoc
    blanking is length/newline-preserving), so a caller can map them to line numbers; the
    returned `block_text` has that noise blanked (its own braces/quotes already can't matter)."""
    src = blank_policy_noise(text)
    blocks: list[tuple[int, int, str]] = []
    stack: list[int] = []
    in_str = False
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if in_str:
            if ch == "\\":
                i += 2
                continue
            if ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch == "{":
            stack.append(i)
        elif ch == "}" and stack:
            s = stack.pop()
            block = src[s : i + 1]
            if _POLICY_EFFECT_KEY.search(block) and not _POLICY_STATEMENT_KEY.search(block):
                blocks.append((s, i + 1, block))
        i += 1
    return blocks


_INTERPOLATION_INNER_STRUCTURE = str.maketrans({"{": "_", "}": "_", "[": "_", "]": "_", '"': "_"})


def neutralize_interpolations(text: str) -> str:
    """Length- and newline-preserving copy of `text` in which every Terraform/HCL `${...}`
    interpolation (and the `$${...}` escape) is rewritten as `$(...)` with the braces, brackets and
    quotes INSIDE it replaced by `_`. Downstream list/map/string scans then cannot be cut short by
    an interpolation's own `}`, `]` or `"` (`"${var.o[0]}"`, `"${lookup({a="b"}, var.k)}"`, a
    multi-line `"${\\n var.o\\n}"`), and `$(` marks a value as not statically evaluable.

    One brace-depth scan, linear: nested braces are counted, not matched by a regex, and an
    unterminated `${` neutralises to the end of the text (#1051 round-4 re-review)."""
    if "${" not in text:
        return text
    out: list[str] = []
    i = 0
    n = len(text)
    while i < n:
        k = text.find("${", i)
        if k < 0:
            out.append(text[i:])
            break
        out.append(text[i:k])
        j = k + 2
        depth = 1
        while j < n and depth:
            ch = text[j]
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
            j += 1
        if depth == 0:  # closed: `${` ... `}` -> `$(` ... `)`
            out.append("$(" + text[k + 2 : j - 1].translate(_INTERPOLATION_INNER_STRUCTURE) + ")")
        else:  # unterminated: neutralise to the end
            out.append("$(" + text[k + 2 : j].translate(_INTERPOLATION_INNER_STRUCTURE))
        i = j
    return "".join(out)


_POLICY_VALUE_CLOSER = {"[": "]", '"': '"'}


def terraform_code_view(text: str) -> str:
    """`text` with its `#`/`//` line comments and non-policy heredoc bodies space-filled
    (`blank_policy_noise`) and every `${...}` interpolation rewritten to `$(...)`
    (`neutralize_interpolations`) -- length- and newline-preserving, so offsets and line numbers
    still index the original. It is the view a Terraform resource guard's block and attribute
    regexes read: a `[^{}]*` block regex cannot be cut short by an interpolation's own `}`
    (`kms_key_id = "${aws_kms_key.k.arn}"`, `host = "${var.host}"`), an attribute written only
    in a comment (`# retention_in_days = 1`, `# mfa_delete = "Enabled"`) is never read as set,
    and a `"$(` value marks an attribute as not statically evaluable. Read a suppress pragma
    from the RAW text, never from this view: the view blanks comments, and a pragma is one."""
    return neutralize_interpolations(blank_policy_noise(text))


def iter_policy_key_values(
    text: str, head: re.Pattern[str]
) -> Iterator[tuple[re.Match[str], str | None]]:
    """`(head_match, value)` for each match of `head` (a policy key plus its `:`/`=` separator,
    e.g. `"?Action"?\\s*[:=]\\s*`; the value starts at `head_match.end()`): `value` is the `[...]`
    list (brackets kept) or `"..."` string that follows, or None when what follows is not a
    list/string literal (a Terraform reference, a function call, a map) or never closes.

    Uncapped AND linear, which a `\\[[^\\]]*\\]` regex is not: that pattern rescans to the end of
    the text from every unterminated `[`, quadratic on a run of them, and the length caps first used
    to bound it were a silent bypass (pad a list past the cap and its `"*"` vanished; PR #1051
    round-4 re-review). Here each value's closer is found with one `str.find`, a head that starts
    inside the previous value is skipped, and once a closer is missing no later value of that kind
    is searched for again. `${...}` interpolations are neutralised first
    (`neutralize_interpolations`), so the returned value is a slice of that neutralised text."""
    text = neutralize_interpolations(text)
    unclosed = {"[": False, '"': False}
    prev_end = -1
    n = len(text)
    for m in head.finditer(text):
        if m.start() < prev_end:
            continue
        i = m.end()
        opener = text[i] if i < n else ""
        closer = _POLICY_VALUE_CLOSER.get(opener)
        if closer is None or unclosed[opener]:
            yield m, None
            continue
        j = text.find(closer, i + 1)
        if j < 0:
            unclosed[opener] = True
            yield m, None
            continue
        prev_end = j + 1
        yield m, text[i : j + 1]


def iter_terraform_provider_blocks(
    text: str,
) -> list[tuple[str, int, list[tuple[int, str]]]]:
    """Yield `(provider_type, start_line, body_lines)` for each top-level `provider "type" { ... }`
    block — the single-label sibling of `iter_terraform_resources()` (which only recognizes the
    two-label `resource` opener). Brace counting is string/comment/heredoc aware via the shared
    `_tf_line_scan`, so an unbalanced `}` inside a string, comment, or `<<EOF` heredoc body does
    not close the provider block prematurely.
    """
    out: list[tuple[str, int, list[tuple[int, str]]]] = []
    lines = text.splitlines()
    i = 0
    n = len(lines)
    while i < n:
        m = _TF_PROVIDER_OPEN.match(lines[i])
        if not m:
            i += 1
            continue
        start = i + 1  # 1-indexed
        delta, heredoc_tag = _tf_line_scan(lines[i], None)
        depth = delta
        body: list[tuple[int, str]] = [(start, lines[i])]
        j = i + 1
        while j < n and depth > 0:
            delta, heredoc_tag = _tf_line_scan(lines[j], heredoc_tag)
            depth += delta
            if depth > 0:
                body.append((j + 1, lines[j]))
            j += 1
        out.append((m.group("type"), start, body))
        i = j
    return out


# `variable "name" { ... }` / `output "name" { ... }` are the single-label siblings of
# `provider "type" { ... }` (one quoted label, not two like `resource`); `locals { ... }` carries
# no label at all. All three are top-level HCL blocks a hardcoded secret can hide in — a
# `variable`'s `default`, a `locals` computed value, an `output`'s `value` — and were invisible to
# this guard before terraform_hardcoded_secret_literal.py only walked `resource`/`provider`
#. Factored into one shared brace-depth walker (identical to the two above, just the
# opener regex differs) rather than three more hand-copied loops.
_TF_VARIABLE_OPEN = re.compile(r'^\s*variable\s+"(?P<name>[\w-]+)"\s*\{')
_TF_LOCALS_OPEN = re.compile(r"^\s*locals\s*\{")
_TF_OUTPUT_OPEN = re.compile(r'^\s*output\s+"(?P<name>[\w-]+)"\s*\{')


def _iter_terraform_blocks_by_opener(
    text: str, opener: re.Pattern[str]
) -> list[tuple[re.Match[str], int, list[tuple[int, str]]]]:
    """Shared brace-depth walk for a top-level HCL block whose OPENING line is matched by
    `opener` (anchored to line start) — yields `(opener_match, start_line, body_lines)`. Same
    string/comment/heredoc-aware walk as `iter_terraform_resources`/`iter_terraform_provider_blocks`
    (via `_tf_line_scan`), just parameterized on the opener so `variable`/`locals`/`output` don't
    each need their own hand-copied loop."""
    out: list[tuple[re.Match[str], int, list[tuple[int, str]]]] = []
    lines = text.splitlines()
    i = 0
    n = len(lines)
    while i < n:
        m = opener.match(lines[i])
        if not m:
            i += 1
            continue
        start = i + 1  # 1-indexed
        delta, heredoc_tag = _tf_line_scan(lines[i], None)
        depth = delta
        body: list[tuple[int, str]] = [(start, lines[i])]
        j = i + 1
        while j < n and depth > 0:
            delta, heredoc_tag = _tf_line_scan(lines[j], heredoc_tag)
            depth += delta
            if depth > 0:
                body.append((j + 1, lines[j]))
            j += 1
        out.append((m, start, body))
        i = j
    return out


def iter_terraform_variable_blocks(
    text: str,
) -> list[tuple[str, int, list[tuple[int, str]]]]:
    """Yield `(variable_name, start_line, body_lines)` for each top-level
    `variable "name" { ... }` block (its `default = ...` is the common home for a leaked
    literal — including a `default = { password = "..." }` object, where the credential-shaped
    key sits on its own line inside the default value)."""
    return [
        (m.group("name"), start, body)
        for m, start, body in _iter_terraform_blocks_by_opener(text, _TF_VARIABLE_OPEN)
    ]


def iter_terraform_locals_blocks(text: str) -> list[tuple[int, list[tuple[int, str]]]]:
    """Yield `(start_line, body_lines)` for each top-level `locals { ... }` block. Unlike
    `variable`/`output`, a `locals` block carries no quoted label."""
    return [(start, body) for _m, start, body in _iter_terraform_blocks_by_opener(text, _TF_LOCALS_OPEN)]


def iter_terraform_output_blocks(
    text: str,
) -> list[tuple[str, int, list[tuple[int, str]]]]:
    """Yield `(output_name, start_line, body_lines)` for each top-level `output "name" { ... }`
    block (its `value = ...` is the common home for a leaked literal)."""
    return [
        (m.group("name"), start, body)
        for m, start, body in _iter_terraform_blocks_by_opener(text, _TF_OUTPUT_OPEN)
    ]


_COMPOSE_SERVICES_KEY = re.compile(r"^(?P<indent>\s*)services\s*:\s*(?:#.*)?$")
_COMPOSE_TOP_KEY = re.compile(r"^(?P<indent>\s*)(?P<name>[A-Za-z0-9_.-]+)\s*:")


# === helpers: Docker Compose ================================================================================
def iter_compose_services(
    text: str,
) -> list[tuple[str, int, list[tuple[int, str]]]]:
    """Yield `(service_name, start_line, body_lines)` for each top-level service block
    under a docker-compose file's `services:` key. `body_lines` is the block's own
    `(lineno, line)` pairs (1-indexed, the service's own `name:` line included, the next
    sibling service excluded) — the compose-file analog of `iter_terraform_resources()`.

    Indent-based (YAML block-mapping form only, not flow `{...}`), matching this
    project's existing compose parsing (`compose_db_port_exposed.py`'s `ports:` tracker,
    `ai_docker.py`'s volume scanners) rather than a real YAML parser, per the zero-runtime-
    dependency architecture. A blank line does not end a block; a line at or above the
    service's own indent does.
    """
    out: list[tuple[str, int, list[tuple[int, str]]]] = []
    lines = text.splitlines()
    n = len(lines)
    services_indent: int | None = None
    service_indent: int | None = None
    i = 0
    while i < n:
        raw = lines[i]
        if not raw.strip():
            i += 1
            continue
        indent = len(raw) - len(raw.lstrip())
        m = _COMPOSE_SERVICES_KEY.match(raw)
        if m:
            services_indent = len(m.group("indent"))
            service_indent = None
            i += 1
            continue
        if services_indent is None:
            i += 1
            continue
        if indent <= services_indent:
            # A line at or above services:'s own indent ends the block — either a
            # sibling top-level key or (if services: was itself nested) an outer close.
            services_indent = None
            service_indent = None
            continue
        if service_indent is None:
            service_indent = indent
        if indent != service_indent:
            # A deeper line belongs to whichever service block is already being
            # collected below; skip here (only entered if services: had no children yet).
            i += 1
            continue
        m2 = _COMPOSE_TOP_KEY.match(raw)
        if not m2:
            i += 1
            continue
        name = m2.group("name")
        start = i + 1
        body: list[tuple[int, str]] = [(start, raw)]
        j = i + 1
        while j < n:
            nxt = lines[j]
            if not nxt.strip():
                body.append((j + 1, nxt))
                j += 1
                continue
            nindent = len(nxt) - len(nxt.lstrip())
            if nindent <= service_indent:
                break
            body.append((j + 1, nxt))
            j += 1
        out.append((name, start, body))
        i = j
    return out
